  function ageFromBirth(value) {
    if (!value) return '';
    const birth = dateAtNoon(value);
    const now = new Date();
    let age = now.getFullYear() - birth.getFullYear();
    const m = now.getMonth() - birth.getMonth();
    if (m < 0 || (m === 0 && now.getDate() < birth.getDate())) age -= 1;
    return age >= 0 && age < 130 ? age : '';
  }

  function profile() { ensureData(); return state.settings.profile; }
  function avatarHtml(size = 'md') {
    const p = profile();
    return p.avatar ? `<img class="v78-avatar v78-avatar-${size}" src="${safe(p.avatar)}" alt="${safe(p.name)}">` : `<span class="v78-avatar v78-avatar-${size} v78-avatar-fallback">${safe(initial(p.name))}</span>`;
  }

  function routeLabel(route) {
    if (route.startsWith('habit-')) return 'Привычка';
    return ({ gamelife:'GameLife', 'review-queue':'Разобрать', goals:'Цели', planner:'Планер', today: 'Сегодня', finance: 'Финансы', 'finance-operations': 'Операции', 'finance-analytics': 'Анализ', 'finance-export': 'Экспорт CSV', 'finance-planning':'Планирование', habits: 'Привычки', information: 'Информация', 'couple-week':'Неделя вдвоём', profile: 'Профиль', debts: 'Обязательства', calendar: 'Календарь', archive: 'Архив', coach: 'Подсказчик', system: 'Настройки' })[route] || route;
  }

  function navItem(route, icon, label) {
    const current = routeNow();
    const informationChild = ['people','notes','ideas','personal','learning','couple-week','polina','trips','wishes','books','films','documents','passwords'].includes(current) || /^(person|note|idea|memory|learning-item)-/.test(current);
    const active = current === route || (route === 'habits' && (current.startsWith('habit-') || current === 'habit-wishlist')) || (route === 'finance' && current.startsWith('finance-')) || (route === 'planner' && current.startsWith('plan-')) || (route === 'information' && informationChild);
    return `<a class="v78-side-link ${active ? 'active' : ''}" href="#${encodeURIComponent(route)}" data-v78-route="${safe(route)}" role="link"><i>${icon}</i><span>${safe(label)}</span></a>`;
  }

  function topTab(route, icon, label) {
    const current = routeNow();
    const active = current === route || (route === 'habits' && (current.startsWith('habit-') || current === 'habit-wishlist')) || (route === 'finance' && current.startsWith('finance-'));
    return `<a class="v78-top-tab ${active ? 'active' : ''}" href="#${encodeURIComponent(route)}" data-v78-route="${route}" role="link"><i>${icon}</i>${label}</a>`;
  }

