  function habitsActive() { return array('habits').filter(h => h.active !== false); }
  function completedHabit(habit, date = todayKey()) { return Boolean(habit?.marks?.[date]); }
  function habitsDone(date = todayKey()) { return habitsActive().filter(h => completedHabit(h, date)).length; }
  function recentDates(days = 7) { return Array.from({ length: days }, (_, index) => addDaysKey(todayKey(), index - (days - 1))); }
  function habitWeekDone(habit) { return recentDates(7).filter(date => completedHabit(habit, date)).length; }
  function todaySuggestionCount() { return habitsDone() < habitsActive().length || !state.discipline.financeChecks?.[todayKey()] ? 1 : 0; }

  function financeSnapshot() {
    const ops = array('operations');
    const key = monthKey(todayKey());
    const monthOps = ops.filter(item => monthKey(operationDate(item)) === key);
    const income = monthOps.filter(item => operationKind(item) === 'income').reduce((s, item) => s + operationAmount(item), 0);
    const expense = monthOps.filter(item => operationKind(item) === 'expense').reduce((s, item) => s + operationAmount(item), 0);
    const balance = number(state.settings.currentBalance);
    const debts = activeDebtsOut();
    const planned = array('purchases').filter(item => item.includeInBudget !== false && monthKey(item.date) === key).reduce((s, item) => s + Math.abs(number(item.amount)), 0);
    return { income, expense, balance, debts, debtTotal: debtOutstandingTotal(debts), planned, available: balance - planned };
  }

  function bestExpensePeriod(){
    const expenses=array('operations').filter(item=>operationKind(item)==='expense');
    const months=[...new Set(expenses.map(item=>monthKey(operationDate(item))).filter(Boolean))].sort().reverse();
    return months[0] || monthKey(todayKey());
  }

  function priorityMeta(value){
    const raw=clean(value).toLowerCase();
    if(/крит|high|важно 1|urgent|сроч/.test(raw)) return {tone:'critical',label:'Критично',order:1};
    if(/выс|high 2|важно|major/.test(raw)) return {tone:'high',label:'Высокий',order:2};
    if(/сред|medium|normal/.test(raw)) return {tone:'medium',label:'Средний',order:3};
    if(/низ|low|later|не сроч/.test(raw)) return {tone:'low',label:'Низкий',order:4};
    return {tone:'medium',label:clean(value)||'Средний',order:3};
  }

  function taskStatusMeta(value){
    const raw=clean(value).toLowerCase();
    if(/вып|done|готов/.test(raw)) return {label:'Выполнено',done:true};
    if(/проц|work|doing/.test(raw)) return {label:'В процессе',done:false};
    return {label:clean(value)||'Запланировано',done:false};
  }

  function expenseClass(valueOrItem){
    const raw=typeof valueOrItem==='object'&&valueOrItem?clean(valueOrItem.expenseClass||valueOrItem.necessity||valueOrItem.requiredType):clean(valueOrItem);
    if(raw==='mandatory'||/обяз|must|required|fixed/.test(raw.toLowerCase()))return 'mandatory';
    if(raw==='optional'||/необяз|optional|wants|discretion/.test(raw.toLowerCase()))return 'optional';
    if(typeof valueOrItem==='object'&&valueOrItem){const row=getFinanceCategory(valueOrItem.category,operationKind(valueOrItem));if(row?.defaultExpenseClass)return row.defaultExpenseClass;}
    return 'optional';
  }
  function expenseClassLabel(value){return expenseClass(value)==='mandatory'?'Обязательный':'Необязательный';}
  function getFinanceCategory(name,kind='expense'){ensureFinanceCategories();const key=financeCategoryKey(name,kind);return state.financeCategories.find(row=>financeCategoryKey(row.name,row.type)===key)||null;}
  function categoryLimit(name){return Math.max(0,number(getFinanceCategory(name,'expense')?.monthlyLimit));}
  function categorySpent(name,period=monthKey(todayKey()),excludeId=''){return array('operations').filter(item=>item.id!==excludeId&&operationKind(item)==='expense'&&monthKey(operationDate(item))===period&&clean(item.category).toLowerCase()===clean(name).toLowerCase()).reduce((sum,item)=>sum+operationAmount(item),0);}
  function categoryData(period = state.settings.v78.categoryPeriod || bestExpensePeriod()) {
    ensureFinanceCategories();
    const expenses = array('operations').filter(item => operationKind(item) === 'expense' && monthKey(operationDate(item)) === period);
    const map = new Map();
    expenses.forEach(item => { const key = clean(item.category||item.group||item.area) || 'Другое'; const current=map.get(key)||{name:key,value:0,count:0,mandatory:0,optional:0};current.value+=operationAmount(item);current.count+=1;current[expenseClass(item)]+=operationAmount(item);map.set(key,current); });
    const rows = [...map.values()].map(row=>{const category=getFinanceCategory(row.name,'expense');const limit=Math.max(0,number(category?.monthlyLimit));const remaining=limit?limit-row.value:0;const percent=limit?Math.round(row.value/limit*100):0;return {...row,limit,remaining,percent,defaultExpenseClass:category?.defaultExpenseClass||'optional',icon:category?.icon||'•',color:category?.color||'#8b5cf6'};}).sort((a, b) => b.value - a.value);
    const sum = rows.reduce((total, row) => total + row.value, 0);
    const mandatory=expenses.filter(item=>expenseClass(item)==='mandatory').reduce((total,item)=>total+operationAmount(item),0);
    const optional=expenses.filter(item=>expenseClass(item)==='optional').reduce((total,item)=>total+operationAmount(item),0);
    return { rows, sum, period, count:expenses.length,mandatory,optional };
  }
  function financePeriodData(period=state.settings.v78.categoryPeriod||bestExpensePeriod()){
    const ops=array('operations').filter(item=>monthKey(operationDate(item))===period);const incomes=ops.filter(item=>operationKind(item)==='income'),expenses=ops.filter(item=>operationKind(item)==='expense');
    const income=incomes.reduce((sum,item)=>sum+operationAmount(item),0),expense=expenses.reduce((sum,item)=>sum+operationAmount(item),0),mandatory=expenses.filter(item=>expenseClass(item)==='mandatory').reduce((sum,item)=>sum+operationAmount(item),0),optional=expense-mandatory,net=income-expense;
    const categories=categoryData(period);const configured=financeCategories('expense',true).filter(row=>number(row.monthlyLimit)>0);const totalLimit=configured.reduce((sum,row)=>sum+number(row.monthlyLimit),0);const limitSpent=configured.reduce((sum,row)=>sum+categorySpent(row.name,period),0);const over=categories.rows.filter(row=>row.limit&&row.value>row.limit);const near=categories.rows.filter(row=>row.limit&&row.value<=row.limit&&row.percent>=80);
    return {period,ops,incomes,expenses,income,expense,mandatory,optional,net,savingsRate:income?Math.round(net/income*100):0,categories,totalLimit,limitSpent,limitRemaining:totalLimit-limitSpent,over,near};
  }
  function previousPeriod(period){const d=new Date(`${period}-01T12:00:00`);d.setMonth(d.getMonth()-1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;}
  function financeAssistant(period=state.settings.v78.categoryPeriod||bestExpensePeriod()){
    const data=financePeriodData(period),tips=[];const noLimits=financeCategories('expense').filter(row=>number(row.monthlyLimit)<=0).length;
    data.over.forEach(row=>tips.push({tone:'danger',title:`Лимит «${row.name}» превышен`,text:`Потрачено ${moneyText(row.value)} при лимите ${moneyText(row.limit)}. Превышение: ${moneyText(row.value-row.limit)}.`,route:'finance-operations'}));
    data.near.forEach(row=>tips.push({tone:'warning',title:`«${row.name}» — ${row.percent}% лимита`,text:`Осталось ${moneyText(Math.max(0,row.remaining))}. Следующий необязательный расход лучше отложить.`,route:'finance-operations'}));
    if(data.income&&data.expense>data.income)tips.push({tone:'danger',title:'Расходы выше доходов',text:`Отрицательный денежный поток: ${moneyText(Math.abs(data.net))}. Сначала остановите необязательные траты.`,route:'finance-analytics'});
    if(data.income&&data.optional/data.income>.3)tips.push({tone:'warning',title:'Высокая доля необязательных расходов',text:`${Math.round(data.optional/data.income*100)}% дохода ушло на необязательные покупки. Проверьте крупнейшие категории.`,route:'finance-analytics'});
    if(noLimits)tips.push({tone:'info',title:'Не все категории имеют лимит',text:`Без лимита осталось ${noLimits} ${plural(noLimits,'категория','категории','категорий')}. Настройте их, чтобы помощник мог предупреждать заранее.`,action:'categories'});
    if(!tips.length)tips.push({tone:'success',title:'Финансы под контролем',text:`Лимиты не превышены. Чистый денежный поток: ${moneyText(data.net)}.`,route:'finance-analytics'});
    return {data,tips};
  }
  function financeAssistantHtml(period=state.settings.v78.categoryPeriod||bestExpensePeriod(),limit=5){const assistant=financeAssistant(period);return `<section class="v867-finance-assistant"><header><div><small>ФИНАНСОВЫЙ ПОМОЩНИК</small><h2>Контроль денег</h2><p>Помощник следит за лимитами, обязательными расходами и денежным потоком.</p></div><i>✦</i></header><div>${assistant.tips.slice(0,limit).map(tip=>`<article class="${tip.tone}"><i>${tip.tone==='danger'?'!':tip.tone==='warning'?'⚠':tip.tone==='success'?'✓':'i'}</i><span><b>${safe(tip.title)}</b><small>${safe(tip.text)}</small></span>${tip.action==='categories'?`<button data-v866-action="open-finance-categories" type="button">Настроить</button>`:`<button data-v78-route="${tip.route||'finance-analytics'}" type="button">Открыть</button>`}</article>`).join('')}</div></section>`;}

  function donutStyle(rows, sum) {
    if (!sum || !rows.length) return 'background:conic-gradient(#eee 0 100%)';
    const colors = ['#8b5cf6','#44c7b1','#ff9b73','#ffc857','#6aa9ff','#f783ac','#7fd1ae','#a6a1ff'];
    let cursor = 0;
    const parts = rows.slice(0, 8).map((row, index) => { const start = cursor; cursor += row.value / sum * 100; return `${colors[index % colors.length]} ${start.toFixed(2)}% ${cursor.toFixed(2)}%`; });
    if (cursor < 100) parts.push(`#edf0f7 ${cursor.toFixed(2)}% 100%`);
    return `background:conic-gradient(${parts.join(',')})`;
  }

  function habitChips(limit = 9) {
    const habits = habitsActive().slice(0, limit);
    return `<div class="v78-habit-chip-grid">${habits.map(habit => `<button class="v78-habit-chip ${completedHabit(habit) ? 'done' : ''}" data-v78-action="toggle-habit" data-id="${safe(habit.id)}" type="button"><i style="--habit:${safe(habit.color)}">${safe(habit.icon)}</i><span><b>${safe(habit.name)}</b><small>${completedHabit(habit) ? 'выполнено сегодня' : `${habit.target} ${safe(habit.unit)}`}</small></span><em>${completedHabit(habit) ? '✓' : '○'}</em></button>`).join('')}<button class="v78-habit-chip add" data-v78-action="open-habit-form" type="button"><i>＋</i><span><b>Добавить привычку</b><small>новая страница и отметки</small></span></button></div>`;
  }

  function foldersPanel() {
    const finance = financeSnapshot();
    const debtQuality = debtDataQuality(finance.debts);
    const debtSubtitle = debtQuality.total && debtQuality.complete < debtQuality.total ? `Долги · уточнить ${debtQuality.total-debtQuality.complete} ${plural(debtQuality.total-debtQuality.complete,'остаток','остатка','остатков')}` : 'Долги · Платежи · Источники';
    const infoCount = array('people').length + array('notes').length + array('wishes').length + array('books').length;
    return `<article class="v78-folder-panel"><header><h2>Мои папки</h2><button data-v78-action="open-search" type="button">＋</button></header><div class="v78-folder-stack">
      ${folderCard('habits', 'folder-violet', 'Привычки', 'Дисциплина · Привычки · Интервью', `<span><small>Сегодня</small><b>${habitsDone()}/${habitsActive().length}</b></span><span><small>Неделя</small><b>${habitsActive().length ? Math.round(habitsActive().reduce((s,h)=>s+habitWeekDone(h),0)/(habitsActive().length*7)*100) : 0}%</b></span>`, '✓')}
      ${folderCard('finance', 'folder-green', 'Финансы', 'Операции · Аналитика · Цели', `<span><small>Баланс</small><b>${safe(moneyText(finance.balance))}</b></span><span><small>Расходы</small><b>${safe(moneyText(finance.expense))}</b></span>`, '₽')}
      ${folderCard('debts', 'folder-coral', 'Обязательства', debtSubtitle, `<span><small>К оплате</small><b>${finance.debts.length}</b></span><span><small>Сумма</small><b>${safe(moneyText(finance.debtTotal))}</b></span>`, '!')}
      ${folderCard('information', 'folder-blue', 'Информация', 'Люди · Заметки · Желания · Библиотека', `<span><small>Люди</small><b>${array('people').length}</b></span><span><small>Всего</small><b>${infoCount}</b></span>`, 'i')}
      <button class="v78-archive-row" data-v78-route="archive" type="button"><i>▣</i><span>Архив</span><b>${array('archive').length} ${plural(array('archive').length,'запись','записи','записей')}</b><em>›</em></button>
    </div></article>`;
  }

  function folderCard(route, tone, title, subtitle, stats, icon) {
    return `<button class="v78-folder-card ${tone}" data-v78-route="${route}" type="button" aria-label="Открыть: ${safe(title)}"><i class="v78-folder-icon" data-sbos-static-icon="true" aria-hidden="true"><span>${icon}</span></i><span class="v78-folder-copy"><b>${title}</b><small>${subtitle}</small><em class="v78-folder-stats">${stats}</em></span><strong aria-hidden="true">›</strong></button>`;
  }

  function obligationsMini() {
    const debts = activeDebtsOut();
    const rows = debts.slice(0, 2).map(item => `<div class="v78-obligation-row"><i>${/банк|кредит|займ/i.test(clean(item.person || item.note)) ? '▱' : '◇'}</i><span><b>${safe(item.person || 'Обязательство')}</b><small>${item.due ? `до ${formatShort(item.due)}` : 'срок не указан'}</small></span><em>${safe(moneyText(debtOutstanding(item)))}</em></div>`).join('');
    return card('Мои обязательства', `${debts.length} ${plural(debts.length,'активное','активных','активных')}`, `${rows || '<div class="v78-empty">Активных обязательств нет.</div>'}<button class="v78-link-button" data-v78-route="debts" type="button">Все обязательства →</button>`, 'v78-obligations-card');
  }

  const INTERVIEW_QUESTION_SETS = [
    ['Что я сейчас на самом деле чувствую, если не пытаться это исправить?','Какое действие я откладываю и чего именно в нём избегаю?','Какой самый маленький честный шаг вернёт мне движение сегодня?'],
    ['Где сегодня я действую из страха, а не из своих ценностей?','Что я пытаюсь контролировать, хотя могу отпустить?','Как я могу поддержать себя без поблажек и самокритики?'],
    ['Какая мысль сегодня забирает у меня больше всего энергии?','Что в этой мысли является фактом, а что моей интерпретацией?','Какое действие возможно даже при сохранении этой тревоги?'],
    ['Что я обещал себе, но снова перенёс?','Какую скрытую выгоду я получаю от бездействия?','Как упростить задачу до действия на пять минут?'],
    ['Где я сейчас предаю собственный приоритет ради быстрого удовольствия?','Какую цену я плачу за это через неделю или месяц?','Какой выбор сегодня подтвердит, кем я хочу стать?'],
    ['Что в моём дне действительно важно, а что создаёт только видимость занятости?','От чего я могу отказаться сегодня без реального ущерба?','Какое одно дело сделает день завершённым?'],
    ['Какая эмоция стоит за моими импульсивными расходами или желаниями?','Что мне хочется получить через покупку на эмоциональном уровне?','Как удовлетворить эту потребность без вреда для финансов?'],
    ['Что помогло мне вчера двигаться, даже если день был неидеальным?','Какой контекст или сигнал стоит повторить сегодня?','Что я отмечу как маленькую победу вечером?'],
    ['Где я жду мотивации вместо того, чтобы создать условия?','Что можно подготовить заранее, чтобы начать было легче?','Во сколько и после какого события я выполню действие?'],
    ['Какая часть меня сопротивляется дисциплине и от чего она меня защищает?','Что этой части важно услышать от меня?','Как совместить заботу о себе и выполнение обещания?'],
    ['Что я сейчас усложняю сильнее, чем требуется?','Как выглядела бы достаточно хорошая версия результата?','Что я закончу сегодня без дальнейшего улучшения?'],
    ['Что я хочу изменить в своей жизни, но поддерживаю ежедневными действиями обратное?','Какое повторяющееся действие создаёт это противоречие?','Чем я заменю его сегодня хотя бы один раз?'],
    ['Какая незакрытая ситуация постоянно занимает фон моего внимания?','Что зависит от меня в этой ситуации прямо сейчас?','Какое сообщение, решение или действие закроет следующий шаг?'],
    ['Что сегодня вызвало у меня раздражение или защитную реакцию?','Какая потребность или граница за этим стоит?','Как выразить её спокойно и прямо?']
  ];
  function interviewQuestions(date=todayKey()){
    const day=Math.floor(dateAtNoon(date).getTime()/DAY); return INTERVIEW_QUESTION_SETS[Math.abs(day)%INTERVIEW_QUESTION_SETS.length];
  }
  function todayInterview(){return array('subconsciousEntries').find(e=>String(e.date||'').slice(0,10)===todayKey());}
  function interviewCard() {
    const session=todayInterview(),questions=interviewQuestions();
    return card('Интервью с подсознанием', session?'Сегодняшнее интервью сохранено':'Каждый день — три новых вопроса', `<div class="v80-interview-preview"><div><span class="v80-daily-tag">${session?'✓ Пройдено сегодня':'Вопрос дня'}</span><p>${safe(questions[0])}</p><button class="v78-primary" data-v78-route="subconscious" type="button">${session?'Открыть ответы':'Начать интервью'} <i>→</i></button></div><div class="v80-mind-art"><i></i><b></b><em></em><span>✦</span></div></div>`, 'v78-interview-card v80-interview-card');
  }

  function assistantCard() {
    const undone = habitsActive().filter(h => !completedHabit(h));
    const suggestion = undone.length ? `Сегодня достаточно одного маленького шага: ${undone[0].name}.` : 'Привычки на сегодня закрыты. Можно спокойно подвести итог дня.';
    return card('Подсказчик AI', 'Ваш личный советник', `<div class="v78-assistant-body"><div><p>${safe(suggestion)}</p><button class="v78-primary" data-v78-route="coach" type="button">Спросить совет <i>→</i></button></div><div class="v78-robot"><i></i><b>••</b><em></em></div></div>`, 'v78-assistant-card');
  }

  function wishlistCard() {
    const rows = state.habitWishlist.slice(0, 4).map(item => `<div class="v78-wish-row"><i>${safe(item.icon || '✦')}</i><span><b>${safe(item.title)}</b><small>${safe(item.schedule || 'На следующую неделю')}</small></span><button data-v78-action="promote-wishlist" data-id="${safe(item.id)}" type="button">＋</button></div>`).join('');
    return card('Вишлист привычек', 'Следующие 4 недели', `${rows || '<div class="v78-empty">Вишлист пока пуст.</div>'}<button class="v78-link-button" data-v78-route="habit-wishlist" type="button">Смотреть все идеи →</button>`, 'v78-wishlist-card');
  }

  function categoryMini() {
    const data = categoryData();
    return card('Анализ по категориям', new Date(`${data.period}-01T12:00:00`).toLocaleDateString('ru-RU',{month:'long',year:'numeric'}), `<div class="v78-category-layout"><div class="v78-donut" style="${donutStyle(data.rows,data.sum)}"><span><b>${safe(moneyText(data.sum))}</b><small>расходы</small></span></div><div class="v78-category-list">${data.rows.slice(0,6).map((row,index)=>`<div><i class="c${index}"></i><span>${safe(row.name)}</span><b>${data.sum?Math.round(row.value/data.sum*100):0}%</b></div>`).join('') || '<p>Расходов пока нет.</p>'}</div></div><button class="v78-link-button" data-v78-route="finance-analytics" type="button">Полный анализ →</button>`, 'v78-category-card');
  }

  function operationsFolderMini() {
    const ops = array('operations');
    const income = ops.filter(item => operationKind(item) === 'income').length;
    const expense = ops.filter(item => operationKind(item) === 'expense').length;
    return card('Папка операций', 'Все финансовые записи в одном месте', `<div class="v78-operation-folder"><button data-v78-route="finance-operations" type="button"><i>▦</i><span>Все операции</span><b>${ops.length}</b></button><button data-v78-route="finance-operations" data-v78-filter="income" type="button"><i>↗</i><span>Доходы</span><b>${income}</b></button><button data-v78-route="finance-operations" data-v78-filter="expense" type="button"><i>↘</i><span>Расходы</span><b>${expense}</b></button><button data-v79-action="open-record-form" data-type="operation" type="button"><i>＋</i><span>Новая операция</span><b>добавить</b></button></div>`, 'v78-operations-folder');
  }

  function financeHero() {
    const f = financeSnapshot();
    return `<article class="v78-card v78-finance-hero"><header><div><h2>Финансы сегодня</h2><p>Факты, операции и понятная структура денег</p></div><div class="v78-chip-actions"><button data-v78-route="finance-operations" type="button">Операции</button><button data-v78-route="finance-export" type="button">Экспорт CSV</button></div></header><div class="v78-finance-hero-body"><div class="v78-finance-numbers"><div><b class="positive">+ ${safe(moneyText(f.income))}</b><small>Доходы месяца</small></div><div><b class="negative">− ${safe(moneyText(f.expense))}</b><small>Расходы месяца</small></div><div class="balance"><small>Фактический баланс</small><strong>${safe(moneyText(f.balance))}</strong><button data-v79-action="set-actual-balance" type="button">Изменить</button></div></div><div class="v78-pie-art"><i></i><i></i><i></i><i></i></div></div></article>`;
  }

  function todayPage() {
    const done = habitsDone();
    const habits = habitsActive();
    const habitsCard = card('Все привычки', `${habits.length} активных · можно отметить прямо здесь`, `<div class="v78-week-strip">${recentDates(7).map(date=>`<span class="${date===todayKey()?'today':''}"><small>${dateAtNoon(date).toLocaleDateString('ru-RU',{weekday:'short'}).toUpperCase()}</small><b>${dateAtNoon(date).getDate()}</b></span>`).join('')}</div>${habitChips(9)}<div class="v78-card-footer"><span>${done}/${habits.length} выполнено сегодня</span><button data-v78-action="mark-all-habits" type="button">Отметить все</button><button data-v78-route="habits" type="button">Открыть все привычки →</button></div>`, 'v78-all-habits');
    return `${gameLifeTodayStrip()}${dailyAutomationStrip()}<section class="v103-home-grid" aria-label="Главная панель">
      <div class="v103-home-habits">${habitsCard}</div>
      <div class="v103-home-finance">${financeHero()}</div>
      <div class="v103-home-folders">${foldersPanel()}</div>
      <div class="v103-home-interview">${interviewCard()}</div>
      <div class="v103-home-ai">${assistantCard()}</div>
      <div class="v103-home-operations">${operationsFolderMini()}</div>
      <div class="v103-home-obligations">${obligationsMini()}</div>
      <div class="v103-home-analysis">${categoryMini()}</div>
      <div class="v103-home-next-week">${wishlistWeekGrid()}</div>
    </section>`;
  }

  function wishlistWeekGrid() {
    const items = state.habitWishlist.slice(0, 4);
    return card('Привычки на следующую неделю', `${items.length} запланировано`, `<div class="v78-week-wishlist">${items.map((item,index)=>`<button data-v78-route="habit-wishlist" type="button"><small>${['ПН','ВТ','СР','ЧТ'][index] || '•'}</small><i>${safe(item.icon||'✦')}</i><b>${safe(item.title)}</b><span>${safe(item.schedule||'')}</span></button>`).join('') || '<div class="v78-empty">Добавьте идеи во вишлист.</div>'}</div><button class="v78-link-button" data-v78-route="habit-wishlist" type="button">Настроить следующую неделю →</button>`, 'v78-next-week');
  }

  function habitsPage() {
    const habits = habitsActive();
    const done = habitsDone();
    const progress = habits.length ? Math.round(done / habits.length * 100) : 0;
    const left=Math.max(0,habits.length-done);
    const stability=habits.length?Math.round(habits.reduce((sum,habit)=>sum+habitWeekDone(habit),0)/(habits.length*7)*100):0;
    return `<section class="v78-page v82-habits-page"><header class="v78-page-head"><div><span>Система дисциплины</span><h1>Привычки</h1><p>Карточки одинакового размера, быстрые отметки и отдельная страница для каждой привычки.</p></div><div><button class="v78-secondary" data-v78-action="open-habit-form" type="button">＋ Новая привычка</button><button class="v78-primary" data-v78-action="mark-all-habits" type="button">✦ Отметить все сегодня</button></div></header>
      <section class="v869-habit-overview"><div class="v869-progress-orbit" style="--progress:${progress}"><div class="v869-progress-inner"><b>${done}/${habits.length}</b><small>сегодня</small><span>${progress}%</span></div><i class="spark one">✦</i><i class="spark two">✦</i></div><div class="v869-habit-copy"><span class="v82-eyebrow">ПРОГРЕСС ДНЯ</span><h2>${done===habits.length&&habits.length?'Все привычки выполнены':'День в движении'}</h2><p>${done===habits.length&&habits.length?'Отличный результат. Система закрыта на сегодня — лучше закрепить ритм, чем добавлять новые обязательства.':'Круг показывает выполненную часть дня. Отмечайте привычки без перегруза и удерживайте устойчивость.'}</p></div><div class="v869-habit-stats"><article><small>Выполнено</small><b>${done}</b><span>из ${habits.length}</span></article><article><small>Осталось</small><b>${left}</b><span>${left?'на сегодня':'всё закрыто'}</span></article><article><small>Стабильность</small><b>${stability}%</b><span>за 7 дней</span></article></div></section>
      <section class="v78-habit-cards v82-habit-grid">${habits.map(habitCard).join('') || '<div class="v78-empty-big">Добавьте первую привычку.</div>'}</section>
      <section class="v78-habit-support-grid">${interviewCard()}${assistantCard()}${wishlistCard()}</section>
    </section>`;
  }

  function habitCard(habit) {
    const week = habitWeekDone(habit), percent = Math.round(week / 7 * 100), done = completedHabit(habit);
    return `<article class="v82-habit-card ${done?'is-done':''}" style="--habit:${safe(habit.color)}">
      <header><button class="v82-habit-main" data-v78-route="habit-${encodeURIComponent(habit.id)}" type="button"><span class="v82-habit-icon">${safe(habit.icon)}</span><span><b>${safe(habit.name)}</b><small>${safe(habit.frequency)} · ${habit.target} ${safe(habit.unit)}</small></span><em>›</em></button><button class="v82-habit-settings" title="Настроить привычку" data-v78-action="edit-habit" data-id="${safe(habit.id)}" type="button">✎</button></header>
      <div class="v82-habit-meter"><div><span>Последние 7 дней</span><b>${week}/7</b></div><u><i style="width:${percent}%"></i></u><small>${percent}% стабильности${linkedGoalsForHabit(habit).length?` · ${linkedGoalsForHabit(habit).length} ${plural(linkedGoalsForHabit(habit).length,'цель','цели','целей')}`:''}</small></div>
      <footer><button class="v82-complete-button ${done?'done':''}" data-v78-action="toggle-habit" data-id="${safe(habit.id)}" type="button"><span>${done?'✓':'✦'}</span><div><b>${done?'Выполнено':'Отметить сегодня'}</b><small>${done?'Нажмите, чтобы отменить':'Сохранить результат дня'}</small></div></button></footer>
    </article>`;
  }

  function habitPage(id) {
    const habit = array('habits').find(item => item.id === id);
    if (!habit) return `<section class="v78-page"><div class="v78-empty-big">Привычка не найдена.<button data-v78-route="habits">Вернуться к привычкам</button></div></section>`;
    const days = /чтен/i.test(habit.name) ? 42 : 28;
    const dates = Array.from({length:days},(_,index)=>addDaysKey(todayKey(), index-(days-1)));
    const completed = dates.filter(date=>completedHabit(habit,date)).length;
    const best = longestStreak(habit);
    const reading = /чтен/i.test(habit.name);
    const sessions = reading ? state.discipline.sessions.slice().sort((a,b)=>String(b.date).localeCompare(String(a.date))) : [];
    return `<section class="v78-page"><header class="v78-page-head"><div><button class="v78-back" data-v78-route="habits" type="button">← Все привычки</button><span>Отдельная страница привычки</span><h1>${safe(habit.icon)} ${safe(habit.name)}</h1><p>${safe(habit.note || 'Последовательное повторение и честная фиксация результата.')}</p></div><div><button class="v80-delete-button" data-v80-action="delete-habit" data-id="${safe(habit.id)}" type="button">Удалить</button><button class="v78-secondary" data-v78-action="edit-habit" data-id="${safe(habit.id)}" type="button">Настроить</button><button class="v78-primary" data-v78-action="toggle-habit" data-id="${safe(habit.id)}" type="button">${completedHabit(habit)?'✓ Сегодня закрыто':'Отметить сегодня'}</button></div></header>
      <section class="v78-kpi-row"><article><small>Выполнено</small><b>${completed}/${days}</b><span>за выбранный период</span></article><article><small>Последние 7 дней</small><b>${habitWeekDone(habit)}/7</b><span>стабильность, не серия</span></article><article><small>Лучшая серия</small><b>${best} дн.</b><span>без обнуления мотивации</span></article><article><small>Цель</small><b>${habit.target} ${safe(habit.unit)}</b><span>${safe(habit.frequency)}</span></article></section>
      ${card(`Карта повторений · ${days} дней`, 'Нажмите на любой день, чтобы изменить отметку.', `<div class="v78-habit-calendar">${dates.map(date=>`<button class="${completedHabit(habit,date)?'done':''} ${date===todayKey()?'today':''}" data-v78-action="toggle-habit-date" data-id="${safe(habit.id)}" data-date="${date}" type="button"><b>${dateAtNoon(date).getDate()}</b><small>${dateAtNoon(date).toLocaleDateString('ru-RU',{month:'short'})}</small></button>`).join('')}</div>`, 'v78-habit-calendar-card')}
      <section class="v78-two-cols">${reading ? readingDetailCard(habit, sessions) : habitNotesCard(habit)}${card('Связанные цели',linkedGoalsForHabit(habit).length?`${linkedGoalsForHabit(habit).length} активных связей`:'Привычка самостоятельна',linkedGoalsForHabit(habit).length?`<div class="v865-linked-goals">${linkedGoalsForHabit(habit).map(goal=>`<button data-v78-route="goal-${encodeURIComponent(goal.id)}" type="button"><i>${goal.type==='process'?'↻':goal.type==='maintenance'?'🛡️':'🎯'}</i><span><b>${safe(goal.title)}</b><small>${goalExecutionLabel(goalExecutionMode(goal))} · ${goalDisplayProgress(goal)}%</small></span><em>›</em></button>`).join('')}</div><button class="v78-link-button" data-v78-action="edit-habit" data-id="${safe(habit.id)}" type="button">Изменить связи →</button>`:`<div class="v865-empty-links"><span>Эта привычка пока не привязана к цели — это нормально.</span><button class="v78-secondary" data-v78-action="edit-habit" data-id="${safe(habit.id)}" type="button">Связать с целью</button></div>`,'v865-habit-goals-card')}</section>
    </section>`;
  }

  function longestStreak(habit) {
    const dates = Object.keys(habit.marks || {}).filter(date => habit.marks[date]).sort();
    let best = 0, current = 0, previous = '';
    dates.forEach(date => { if (previous && Math.round((dateAtNoon(date)-dateAtNoon(previous))/DAY)===1) current += 1; else current = 1; best = Math.max(best,current); previous=date; });
    return best;
  }

  function readingDetailCard(habit, sessions) {
    const totalMinutes = sessions.reduce((s,item)=>s+number(item.minutes),0);
    const resistance = sessions.filter(item=>item.resistance!==''&&item.resistance!=null).map(item=>number(item.resistance));
    const avg = resistance.length ? (resistance.reduce((s,v)=>s+v,0)/resistance.length).toFixed(1) : '—';
    return card('Эксперимент: чтение', '42 дня · фактические действия', `<div class="v78-reading-stats"><div><small>Общее время</small><b>${Math.floor(totalMinutes/60)} ч ${totalMinutes%60} мин</b></div><div><small>Среднее сопротивление</small><b>${avg}/10</b></div><div><small>Сессий</small><b>${sessions.length}</b></div></div><div class="v78-session-list">${sessions.slice(0,6).map(item=>`<div><i>${item.mode==='minimum'?'5':'20'}</i><span><b>${formatShort(item.date)} · ${number(item.minutes)} мин</b><small>${safe(item.note||'Без заметки')}</small></span></div>`).join('') || '<div class="v78-empty">Первая сессия появится после отметки.</div>'}</div>`, 'v78-reading-detail');
  }

  function habitNotesCard(habit) {
    return card('Контекст привычки', 'Сделайте начало максимально простым', `<div class="v78-context-list"><div><small>Когда</small><b>${safe(habit.cue || 'Укажите сигнал в настройках')}</b></div><div><small>Где</small><b>${safe(habit.place || 'Укажите место в настройках')}</b></div><div><small>Минимальная версия</small><b>${Math.max(1,Math.round(habit.target/4))} ${safe(habit.unit)}</b></div></div>`, 'v78-context-card');
  }

  function informationPage() {
    const groups = [
      ['people','👥','Люди','Контакты, отношения и важный контекст',array('people')],
      ['notes','📝','Заметки','Мысли, решения, планы и наблюдения',array('notes')],
      ['wishes','💗','Желания','Мечты, цели и идеи для будущего',array('wishes')],
      ['ideas','💡','Идеи','Все задумки и возможные проекты',array('ideas')],
      ['personal','🌿','Личная память','Дневник, события и личные записи',array('personal')],
      ['polina','🌸','Состояние Полины','Календарь состояния и цикла',array('polinaDays')],
      ['documents','📄','Документы','Файлы, ссылки и важные материалы',array('documents')],
      ['books','📚','Книги','Книги, цитаты и конспекты',array('books')],
      ['films','🎬','Фильмы','Фильмы, сериалы и список просмотра',array('films')],
      ['trips','✈️','Путешествия','Маршруты, поездки и идеи',array('trips')],
      ['passwords','🔐','Пароли и доступы','Зашифрованное личное хранилище',Array.isArray(state.passwordVault)?state.passwordVault:[]],
      ['inbox','📥','Входящие','Несортированные мысли на разбор',array('inbox')]
    ];
    return `<section class="v78-page"><header class="v78-page-head"><div><span>Архив и необязательные разделы</span><h1>Информация</h1><p>На каждой карточке сразу видно, что лежит внутри. Открывать всё подряд больше не нужно.</p></div><div><button class="v78-secondary" data-v78-action="open-search" type="button">⌕ Найти информацию</button><button class="v78-primary" data-v79-action="open-quick" type="button">＋ Добавить</button></div></header><section class="v78-information-grid">${groups.map(infoFolder).join('')}</section></section>`;
  }

  function infoFolder([route,icon,title,subtitle,items]) {
    const previews = items.slice(0,3).map(item=>clean(item.title||item.name||item.person||item.text||item.note||item.date)).filter(Boolean);
    return `<button class="v78-info-folder" data-v78-route="${route}" type="button"><i>${icon}</i><span><b>${title}</b><small>${subtitle}</small><em>${previews.length ? previews.map(value=>`<mark>${safe(value.slice(0,34))}</mark>`).join('') : '<mark>Пока пусто</mark>'}</em></span><strong>${items.length}<small>${plural(items.length,'элемент','элемента','элементов')}</small></strong><u>›</u></button>`;
  }

  function financePage() {
    const f = financeSnapshot();
    const period=monthKey(todayKey()),flow=financePeriodData(period),plans=financePlanData(period);
    return `<section class="v78-page"><header class="v78-page-head"><div><span>Финансовая осознанность</span><h1>Финансы</h1><p>Доходы, обязательные и необязательные расходы, лимиты категорий, планирование и полный денежный поток.</p></div><div><button class="v78-secondary" data-v866-action="open-finance-categories" type="button">◌ Категории и лимиты</button><button class="v78-secondary" data-v85-action="import-bank-csv" type="button">⇧ Импорт CSV</button><button class="v78-secondary" data-v79-action="set-actual-balance" type="button">Изменить баланс</button><button class="v78-primary" data-v79-action="open-record-form" data-type="operation" type="button">＋ Операция</button></div></header>
      <section class="v78-finance-folders v869-finance-folders">${financeFolder('finance-operations','▦','Операции',`${array('operations').length} записей`,`Доходы, расходы, обязательность и комментарии`)}${financeFolder('finance-analytics','◌','Полная аналитика',safe(moneyText(flow.expense)),'Лимиты, движение денег и сравнение периодов')}${financeFolder('finance-planning','◷','Планирование',safe(moneyText(plans.planned)),'Расходы будущих месяцев и прогноз остатка')}${financeFolder('finance-export','⇩','CSV-центр','Импорт и выгрузка','Банк CSV, удаление дублей и проверка строк')}${financeFolder('debts','!','Источники долгов',safe(moneyText(f.debtTotal)),`${f.debts.length} активных обязательств — каждая сумма объяснена`)}</section>
      <section class="v78-kpi-row"><article><small>Фактический баланс</small><b>${safe(moneyText(f.balance))}</b><span>указанный остаток</span></article><article><small>Доходы месяца</small><b class="positive">${safe(moneyText(flow.income))}</b><span>${flow.incomes.length} операций</span></article><article><small>Обязательные расходы</small><b class="negative">${safe(moneyText(flow.mandatory))}</b><span>${flow.expense?Math.round(flow.mandatory/flow.expense*100):0}% всех расходов</span></article><article><small>Необязательные расходы</small><b>${safe(moneyText(flow.optional))}</b><span>${flow.expense?Math.round(flow.optional/flow.expense*100):0}% всех расходов</span></article></section>
      ${financeAssistantHtml(period,4)}
      <section class="v867-finance-overview"><article><small>Чистый денежный поток</small><b class="${flow.net>=0?'positive':'negative'}">${flow.net>=0?'+':''}${safe(moneyText(flow.net))}</b><span>доходы минус расходы</span></article><article><small>Настроено лимитов</small><b>${safe(moneyText(flow.totalLimit))}</b><span>${financeCategories('expense').filter(row=>number(row.monthlyLimit)>0).length} категорий</span></article><article><small>Запланировано</small><b>${safe(moneyText(plans.planned))}</b><span>${plans.items.filter(item=>item.status==='planned').length} будущих расходов</span></article><article><small>Категорий с превышением</small><b class="${flow.over.length?'negative':''}">${flow.over.length}</b><span>${flow.near.length} близко к лимиту</span></article></section>
      <section class="v78-two-cols">${operationsFolderMini()}${categoryMini()}</section>
      ${card('Прозрачные обязательства', 'Сумма не берётся из воздуха — ниже показаны все источники.', debtSourceRows(), 'v78-debt-source')}
    </section>`;
  }

  function financeFolder(route, icon, title, value, subtitle) {
    return `<button class="v78-finance-folder" data-v78-route="${route}" type="button"><i>${icon}</i><span><small>${title}</small><b>${value}</b><em>${subtitle}</em></span><strong>›</strong></button>`;
  }

  function debtSourceRows() {
    const debts = activeDebtsOut();
    return `<div class="v78-source-list">${debts.map(item=>`<button data-v78-route="debts" type="button"><i>!</i><span><b>${safe(item.person||'Обязательство')}</b><small>${safe(item.note||'Без комментария')}${item.due?` · срок ${formatShort(item.due)}`:''}</small></span><em>${safe(moneyText(debtOutstanding(item)))}</em></button>`).join('') || '<div class="v78-empty">Активных долгов и обязательств нет.</div>'}</div><div class="v78-source-total"><span>Итого из ${debts.length} ${plural(debts.length,'источника','источников','источников')}</span><b>${safe(moneyText(debtOutstandingTotal(debts)))}</b></div>`;
  }

  function financeOperationsPage() {
    const all = array('operations').slice().sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')) || String(b.createdAt||'').localeCompare(String(a.createdAt||'')));
    let filtered = all.filter(item => operationType === 'all' || operationKind(item) === operationType);
    if (operationQuery) {
      const q = operationQuery.toLowerCase();
      filtered = filtered.filter(item => [item.date,item.type,item.amount,item.category,item.account,item.note,item.incomeSource].some(value=>String(value||'').toLowerCase().includes(q)));
    }
    const pages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
    operationPage = Math.min(operationPage, pages);
    const start = (operationPage - 1) * PAGE_SIZE;
    const visible = filtered.slice(start, start + PAGE_SIZE);
    const categories=[...new Map(filtered.filter(item=>operationKind(item)==='expense').map(item=>[clean(item.category)||'Другое',0])).keys()];
    const catStats=categoryData(state.settings.v78.categoryPeriod || bestExpensePeriod());
    state.settings.v78.operationPage = operationPage;
    state.settings.v78.operationType = operationType;
    return `<section class="v78-page"><header class="v78-page-head"><div><button class="v78-back" data-v78-route="finance" type="button">← Финансы</button><span>Папка финансов</span><h1>Операции</h1><p>Полный список без обрезания. На одной странице отображается ${PAGE_SIZE} операций.</p></div><div><button class="v78-secondary" data-v866-action="open-finance-categories" type="button">Категории</button><button class="v78-secondary" data-v85-action="import-bank-csv" type="button">⇧ Импорт CSV из банка</button><button class="v78-secondary" data-v81-action="open-category-editor" type="button">Переименовать CSV</button><button class="v78-secondary" data-v78-action="export-csv" data-scope="filtered" type="button">⇩ Экспорт списка</button><button class="v78-primary" data-v79-action="open-record-form" data-type="operation" type="button">＋ Операция</button></div></header>
      <section class="v78-operation-toolbar"><div class="v78-segment">${[['all','Все'],['income','Доходы'],['expense','Расходы']].map(([key,label])=>`<button class="${operationType===key?'active':''}" data-v78-action="operation-type" data-type="${key}" type="button">${label}</button>`).join('')}</div><label>⌕<input data-v78-operation-search value="${safe(operationQuery)}" placeholder="Категория, сумма, комментарий..."></label><span>${filtered.length} ${plural(filtered.length,'операция','операции','операций')}</span></section>
      <section class="v81-category-hint"><div><b>Редактирование категорий после CSV стало понятнее</b><p>«Импорт CSV из банка» загружает новую выписку с предварительной проверкой и удалением дублей. «Категории» управляют справочником, а «Переименовать CSV» меняет старое название сразу во всей выписке.</p></div><div class="v81-category-pills">${catStats.rows.slice(0,6).map(row=>`<button data-v81-action="open-category-editor" data-from="${safe(row.name)}" type="button">${safe(row.name)} <small>${Math.round(row.value)}</small></button>`).join('') || '<span>Категории появятся после расходных операций</span>'}</div></section>
      <section class="v78-operation-table"><header><span>Дата</span><span>Тип</span><span>Категория</span><span>Комментарий / счёт</span><span>Сумма</span><span></span></header>${visible.map(operationRow).join('') || '<div class="v78-empty-big">Операций по выбранному фильтру нет.</div>'}</section>
      <footer class="v78-pagination"><span>Страница ${operationPage} из ${pages}</span><div><button data-v78-action="operation-page" data-page="${Math.max(1,operationPage-1)}" ${operationPage===1?'disabled':''} type="button">←</button>${paginationButtons(operationPage,pages).map(page=>`<button class="${page===operationPage?'active':''}" data-v78-action="operation-page" data-page="${page}" type="button">${page}</button>`).join('')}<button data-v78-action="operation-page" data-page="${Math.min(pages,operationPage+1)}" ${operationPage===pages?'disabled':''} type="button">→</button></div></footer>
    </section>`;
  }

  function paginationButtons(current, pages) {
    const set = new Set([1,pages,current-1,current,current+1]);
    return [...set].filter(page=>page>=1&&page<=pages).sort((a,b)=>a-b);
  }

  function operationRow(item) {
    const income = operationKind(item) === 'income';const necessity=income?'':expenseClass(item);
    return `<article><span>${safe(formatShort(item.date))}</span><span><i class="${income?'income':'expense'}">${income?'↗':'↘'}</i>${income?'Доход':'Расход'}</span><span><b>${safe(item.category||'Без категории')}</b><small>${income?'доходная запись':`<mark class="v867-necessity ${necessity}">${expenseClassLabel(necessity)}</mark>`}</small></span><span><b>${safe(item.note||'Без комментария')}</b><small>${safe(item.account||item.incomeSource||'')}</small></span><strong class="${income?'positive':'negative'}">${income?'+':'−'} ${safe(moneyText(item.amount))}</strong><span class="v78-row-menu v81-row-menu"><button data-v81-action="quick-category" data-id="${safe(item.id)}" type="button">Категория</button><button data-v79-action="edit-record" data-type="operation" data-id="${safe(item.id)}" type="button">Изменить</button><button class="danger" data-v79-action="delete-record" data-type="operation" data-id="${safe(item.id)}" type="button">Удалить</button></span></article>`;
  }

  function financeAnalyticsPage() {
    const period=state.settings.v78.categoryPeriod||bestExpensePeriod(),data=financePeriodData(period),months=[...new Set(array('operations').map(item=>monthKey(operationDate(item))).filter(Boolean))].sort().reverse();const prev=financePeriodData(previousPeriod(period));const categoryRows=financeCategories('expense',true).map(category=>{const spent=categorySpent(category.name,period),old=categorySpent(category.name,previousPeriod(period)),limit=number(category.monthlyLimit),remaining=limit-spent,percent=limit?Math.round(spent/limit*100):0;return {category,spent,old,limit,remaining,percent,count:array('operations').filter(item=>operationKind(item)==='expense'&&monthKey(operationDate(item))===period&&clean(item.category).toLowerCase()===clean(category.name).toLowerCase()).length};}).filter(row=>row.spent||row.limit).sort((a,b)=>b.spent-a.spent);
    return `<section class="v78-page"><header class="v78-page-head"><div><button class="v78-back" data-v78-route="finance" type="button">← Финансы</button><span>Полная финансовая аналитика</span><h1>Движение денег</h1><p>Доходы, расходы, лимиты, обязательность, динамика категорий и рекомендации помощника.</p></div><div><select class="v78-select" data-v78-category-period>${months.map(key=>`<option value="${key}" ${key===period?'selected':''}>${new Date(`${key}-01T12:00:00`).toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}</option>`).join('')||`<option value="${monthKey(todayKey())}">Текущий месяц</option>`}</select><button class="v78-secondary" data-v866-action="open-finance-categories" type="button">Категории и лимиты</button><button class="v78-primary" data-v78-route="finance-operations" type="button">Операции</button></div></header>
      <section class="v867-analytics-kpis"><article><small>Доходы</small><b class="positive">${safe(moneyText(data.income))}</b><span>${data.incomes.length} операций</span></article><article><small>Все расходы</small><b class="negative">${safe(moneyText(data.expense))}</b><span>${data.expenses.length} операций</span></article><article><small>Чистый поток</small><b class="${data.net>=0?'positive':'negative'}">${data.net>=0?'+':''}${safe(moneyText(data.net))}</b><span>изменение к прошлому: ${safe(moneyText(data.net-prev.net))}</span></article><article><small>Норма сбережений</small><b class="${data.savingsRate>=0?'positive':'negative'}">${data.savingsRate}%</b><span>чистый поток / доходы</span></article></section>
      <section class="v867-necessity-analysis"><article class="mandatory"><header><i>🛡</i><div><small>Обязательные расходы</small><h2>${safe(moneyText(data.mandatory))}</h2></div></header><p>То, без чего нельзя нормально выполнять обязательства: жильё, базовые продукты, здоровье, долги и другие выбранные вами траты.</p><footer><b>${data.expense?Math.round(data.mandatory/data.expense*100):0}% расходов</b><span>${data.income?Math.round(data.mandatory/data.income*100):0}% дохода</span></footer></article><article class="optional"><header><i>✨</i><div><small>Необязательные расходы</small><h2>${safe(moneyText(data.optional))}</h2></div></header><p>Покупки и развлечения, которые можно перенести, сократить или заменить без нарушения обязательств.</p><footer><b>${data.expense?Math.round(data.optional/data.expense*100):0}% расходов</b><span>${data.income?Math.round(data.optional/data.income*100):0}% дохода</span></footer></article><article class="limits"><header><i>◌</i><div><small>Общий лимит категорий</small><h2>${safe(moneyText(data.totalLimit))}</h2></div></header><p>Потрачено ${safe(moneyText(data.limitSpent))}. Осталось ${safe(moneyText(Math.max(0,data.limitRemaining)))}.</p><footer><b>${data.totalLimit?Math.round(data.limitSpent/data.totalLimit*100):0}% использовано</b><span>${data.over.length} превышено</span></footer></article></section>
      ${financeAssistantHtml(period,8)}
      <section class="v867-category-budget"><header><div><h2>Категории, лимиты и динамика</h2><p>Каждая строка показывает расход, лимит, остаток, обязательность и изменение к прошлому месяцу.</p></div><button data-v866-action="open-finance-categories" type="button">Настроить лимиты</button></header><div class="v867-budget-table"><div class="head"><span>Категория</span><span>Тип по умолчанию</span><span>Расход</span><span>Лимит</span><span>Использовано</span><span>Остаток</span><span>К прошлому месяцу</span></div>${categoryRows.map(row=>`<article class="${row.limit&&row.spent>row.limit?'over':row.percent>=80?'near':''}"><span><i style="background:${safe(row.category.color)}20;color:${safe(row.category.color)}">${safe(row.category.icon)}</i><b>${safe(row.category.name)}</b><small>${row.count} ${plural(row.count,'операция','операции','операций')}</small></span><span><mark class="v867-necessity ${row.category.defaultExpenseClass}">${expenseClassLabel(row.category.defaultExpenseClass)}</mark></span><strong>${safe(moneyText(row.spent))}</strong><span>${row.limit?safe(moneyText(row.limit)):'Не задан'}</span><span><u><b style="width:${Math.min(100,row.percent)}%"></b></u><em>${row.limit?`${row.percent}%`:'—'}</em></span><span class="${row.limit&&row.remaining<0?'negative':''}">${row.limit?safe(moneyText(row.remaining)):'—'}</span><span class="${row.spent-row.old>0?'negative':row.spent-row.old<0?'positive':''}">${row.spent-row.old>0?'+':''}${safe(moneyText(row.spent-row.old))}</span></article>`).join('')||'<div class="v78-empty-big">Задайте лимиты категориям или добавьте расходы.</div>'}</div></section>
      <section class="v867-cashflow-history"><header><h2>Движение денег по месяцам</h2><p>Последние 6 месяцев: доходы, расходы и чистый результат.</p></header><div>${[...new Set(array('operations').map(item=>monthKey(operationDate(item))).filter(Boolean))].sort().reverse().slice(0,6).reverse().map(key=>{const row=financePeriodData(key),max=Math.max(row.income,row.expense,1);return `<article><span><b>${new Date(`${key}-01T12:00:00`).toLocaleDateString('ru-RU',{month:'short',year:'2-digit'})}</b><small class="${row.net>=0?'positive':'negative'}">${row.net>=0?'+':''}${safe(moneyText(row.net))}</small></span><div><i class="income" style="width:${row.income/max*100}%"></i><i class="expense" style="width:${row.expense/max*100}%"></i></div><em><small>Доход ${safe(moneyText(row.income))}</small><small>Расход ${safe(moneyText(row.expense))}</small></em></article>`}).join('')}</div></section>
    </section>`;
  }

  function categoryComparison(period) {
    const d = new Date(`${period}-01T12:00:00`); d.setMonth(d.getMonth()-1); const previous = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
    const currentData = categoryData(period); const prevData = categoryData(previous); const prevMap = new Map(prevData.rows.map(row=>[row.name,row.value]));
    return `<div class="v78-comparison-list">${currentData.rows.slice(0,8).map(row=>{const old=prevMap.get(row.name)||0; const diff=row.value-old; return `<div><span><b>${safe(row.name)}</b><small>было ${safe(moneyText(old))}</small></span><em class="${diff>0?'negative':diff<0?'positive':''}">${diff>0?'+':''}${safe(moneyText(diff))}</em></div>`}).join('') || '<div class="v78-empty">Недостаточно операций для сравнения.</div>'}</div>`;
  }

  function financeExportPage() {
    const ops = array('operations');
    const cats = categoryData(state.settings.v78.categoryPeriod || bestExpensePeriod());
    const dupeless = new Set(ops.map(operationSignature)).size;
    return `<section class="v78-page"><header class="v78-page-head"><div><button class="v78-back" data-v78-route="finance" type="button">← Финансы</button><span>Импорт и выгрузка данных</span><h1>CSV-центр</h1><p>Здесь можно и выгрузить весь список операций, и загрузить банковскую выписку без дублей.</p></div></header>
      <section class="v85-export-grid">
        <article class="v85-export-card"><small>Экспорт операций</small><h2>${ops.length} ${plural(ops.length,'операция','операции','операций')} готовы к выгрузке</h2><p>Файл сохраняется в CSV UTF-8 с разделителем «;». Экспорт включает все даты, страницы, категории, комментарии и счета.</p><div class="v85-export-stats"><article><small>Всего записей</small><b>${ops.length}</b><span>в полном файле</span></article><article><small>Уникальных</small><b>${dupeless}</b><span>без возможных дублей</span></article><article><small>Категорий</small><b>${cats.rows.length}</b><span>используются в аналитике</span></article></div><div class="v85-export-checks"><span>✓ Полный список</span><span>✓ UTF‑8</span><span>✓ Excel compatible</span><span>✓ Комментарии и счёт</span></div><div class="v85-export-actions"><button class="v78-primary" data-v78-action="export-csv" data-scope="all" type="button">Скачать полный CSV</button><button class="v78-secondary" data-v78-action="export-csv" data-scope="filtered" type="button">Скачать текущий список</button></div></article>
        <article class="v85-export-card"><small>Импорт из банка</small><h2>Загрузить банковскую выписку</h2><p>Поддерживаются CSV‑файлы банковских выписок. Система распознаёт дату, сумму, комментарий и черновую категорию, а перед импортом показывает превью.</p><div class="v85-import-note">Во время импорта автоматически удаляются дубли из файла и уже существующие операции. После импорта можно быстро редактировать категорию у любой строки.</div><div class="v85-export-actions"><button class="v78-primary" data-v85-action="import-bank-csv" type="button">⇧ Импортировать CSV</button><button class="v78-secondary" data-v866-action="open-finance-categories" type="button">Категории</button><button class="v78-secondary" data-v81-action="open-category-editor" type="button">Переименовать CSV</button></div></article>
      </section>
      <section class="v81-category-hint"><div><b>Категории из CSV</b><p>Если банк прислал «нечеловеческие» категории, откройте редактор и переименуйте их сразу у всей выписки. Для точечной правки у каждой операции есть кнопка «Категория».</p></div><div class="v81-category-pills">${cats.rows.slice(0,8).map(row=>`<button data-v81-action="open-category-editor" data-from="${safe(row.name)}" type="button">${safe(row.name)} <small>${Math.round(row.value)}</small></button>`).join('') || '<span>Категории появятся после расходных операций</span>'}<button class="accent" data-v81-action="open-category-editor" type="button">Открыть редактор</button></div></section>
      ${card('Предпросмотр последних операций', 'Сам файл будет содержать весь список.', `<div class="v78-export-preview">${ops.slice().sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).slice(0,8).map(item=>`<div><span>${formatShort(item.date)}</span><b>${safe(item.category||'Без категории')}</b><em class="${item.type==='income'?'positive':'negative'}">${item.type==='income'?'+':'−'} ${safe(moneyText(item.amount))}</em></div>`).join('') || '<div class="v78-empty">Операций нет.</div>'}</div>`, 'v78-export-preview-card')}
    </section>`;
  }


  function v869SafeFinanceRoute(factory,route){
    try{return factory();}catch(error){console.error('[V86.9 finance route]',route,error);return `<section class="v78-page"><header class="v78-page-head"><div><button class="v78-back" data-v78-route="today" type="button">← Главная</button><span>Безопасный режим финансов</span><h1>Финансы открыты</h1><p>Часть старых записей вызвала ошибку отображения, но данные сохранены. Вы можете открыть операции, планирование, аналитику или категории.</p></div></header><section class="v869-finance-recovery"><button data-v78-route="finance-operations" type="button"><i>▦</i><b>Операции</b><span>Открыть список и редактирование</span></button><button data-v78-route="finance-planning" type="button"><i>◷</i><b>Планирование</b><span>Будущие месяцы</span></button><button data-v78-route="finance-analytics" type="button"><i>◌</i><b>Аналитика</b><span>Движение денег</span></button><button data-v866-action="open-finance-categories" type="button"><i>₽</i><b>Категории и лимиты</b><span>Настроить справочник</span></button></section><div class="v869-finance-error"><b>Техническая причина сохранена в консоли.</b><span>${safe(error?.message||String(error))}</span></div></section>`;}
  }
  function addMonthsPeriod(period,delta){const d=new Date(`${period}-01T12:00:00`);d.setMonth(d.getMonth()+number(delta));return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;}
  function financePlanMonth(){const raw=clean(state.settings?.v869?.planMonth);return /^\d{4}-\d{2}$/.test(raw)?raw:monthKey(todayKey());}
  function financePlanItems(period=financePlanMonth()){return array('financePlans').filter(item=>item.month===period).slice().sort((a,b)=>number(a.dueDay)-number(b.dueDay)||String(a.createdAt).localeCompare(String(b.createdAt)));}
  function financePlanData(period=financePlanMonth()){
    const items=financePlanItems(period),active=items.filter(item=>item.status!=='cancelled'),plannedItems=active.filter(item=>item.status==='planned'),paidItems=active.filter(item=>item.status==='paid');
    const planned=plannedItems.reduce((sum,item)=>sum+number(item.amount),0),paid=paidItems.reduce((sum,item)=>sum+number(item.amount),0),mandatory=plannedItems.filter(item=>expenseClass(item)==='mandatory').reduce((sum,item)=>sum+number(item.amount),0),optional=planned-mandatory;
    const actual=financePeriodData(period),balance=number(state.settings.currentBalance),projectedBalance=balance-planned;
    const categoryMap=new Map();plannedItems.forEach(item=>{const key=clean(item.category)||'Прочее';const row=categoryMap.get(key)||{name:key,planned:0,mandatory:0,optional:0,count:0};row.planned+=number(item.amount);row[expenseClass(item)]+=number(item.amount);row.count+=1;categoryMap.set(key,row);});
    const categories=[...categoryMap.values()].map(row=>{const category=getFinanceCategory(row.name,'expense'),limit=number(category?.monthlyLimit),actualSpent=categorySpent(row.name,period),projected=actualSpent+row.planned;return {...row,limit,actualSpent,projected,remaining:limit-projected,percent:limit?Math.round(projected/limit*100):0,icon:category?.icon||'•',color:category?.color||'#8b5cf6'};}).sort((a,b)=>b.projected-a.projected);
    return {period,items,plannedItems,paidItems,planned,paid,mandatory,optional,actual,projectedBalance,categories};
  }
  function financePlanningPage(){
    ensureFinanceCategories();const period=financePlanMonth(),data=financePlanData(period),label=new Date(`${period}-01T12:00:00`).toLocaleDateString('ru-RU',{month:'long',year:'numeric'}),future=period>monthKey(todayKey());
    const rows=data.items.map(item=>`<article class="v869-plan-row ${item.status}"><span class="date"><b>${item.dueDay}</b><small>${new Date(`${period}-${String(Math.min(item.dueDay,new Date(Number(period.slice(0,4)),Number(period.slice(5,7)),0).getDate())).padStart(2,'0')}T12:00:00`).toLocaleDateString('ru-RU',{weekday:'short'})}</small></span><i>${safe(getFinanceCategory(item.category,'expense')?.icon||'•')}</i><span class="copy"><b>${safe(item.title)}</b><small>${safe(item.category)} · ${expenseClassLabel(item.expenseClass)}${item.note?` · ${safe(item.note)}`:''}</small></span><strong>${safe(moneyText(item.amount))}</strong><mark class="v867-necessity ${expenseClass(item)}">${expenseClassLabel(item.expenseClass)}</mark><span class="status">${item.status==='paid'?'Проведён':item.status==='cancelled'?'Отменён':'Запланирован'}</span><div class="actions"><button data-v869-action="edit-plan" data-id="${safe(item.id)}" type="button">Изм</button>${item.status==='planned'?`<button class="primary" data-v869-action="post-plan" data-id="${safe(item.id)}" type="button">Провести</button>`:''}<button data-v869-action="copy-plan" data-id="${safe(item.id)}" type="button">В след. месяц</button><button class="danger" data-v869-action="delete-plan" data-id="${safe(item.id)}" type="button">Удалить</button></div></article>`).join('');
    return `<section class="v78-page"><header class="v78-page-head"><div><button class="v78-back" data-v78-route="finance" type="button">← Финансы</button><span>Планирование движения денег</span><h1>Расходы по месяцам</h1><p>Вносите будущие траты заранее, разделяйте обязательные и необязательные расходы и проверяйте, укладывается ли месяц в лимиты.</p></div><div><button class="v78-secondary" data-v869-action="shift-plan-month" data-delta="-1" type="button">←</button><input class="v869-month-input" type="month" value="${period}" data-v869-plan-month><button class="v78-secondary" data-v869-action="shift-plan-month" data-delta="1" type="button">→</button><button class="v78-primary" data-v869-action="open-plan-form" type="button">＋ Запланировать расход</button></div></header>
      <section class="v869-plan-hero"><div><small>${future?'БУДУЩИЙ МЕСЯЦ':'ТЕКУЩИЙ МЕСЯЦ'}</small><h2>${label}</h2><p>${data.plannedItems.length?`В плане ${data.plannedItems.length} ${plural(data.plannedItems.length,'расход','расхода','расходов')}. Помощник учитывает категории, лимиты и обязательность.`:'План пока пуст. Добавьте известные расходы, чтобы заранее увидеть нагрузку на деньги.'}</p></div><div class="v869-plan-orb"><b>${safe(moneyText(data.planned))}</b><span>ещё предстоит</span></div></section>
      <section class="v869-plan-kpis"><article><small>Запланировано</small><b>${safe(moneyText(data.planned))}</b><span>не проведено</span></article><article><small>Обязательные</small><b class="negative">${safe(moneyText(data.mandatory))}</b><span>${data.planned?Math.round(data.mandatory/data.planned*100):0}% плана</span></article><article><small>Необязательные</small><b>${safe(moneyText(data.optional))}</b><span>${data.planned?Math.round(data.optional/data.planned*100):0}% плана</span></article><article><small>Прогноз остатка</small><b class="${data.projectedBalance>=0?'positive':'negative'}">${safe(moneyText(data.projectedBalance))}</b><span>текущий баланс минус будущие траты</span></article></section>
      <section class="v869-planning-grid"><article class="v869-plan-list"><header><div><h2>План расходов</h2><p>Нажмите «Провести», когда расход действительно произошёл — он попадёт в операции и аналитику.</p></div><button data-v869-action="open-plan-form" type="button">＋ Добавить</button></header><div>${rows||'<div class="v78-empty-big">На этот месяц запланированных расходов нет.</div>'}</div></article><article class="v869-plan-categories"><header><h2>Категории и будущая нагрузка</h2><p>Факт + ещё не проведённый план.</p></header><div>${data.categories.map(row=>`<article class="${row.limit&&row.projected>row.limit?'over':row.percent>=80?'near':''}"><span><i style="background:${safe(row.color)}20;color:${safe(row.color)}">${safe(row.icon)}</i><span><b>${safe(row.name)}</b><small>факт ${safe(moneyText(row.actualSpent))} + план ${safe(moneyText(row.planned))}</small></span></span><strong>${safe(moneyText(row.projected))}</strong><u><b style="width:${Math.min(100,row.percent)}%"></b></u><em>${row.limit?`${row.percent}% лимита · остаток ${safe(moneyText(row.remaining))}`:'лимит не задан'}</em></article>`).join('')||'<div class="v78-empty">Категории появятся после добавления плана.</div>'}</div><button class="v78-link-button" data-v866-action="open-finance-categories" type="button">Настроить категории и лимиты →</button></article></section>
      ${financePlanningAssistantHtml(data)}
    </section>`;
  }
  function financePlanningAssistantHtml(data){const tips=[];data.categories.filter(row=>row.limit&&row.projected>row.limit).forEach(row=>tips.push({tone:'danger',title:`Будущий лимит «${row.name}» превышен`,text:`Факт и план составят ${moneyText(row.projected)} при лимите ${moneyText(row.limit)}. Уберите или перенесите ${moneyText(row.projected-row.limit)}.`}));data.categories.filter(row=>row.limit&&row.projected<=row.limit&&row.percent>=80).forEach(row=>tips.push({tone:'warning',title:`«${row.name}» займёт ${row.percent}% лимита`,text:`После запланированных расходов останется ${moneyText(Math.max(0,row.remaining))}.`}));if(data.projectedBalance<0)tips.push({tone:'danger',title:'План превышает текущий остаток',text:`Не хватает ${moneyText(Math.abs(data.projectedBalance))}. Сначала перенесите необязательные расходы или добавьте ожидаемый доход.`});if(data.optional>data.mandatory&&data.planned)tips.push({tone:'warning',title:'Необязательных расходов больше обязательных',text:`На необязательные траты запланировано ${moneyText(data.optional)}. Проверьте, что они действительно нужны в этом месяце.`});if(!tips.length)tips.push({tone:'success',title:'План выглядит устойчиво',text:`Запланировано ${moneyText(data.planned)}. Категории с настроенными лимитами не превышены.`});return `<section class="v867-finance-assistant v869-plan-assistant"><header><div><small>ПОМОЩНИК ПО БУДУЩЕМУ МЕСЯЦУ</small><h2>Проверка плана</h2><p>Подсказки строятся до того, как деньги будут потрачены.</p></div><i>✦</i></header><div>${tips.slice(0,8).map(tip=>`<article class="${tip.tone}"><i>${tip.tone==='danger'?'!':tip.tone==='warning'?'⚠':'✓'}</i><span><b>${safe(tip.title)}</b><small>${safe(tip.text)}</small></span></article>`).join('')}</div></section>`;}
  function openFinancePlanForm(id=''){ensureFinanceCategories();const existing=array('financePlans').find(item=>item.id===id)||{month:financePlanMonth(),dueDay:1,expenseClass:'mandatory',status:'planned'};openModal(id?'Редактировать запланированный расход':'Запланировать расход',`<div class="v79-form-grid"><label class="v79-field span-2"><span>Название расхода</span><input id="v869_plan_title" value="${safe(existing.title||'')}" placeholder="Например: Аренда квартиры"></label><label class="v79-field"><span>Месяц</span><input id="v869_plan_month" type="month" value="${safe(existing.month||financePlanMonth())}"></label><label class="v79-field"><span>День оплаты</span><input id="v869_plan_day" type="number" min="1" max="31" value="${number(existing.dueDay)||1}"></label><label class="v79-field"><span>Сумма</span><input id="v869_plan_amount" type="number" min="0" step="0.01" value="${number(existing.amount)||''}"></label><label class="v79-field"><span>Категория</span><select id="v869_plan_category">${financeCategoryOptions('expense',existing.category||'')}</select></label><label class="v79-field span-2"><span>Характер расхода</span><div class="v867-expense-choice v869-plan-choice"><button class="${expenseClass(existing)==='mandatory'?'selected mandatory':''}" data-v869-action="set-plan-class" data-value="mandatory" type="button">🛡 <b>Обязательный</b><small>нельзя безопасно пропустить</small></button><button class="${expenseClass(existing)==='optional'?'selected optional':''}" data-v869-action="set-plan-class" data-value="optional" type="button">✨ <b>Необязательный</b><small>можно перенести или сократить</small></button><input id="v869_plan_class" type="hidden" value="${expenseClass(existing)}"></div></label><label class="v79-field"><span>Повторить ещё месяцев</span><input id="v869_plan_repeat" type="number" min="0" max="24" value="0"></label><label class="v79-field"><span>Статус</span><select id="v869_plan_status"><option value="planned" ${existing.status==='planned'?'selected':''}>Запланирован</option><option value="paid" ${existing.status==='paid'?'selected':''}>Уже оплачен</option><option value="cancelled" ${existing.status==='cancelled'?'selected':''}>Отменён</option></select></label><label class="v79-field span-2"><span>Комментарий</span><textarea id="v869_plan_note" placeholder="Что важно учесть">${safe(existing.note||'')}</textarea></label></div><div class="v79-modal-actions"><button class="v78-primary" data-v869-action="save-plan" data-id="${safe(id)}" type="button">Сохранить план</button><button data-v78-action="close-modal" type="button">Отмена</button></div>`);}
  function showFinancePlanError(message,fieldId){const field=document.getElementById(fieldId),card=field?.closest('.modal-card')||document.querySelector('#modal .modal-card')||document.querySelector('#modal');let error=card?.querySelector('.v106-plan-form-error');if(card&&!error){error=document.createElement('p');error.className='v106-plan-form-error';error.setAttribute('role','alert');card.querySelector('.v79-form-grid')?.before(error);}card?.querySelectorAll('[aria-invalid="true"]').forEach(node=>node.removeAttribute('aria-invalid'));if(field){field.setAttribute('aria-invalid','true');field.focus({preventScroll:true});field.scrollIntoView({block:'center',behavior:'smooth'});}if(error){error.textContent=message;error.hidden=false;}return toast(message);}
  function saveFinancePlan(id=''){const title=clean(document.getElementById('v869_plan_title')?.value),month=clean(document.getElementById('v869_plan_month')?.value),amount=Math.max(0,number(document.getElementById('v869_plan_amount')?.value)),category=clean(document.getElementById('v869_plan_category')?.value),repeat=Math.min(24,Math.max(0,number(document.getElementById('v869_plan_repeat')?.value)));if(!title)return showFinancePlanError('Введите название расхода','v869_plan_title');if(!/^\d{4}-\d{2}$/.test(month))return showFinancePlanError('Выберите месяц','v869_plan_month');if(!amount)return showFinancePlanError('Укажите сумму больше нуля','v869_plan_amount');if(!category||category==='__new__')return showFinancePlanError('Выберите категорию','v869_plan_category');registerFinanceCategory(category,'expense');const base={title,month,dueDay:Math.min(31,Math.max(1,number(document.getElementById('v869_plan_day')?.value)||1)),amount,category,expenseClass:expenseClass(document.getElementById('v869_plan_class')?.value),note:clean(document.getElementById('v869_plan_note')?.value),status:clean(document.getElementById('v869_plan_status')?.value)||'planned',updatedAt:nowIso()};const old=id?array('financePlans').find(item=>item.id===id):null;if(old){Object.assign(old,base);}else{state.financePlans.unshift({id:makeId(),...base,createdAt:nowIso()});for(let step=1;step<=repeat;step++)state.financePlans.unshift({id:makeId(),...base,month:addMonthsPeriod(month,step),status:'planned',createdAt:nowIso(),updatedAt:nowIso()});}state.settings.v869.planMonth=month;save();closeModal();renderPremium();toast(repeat?`План сохранён на ${repeat+1} месяцев`:'Запланированный расход сохранён');}
  function deleteFinancePlan(id){const item=array('financePlans').find(row=>row.id===id);if(!item)return;if(!confirm(`Удалить запланированный расход «${item.title}»?`))return;archiveSnapshot(`Удалённый план: ${item.title}`,'deleted-finance-plan',item);state.financePlans=state.financePlans.filter(row=>row.id!==id);save();renderPremium();toast('План удалён, копия сохранена в архиве');}
  function copyFinancePlanNextMonth(id){const item=array('financePlans').find(row=>row.id===id);if(!item)return;const month=addMonthsPeriod(item.month,1);state.financePlans.unshift({...item,id:makeId(),month,status:'planned',actualOperationId:'',createdAt:nowIso(),updatedAt:nowIso()});state.settings.v869.planMonth=month;save();renderPremium();toast('Расход перенесён в следующий месяц');}
  function financePlanAccountOptions(selected=''){const accounts=array('financeAccounts').filter(account=>account&&account.active!==false&&account.type!=='credit_card'&&account.actualBalance!==null&&account.actualBalance!==undefined&&Number.isFinite(Number(account.actualBalance)));return `<option value="">Выберите собственный счёт</option>${accounts.map(account=>`<option value="${safe(account.id)}" ${account.id===selected?'selected':''}>${safe(account.name||'Счёт')} · ${safe(moneyText(account.actualBalance))}</option>`).join('')}`;}
  function postFinancePlan(id,confirmed=false){const item=array('financePlans').find(row=>row.id===id);if(!item||item.status!=='planned')return;const maxDay=new Date(Number(item.month.slice(0,4)),Number(item.month.slice(5,7)),0).getDate(),plannedDate=`${item.month}-${String(Math.min(maxDay,Math.max(1,number(item.dueDay)||1))).padStart(2,'0')}`;if(!confirmed){const accounts=financePlanAccountOptions();if(!array('financeAccounts').some(account=>account&&account.active!==false&&account.type!=='credit_card'&&account.actualBalance!==null&&account.actualBalance!==undefined&&Number.isFinite(Number(account.actualBalance))))return toast('Сначала добавьте собственный счёт с фактическим остатком');return openModal(`Провести: ${item.title}`,`<div class="v79-form-grid"><label class="v79-field"><span>Фактическая дата</span><input id="v112_post_date" type="date" value="${plannedDate}"></label><label class="v79-field"><span>Фактическая сумма</span><input id="v112_post_amount" type="number" min="0" step="0.01" value="${number(item.amount)}"></label><label class="v79-field span-2"><span>Списать со счёта</span><select id="v112_post_account">${accounts}</select><small>Остаток выбранного счёта уменьшится на фактическую сумму.</small></label><label class="v79-field span-2"><span>Комментарий</span><textarea id="v112_post_note">${safe(item.note||`По плану: ${item.title}`)}</textarea></label></div><div class="v79-modal-actions"><button class="v78-primary" data-v869-action="confirm-post-plan" data-id="${safe(id)}" type="button">Провести расход</button><button data-v78-action="close-modal" type="button">Отмена</button></div>`);}
    const date=clean(document.getElementById('v112_post_date')?.value)||plannedDate,amount=Math.max(0,number(document.getElementById('v112_post_amount')?.value)),accountId=clean(document.getElementById('v112_post_account')?.value),account=array('financeAccounts').find(row=>row.id===accountId),note=clean(document.getElementById('v112_post_note')?.value);if(!/^\d{4}-\d{2}-\d{2}$/.test(date))return toast('Укажите фактическую дату');if(!amount)return toast('Укажите фактическую сумму');if(!account)return toast('Выберите собственный счёт');const category=getFinanceCategory(item.category,'expense'),limit=number(category?.monthlyLimit),period=monthKey(date),projected=categorySpent(item.category,period)+amount;if(limit&&projected>limit&&!confirm(`После проведения категория «${item.category}» превысит лимит на ${moneyText(projected-limit)}. Всё равно провести расход?`))return toast('Операция не проведена');const stamp=nowIso(),operation={id:makeId(),date,type:'expense',amount,category:item.category,expenseClass:expenseClass(item),account:account.name||'',accountId:account.id,incomeSource:'',note:note||`По плану: ${item.title}`,planId:item.id,createdAt:stamp,updatedAt:stamp};state.operations.unshift(operation);account.actualBalance=number(account.actualBalance)-amount;account.calculatedBalance=account.actualBalance;account.updatedAt=stamp;item.status='paid';item.actualAmount=amount;item.actualOperationId=operation.id;item.updatedAt=stamp;array('financeReservations').filter(reservation=>reservation&&reservation.active!==false&&reservation.sourceType==='plan'&&reservation.sourceId===item.id).forEach(reservation=>{reservation.status='completed';reservation.active=false;reservation.completedAt=stamp;reservation.updatedAt=stamp;});const total=typeof v884CurrentBalanceFromAccounts==='function'?v884CurrentBalanceFromAccounts():null;if(total!==null)state.settings.currentBalance=total;save();closeModal();renderPremium();toast('Расход списан со счёта, операция и связанный резерв обновлены');}
  function debtsPage() {
    const out = activeDebtsOut(); const incoming = activeDebtsIn();
    return `<section class="v78-page"><header class="v78-page-head"><div><span>Прозрачные источники суммы</span><h1>Долги и обязательства</h1><p>Итог всегда равен сумме конкретных записей ниже. Никаких скрытых расчётов.</p></div><div><button class="v78-secondary" data-v79-action="open-debt-in" type="button">＋ Мне должны</button><button class="v78-primary" data-v79-action="open-debt-out" type="button">＋ Я должен</button></div></header>
      <section class="v78-kpi-row"><article><small>Я должен</small><b class="negative">${safe(moneyText(total(out)))}</b><span>${out.length} активных записей</span></article><article><small>Мне должны</small><b class="positive">${safe(moneyText(total(incoming)))}</b><span>${incoming.length} активных записей</span></article><article><small>Чистая позиция</small><b>${safe(moneyText(total(incoming)-total(out)))}</b><span>возвраты минус обязательства</span></article><article><small>Ближайший срок</small><b>${safe(formatShort(out.filter(item=>item.due).sort((a,b)=>String(a.due).localeCompare(String(b.due)))[0]?.due))}</b><span>по активным обязательствам</span></article></section>
      <section class="v78-two-cols">${debtColumn('Я должен',out,'negative')}${debtColumn('Мне должны',incoming,'positive')}</section>
    </section>`;
  }

  function debtColumn(title, items, tone) {
    return card(title, `Итого ${moneyText(debtOutstandingTotal(items))}`, `<div class="v78-debt-list">${items.map(item=>`<article><i>${tone==='negative'?'↘':'↗'}</i><span><b>${safe(item.person||'Без названия')}</b><small>${safe(item.note||'Без комментария')}${item.due?` · ${formatShort(item.due)}`:''}</small></span><strong class="${tone}">${safe(moneyText(debtOutstanding(item)))}</strong><div><button data-v79-action="edit-record" data-type="debt" data-id="${safe(item.id)}" type="button">Изменить</button><button data-v79-action="close-debt" data-id="${safe(item.id)}" type="button">Закрыть</button></div></article>`).join('') || '<div class="v78-empty">Записей нет.</div>'}</div>`, `v78-debt-column ${tone}`);
  }

  function profilePage() {
    const p = profile(); const age = ageFromBirth(p.birthDate);
    return `<section class="v78-page"><header class="v78-page-head"><div><span>Персонализация системы</span><h1>Мой профиль</h1><p>Имя и фотография отображаются во всём приложении.</p></div><div><button class="v78-secondary" data-v79-action="export-data" type="button">Экспорт данных</button><button class="v78-primary" data-v78-action="edit-profile" type="button">Редактировать профиль</button></div></header>
      <section class="v78-profile-hero"><div class="v78-profile-visual">${avatarHtml('xl')}<span class="v78-brand-orb"></span></div><div><span>Персональный профиль</span><h2>${safe([p.name,p.lastName].filter(Boolean).join(' ') || 'Алексей')}</h2><p>${safe(p.subtitle || 'Фокус на рост')}</p><div class="v78-profile-tags">${age!==''?`<span>${age} ${plural(age,'год','года','лет')}</span>`:''}${p.birthDate?`<span>🎂 ${formatDate(p.birthDate)}</span>`:''}${p.city?`<span>⌖ ${safe(p.city)}</span>`:''}</div></div></section>
      <section class="v78-profile-grid"><article><small>О себе</small><p>${safe(p.bio || 'Добавьте короткое описание, чтобы профиль стал по-настоящему вашим.')}</p></article><article><small>Email</small><p>${safe(p.email || 'Не указан')}</p></article><article><small>Телефон</small><p>${safe(p.phone || 'Не указан')}</p></article><article><small>Дата рождения</small><p>${safe(p.birthDate ? formatDate(p.birthDate) : 'Не указана')}</p></article></section>
      ${card('Безопасность данных', 'Профиль сохраняется вместе с общей базой приложения.', `<div class="v78-security-list"><span>✓ Обновление не очищает существующие записи</span><span>✓ Фотография уменьшается перед сохранением</span><span>✓ Профиль входит в JSON-экспорт</span><span>✓ Работает с защитным хранилищем V76</span></div>`, 'v78-security-card')}
    </section>`;
  }

  function wishlistPage() {
    return `<section class="v78-page"><header class="v78-page-head"><div><button class="v78-back" data-v78-route="habits" type="button">← Привычки</button><span>Следующие этапы дисциплины</span><h1>Вишлист привычек</h1><p>Храните идеи здесь и внедряйте только одну следующую привычку за раз.</p></div><button class="v78-primary" data-v78-action="open-wishlist-form" type="button">＋ Добавить идею</button></header><section class="v78-wishlist-full">${state.habitWishlist.map(item=>`<article><i>${safe(item.icon||'✦')}</i><span><b>${safe(item.title)}</b><small>${safe(item.schedule||'Без графика')}</small><p>${safe(item.note||'')}</p></span><div><button data-v78-action="promote-wishlist" data-id="${safe(item.id)}" type="button">Внедрить</button><button data-v78-action="edit-wishlist" data-id="${safe(item.id)}" type="button">✎</button><button data-v78-action="delete-wishlist" data-id="${safe(item.id)}" type="button">×</button></div></article>`).join('') || '<div class="v78-empty-big">Вишлист пока пуст.</div>'}</section></section>`;
  }



  const DEFAULT_FINANCE_CATEGORIES = {
    expense:[
      ['Продукты','🛒','#48b987','mandatory'],['Кафе','☕','#ff9b73','optional'],['Транспорт','🚌','#6aa9ff','mandatory'],['Такси','🚕','#f5b848','optional'],['Жильё','🏠','#9a7af0','mandatory'],['Подписки','◉','#7f9cff','optional'],['Здоровье','❤','#f783ac','mandatory'],['Развлечения','🎬','#ae86f4','optional'],['Подарки','🎁','#ff8fa9','optional'],['Долги','↘','#df6d7b','mandatory'],['Инвестиции','📈','#45b79a','optional'],['Путешествия','✈','#65bde8','optional'],['Переводы','⇄','#8d91a8','mandatory'],['Прочее','•••','#a49db5','optional']
    ],
    income:[
      ['Зарплата','💼','#46b98b'],['Аванс','₽','#56c3a6'],['Подработка','⚡','#7c73e6'],['Возврат','↩','#65bde8'],['Кэшбэк','✦','#f4b84f'],['Подарок','🎁','#f783ac'],['Переводы','⇄','#8d91a8'],['Прочий доход','＋','#8b5cf6']
    ]
  };
  function financeCategoryKind(value){return clean(value)==='income'?'income':'expense';}
  function financeCategoryKey(name,kind){return `${financeCategoryKind(kind)}|${clean(name).toLowerCase().replace(/\s+/g,' ')}`;}
  function ensureFinanceCategories(){
    const raw=Array.isArray(state.financeCategories)?state.financeCategories:[];const map=new Map();
    raw.forEach((item,index)=>{const row=typeof item==='string'?{name:item,type:'expense'}:(item||{});const name=clean(row.name||row.title);if(!name)return;const type=financeCategoryKind(row.type||row.kind);map.set(financeCategoryKey(name,type),{id:clean(row.id)||makeId(),name,type,icon:clean(row.icon)||'•',color:clean(row.color)||'#8b5cf6',active:row.active!==false,monthlyLimit:Math.max(0,number(row.monthlyLimit||row.limit)),defaultExpenseClass:type==='expense'?expenseClass(row.defaultExpenseClass||row.expenseClass||row.necessity):'',createdAt:row.createdAt||nowIso(),updatedAt:row.updatedAt||nowIso(),order:number(row.order)||index});});
    Object.entries(DEFAULT_FINANCE_CATEGORIES).forEach(([type,items])=>items.forEach(([name,icon,color,defaultExpenseClass='optional'],index)=>{const key=financeCategoryKey(name,type);if(!map.has(key))map.set(key,{id:makeId(),name,type,icon,color,active:true,monthlyLimit:0,defaultExpenseClass:type==='expense'?defaultExpenseClass:'',createdAt:nowIso(),updatedAt:nowIso(),order:index});}));
    array('operations').forEach(item=>{const name=clean(item.category);if(!name)return;const type=operationKind(item),key=financeCategoryKey(name,type);if(!map.has(key))map.set(key,{id:makeId(),name,type,icon:type==='income'?'＋':'•',color:type==='income'?'#48b987':'#8b5cf6',active:true,monthlyLimit:0,defaultExpenseClass:type==='expense'?expenseClass(item.expenseClass||item.necessity||'optional'):'',createdAt:nowIso(),updatedAt:nowIso(),order:999});});
    state.financeCategories=[...map.values()].sort((a,b)=>a.type.localeCompare(b.type)||number(a.order)-number(b.order)||a.name.localeCompare(b.name,'ru'));return state.financeCategories;
  }
  function financeCategories(kind='expense',includeInactive=false){ensureFinanceCategories();const type=financeCategoryKind(kind);return state.financeCategories.filter(row=>row.type===type&&(includeInactive||row.active!==false)).sort((a,b)=>number(a.order)-number(b.order)||a.name.localeCompare(b.name,'ru'));}
  function financeCategoryNames(kind='expense',includeInactive=false){return financeCategories(kind,includeInactive).map(row=>row.name);}
  function financeCategoryExists(name,kind='expense'){const target=clean(name).toLowerCase();return financeCategories(kind,true).some(row=>clean(row.name).toLowerCase()===target);}
  function registerFinanceCategory(name,kind='expense',extra={}){const title=clean(name);if(!title)return null;ensureFinanceCategories();const type=financeCategoryKind(kind),existing=state.financeCategories.find(row=>financeCategoryKey(row.name,row.type)===financeCategoryKey(title,type));if(existing){existing.active=true;existing.updatedAt=nowIso();if(extra.icon)existing.icon=clean(extra.icon);if(extra.color)existing.color=clean(extra.color);if(extra.monthlyLimit!==undefined)existing.monthlyLimit=Math.max(0,number(extra.monthlyLimit));if(type==='expense'&&extra.defaultExpenseClass)existing.defaultExpenseClass=expenseClass(extra.defaultExpenseClass);return existing;}const row={id:makeId(),name:title,type,icon:clean(extra.icon)||(type==='income'?'＋':'•'),color:clean(extra.color)||(type==='income'?'#48b987':'#8b5cf6'),active:true,monthlyLimit:type==='expense'?Math.max(0,number(extra.monthlyLimit)):0,defaultExpenseClass:type==='expense'?expenseClass(extra.defaultExpenseClass||'optional'):'',createdAt:nowIso(),updatedAt:nowIso(),order:financeCategories(type,true).length};state.financeCategories.push(row);return row;}
  function financeCategoryOptions(kind='expense',current=''){const type=financeCategoryKind(kind),selected=clean(current),names=financeCategoryNames(type);if(selected&&!names.some(name=>name.toLowerCase()===selected.toLowerCase()))names.unshift(selected);return `<option value="">Выберите категорию</option>${names.map(name=>`<option value="${safe(name)}" ${name===selected?'selected':''}>${safe(name)}</option>`).join('')}<option value="__new__">＋ Новая категория…</option>`;}
  function refreshFinanceCategorySelect(select,kind,current=''){if(!select)return;const keep=clean(current||select.value);select.innerHTML=financeCategoryOptions(kind,keep);select.dataset.categoryKind=financeCategoryKind(kind);if(keep)select.value=keep;}
  function financeCategoryUsage(row){return array('operations').filter(item=>operationKind(item)===row.type&&clean(item.category).toLowerCase()===clean(row.name).toLowerCase()).length;}
  function financeCategoryManagerHtml(){ensureFinanceCategories();const period=monthKey(todayKey()),expenses=financeCategories('expense',true),incomes=financeCategories('income',true),active=state.financeCategories.filter(x=>x.active!==false).length;const group=(title,rows)=>`<section class="v866-category-group"><header><h3>${title}</h3><span>${rows.filter(x=>x.active!==false).length} активных</span></header><div class="v866-category-list">${rows.map(row=>{const used=financeCategoryUsage(row),spent=row.type==='expense'?categorySpent(row.name,period):0,limit=number(row.monthlyLimit),percent=limit?Math.round(spent/limit*100):0;return `<article class="v866-category-row ${row.active===false?'inactive':''} ${limit&&spent>limit?'v867-over':''}"><i style="background:${safe(row.color)}20;color:${safe(row.color)}">${safe(row.icon||'•')}</i><span><b>${safe(row.name)}</b><small>${used} ${plural(used,'операция','операции','операций')}${row.type==='expense'?` · ${expenseClassLabel(row.defaultExpenseClass)}`:''}</small>${row.type==='expense'?`<em>${limit?`Лимит ${moneyText(limit)} · потрачено ${moneyText(spent)} (${percent}%)`:'Лимит не задан'}</em>`:''}</span><div><button data-v867-action="edit-finance-category" data-id="${safe(row.id)}" type="button">Настроить</button><button data-v866-action="toggle-finance-category" data-id="${safe(row.id)}" type="button">${row.active===false?'Вернуть':'Скрыть'}</button><button class="danger" data-v866-action="delete-finance-category" data-id="${safe(row.id)}" type="button">Удалить</button></div></article>`}).join('')||'<div class="v78-empty">Пока нет категорий.</div>'}</div></section>`;return `<div class="v866-category-manager"><section class="v866-category-summary"><article><small>Расходных</small><b>${expenses.filter(x=>x.active!==false).length}</b><span>лимиты и обязательность</span></article><article><small>Доходных</small><b>${incomes.filter(x=>x.active!==false).length}</b><span>для корректного учёта</span></article><article><small>С лимитами</small><b>${expenses.filter(x=>number(x.monthlyLimit)>0).length}</b><span>помощник их контролирует</span></article></section><section class="v866-category-create v867-category-create"><label><span>Тип категории</span><select id="v866_category_type"><option value="expense">Расход</option><option value="income">Доход</option></select></label><label><span>Название</span><input id="v866_category_name" placeholder="Например: Одежда"></label><label><span>Иконка</span><input id="v866_category_icon" value="•" maxlength="8"></label><label><span>Цвет</span><input id="v866_category_color" type="color" value="#8b5cf6"></label><label><span>Лимит в месяц</span><input id="v867_category_limit" type="number" min="0" step="100" placeholder="0 — без лимита"></label><label><span>По умолчанию</span><select id="v867_category_class"><option value="optional">Необязательный</option><option value="mandatory">Обязательный</option></select></label><button data-v866-action="save-finance-category" type="button">＋ Добавить</button></section><section class="v866-category-groups">${group('Расходы',expenses)}${group('Доходы',incomes)}</section><div class="v79-modal-actions"><button data-v78-action="close-modal" type="button">Готово</button></div></div>`;}
  function openFinanceCategories(){openModal('Категории, лимиты и обязательность',financeCategoryManagerHtml());}
  const v869OpenFinanceCategoriesOriginal=openFinanceCategories;
  openFinanceCategories=function(){try{return v869OpenFinanceCategoriesOriginal();}catch(error){console.error('[V86.9 categories]',error);state.financeCategories=[];ensureFinanceCategories();save();return v869OpenFinanceCategoriesOriginal();}};
  function saveFinanceCategory(){const type=financeCategoryKind(document.getElementById('v866_category_type')?.value),name=clean(document.getElementById('v866_category_name')?.value),icon=clean(document.getElementById('v866_category_icon')?.value)||'•',color=clean(document.getElementById('v866_category_color')?.value)||'#8b5cf6',monthlyLimit=Math.max(0,number(document.getElementById('v867_category_limit')?.value)),defaultExpenseClass=expenseClass(document.getElementById('v867_category_class')?.value);if(!name)return toast('Введите название категории');registerFinanceCategory(name,type,{icon,color,monthlyLimit,defaultExpenseClass});save();openFinanceCategories();toast(type==='income'?'Категория дохода добавлена':'Категория расхода и лимит сохранены');}
  function openFinanceCategorySettings(id){ensureFinanceCategories();const row=state.financeCategories.find(x=>x.id===id);if(!row)return;openModal(`Настройка · ${row.name}`,`<div class="v79-form-grid"><label class="v79-field"><span>Название</span><input id="v867_edit_name" value="${safe(row.name)}"></label><label class="v79-field"><span>Иконка</span><input id="v867_edit_icon" value="${safe(row.icon||'•')}" maxlength="8"></label><label class="v79-field"><span>Цвет</span><input id="v867_edit_color" type="color" value="${safe(row.color||'#8b5cf6')}"></label>${row.type==='expense'?`<label class="v79-field"><span>Лимит в месяц</span><input id="v867_edit_limit" type="number" min="0" step="100" value="${number(row.monthlyLimit)||''}" placeholder="0 — без лимита"></label><label class="v79-field span-2"><span>Расход по умолчанию</span><div class="v867-expense-choice"><button class="${expenseClass(row.defaultExpenseClass)==='mandatory'?'selected mandatory':''}" data-v867-action="category-class-choice" data-value="mandatory" type="button">🛡 Обязательный</button><button class="${expenseClass(row.defaultExpenseClass)==='optional'?'selected optional':''}" data-v867-action="category-class-choice" data-value="optional" type="button">✨ Необязательный</button><input id="v867_edit_class" type="hidden" value="${expenseClass(row.defaultExpenseClass)}"></div></label>`:''}<label class="v79-field span-2"><span>Состояние</span><div class="v81-help-box">Категория используется в ${financeCategoryUsage(row)} ${plural(financeCategoryUsage(row),'операции','операциях','операциях')}. Старые операции сохранятся при любых настройках справочника.</div></label></div><div class="v79-modal-actions"><button class="v78-primary" data-v867-action="save-finance-category-settings" data-id="${safe(id)}" type="button">Сохранить настройки</button><button data-v78-action="close-modal" type="button">Отмена</button></div>`);}
  function saveFinanceCategorySettings(id){ensureFinanceCategories();const row=state.financeCategories.find(x=>x.id===id);if(!row)return;const oldName=row.name,newName=clean(document.getElementById('v867_edit_name')?.value)||oldName;row.name=newName;row.icon=clean(document.getElementById('v867_edit_icon')?.value)||row.icon;row.color=clean(document.getElementById('v867_edit_color')?.value)||row.color;if(row.type==='expense'){row.monthlyLimit=Math.max(0,number(document.getElementById('v867_edit_limit')?.value));row.defaultExpenseClass=expenseClass(document.getElementById('v867_edit_class')?.value);}if(newName!==oldName&&confirm(`Переименовать категорию также во всех старых операциях «${oldName}» → «${newName}»?`)){array('operations').forEach(item=>{if(operationKind(item)===row.type&&clean(item.category).toLowerCase()===oldName.toLowerCase())item.category=newName;});}row.updatedAt=nowIso();save();closeModal();renderPremium();toast('Категория, лимит и тип сохранены');}
  function toggleFinanceCategory(id){ensureFinanceCategories();const row=state.financeCategories.find(x=>x.id===id);if(!row)return;row.active=row.active===false;row.updatedAt=nowIso();save();openFinanceCategories();toast(row.active?'Категория возвращена в список':'Категория скрыта из списка');}
  function deleteFinanceCategory(id){ensureFinanceCategories();const row=state.financeCategories.find(x=>x.id===id);if(!row)return;const used=financeCategoryUsage(row),message=used?`Категория «${row.name}» используется в ${used} операциях. Убрать её из выпадающего списка, не меняя старые операции?`:`Убрать категорию «${row.name}» из выпадающего списка?`;if(!confirm(message))return;row.active=false;row.archived=true;row.updatedAt=nowIso();save();openFinanceCategories();toast(used?'Категория скрыта, операции сохранены':'Категория убрана из списка');}
  function addCategoryFromOperationForm(){const kind=financeCategoryKind(document.getElementById('v79_f_type')?.value),name=clean(prompt(kind==='income'?'Название новой категории дохода':'Название новой категории расхода'));if(!name)return;const row=registerFinanceCategory(name,kind);save();const select=document.getElementById('v79_f_category');refreshFinanceCategorySelect(select,kind,name);if(kind==='expense')setExpenseClassChoice(row.defaultExpenseClass||'optional');toast('Категория добавлена');}

