  function fieldValue(item,key){return safe(item?.[key]??'');}
  function setExpenseClassChoice(value){const choice=expenseClass(value),hidden=document.getElementById('v79_f_expenseClass'),wrap=document.querySelector('[data-v867-expense-class-wrap]');if(hidden)hidden.value=choice;if(wrap)wrap.querySelectorAll('[data-v867-action="set-expense-class"]').forEach(button=>button.classList.toggle('selected',button.dataset.value===choice));}
