  function recordFormField(field,item){const [key,label,type,options]=field;const value=fieldValue(item,key);if(type==='goal-select')return `<label class="v79-field"><span>${label}</span><select id="v79_f_${key}"><option value="">Без цели</option>${array('goals').filter(g=>g.status!=='done'&&g.status!=='archived').map(g=>`<option value="${safe(g.id)}" ${String(item?.[key]||'')===g.id?'selected':''}>${safe(g.title)}</option>`).join('')}</select></label>`;if(type==='stage-select'){const goal=array('goals').find(g=>g.id===item?.goalId);return `<label class="v79-field"><span>${label}</span><select id="v79_f_${key}"><option value="">Без этапа</option>${(goal?.stages||[]).map(st=>`<option value="${safe(st.id)}" ${String(item?.[key]||'')===st.id?'selected':''}>${safe(st.title)}</option>`).join('')}</select></label>`;}if(type==='operation-category'){const kind=financeCategoryKind(item?.type);return `<label class="v79-field"><span>${label}</span><div class="v866-category-control"><select id="v79_f_${key}" data-v866-operation-category data-category-kind="${kind}">${financeCategoryOptions(kind,item?.[key]||'')}</select><button data-v866-action="add-category-from-operation" title="Добавить категорию" type="button">＋</button></div></label>`;}if(type==='expense-class'){const kind=financeCategoryKind(item?.type),category=getFinanceCategory(item?.category,kind),value=expenseClass(item?.[key]||category?.defaultExpenseClass||'optional');return `<label class="v79-field span-2" data-v867-expense-class-field ${kind==='income'?'hidden':''}><span>${label}</span><div class="v867-expense-choice" data-v867-expense-class-wrap><button class="${value==='mandatory'?'selected mandatory':''}" data-v867-action="set-expense-class" data-value="mandatory" type="button">🛡 <b>Обязательный</b><small>нельзя безопасно пропустить</small></button><button class="${value==='optional'?'selected optional':''}" data-v867-action="set-expense-class" data-value="optional" type="button">✨ <b>Необязательный</b><small>можно сократить или перенести</small></button><input id="v79_f_${key}" type="hidden" value="${value}"></div></label>`;}if(type==='textarea')return `<label class="v79-field span-2"><span>${label}</span><textarea id="v79_f_${key}">${value}</textarea></label>`;if(type==='select')return `<label class="v79-field"><span>${label}</span><select id="v79_f_${key}">${options.map(([v,l])=>`<option value="${safe(v)}" ${String(item?.[key]??'')===v?'selected':''}>${safe(l)}</option>`).join('')}</select></label>`;return `<label class="v79-field"><span>${label}</span><input id="v79_f_${key}" type="${type}" value="${value}"></label>`;}
  function openRecordForm(type,id='',preset={}){
    const schema=RECORDS[type];if(!schema)return toast('Форма не найдена');
    const item=id?array(schema.arr).find(x=>x.id===id)||{}:Object.assign({date:todayKey()},preset);
    const fields=new Map(schema.fields.map(field=>[field[0],field])),renderKeys=keys=>keys.map(key=>fields.has(key)?recordFormField(fields.get(key),item):'').join('');
    let body=schema.fields.map(field=>recordFormField(field,item)).join(''),title=schema.title,intro='';
    if(type==='operation'){
      title='Финансовая операция';
      intro='<header class="v108-form-intro span-2"><b>Сначала — сумма и категория</b><span>Счёт, комментарий и анализ покупки можно добавить при необходимости.</span></header>';
      body=`${renderKeys(['amount','type','category','expenseClass'])}<details class="v108-advanced span-2" data-v108-advanced="operation"><summary><span>Счёт, дата и пояснение</span><small>Необязательно</small></summary><div class="v108-advanced-body v79-form-grid">${renderKeys(['date','account','incomeSource','note'])}</div></details>`;
    }else if(type==='task'){
      const calendarEvent=routeNow()==='calendar';
      title=calendarEvent?'Событие':'Задача';
      intro=`<header class="v108-form-intro span-2"><b>${calendarEvent?'Когда и что должно произойти?':'Что нужно сделать?'}</b><span>Связи с целью, место и приоритет скрыты в дополнительных полях.</span></header>`;
      body=`${renderKeys(['title','date','time','durationMinutes'])}<details class="v108-advanced span-2" data-v108-advanced="task"><summary><span>Связи, место и статус</span><small>Необязательно</small></summary><div class="v108-advanced-body v79-form-grid">${renderKeys(['area','goalId','stageId','location','priority','status','note'])}</div></details>`;
    }
    openModal(`${id?'Редактировать':'Добавить'}: ${title}`,`<div class="v79-form-grid v108-clear-form" data-v108-record-form="${type}">${intro}${body}</div><div class="v79-modal-actions v108-sticky-actions"><button class="v78-primary" data-v79-action="save-record" data-type="${type}" data-id="${safe(id)}">Сохранить</button>${id?`<button class="v79-danger" data-v79-action="delete-record" data-type="${type}" data-id="${safe(id)}">Удалить</button>`:''}<button data-v78-action="close-modal">Отмена</button></div>`);
  }
  function saveRecord(type,id,originEl=null){
    const schema=RECORDS[type];if(!schema)return;
    const old=id?array(schema.arr).find(x=>x.id===id):null,item=Object.assign({},old||{id:makeId(),createdAt:nowIso()});
    schema.fields.forEach(([key,,kind])=>{const el=document.getElementById(`v79_f_${key}`);if(!el)return;item[key]=kind==='number'?number(el.value):clean(el.value);});
    let limitWarning='';
    if(type==='operation'){
      item.type=financeCategoryKind(item.type);if(item.category==='__new__'||!item.category)return toast('Выберите категорию');
      const category=registerFinanceCategory(item.category,item.type);
      if(item.type==='income'){item.expenseClass='';if(!item.incomeSource)item.incomeSource=item.category;}
      else{
        item.expenseClass=expenseClass(item.expenseClass||category?.defaultExpenseClass||'optional');
        const limit=Math.max(0,number(category?.monthlyLimit)),period=monthKey(item.date||todayKey()),projected=categorySpent(item.category,period,id)+Math.abs(number(item.amount));
        if(limit&&projected>limit){const over=projected-limit;if(!confirm(`Финансовый помощник останавливает расход.\n\nКатегория: ${item.category}\nЛимит: ${moneyText(limit)}\nПосле операции: ${moneyText(projected)}\nПревышение: ${moneyText(over)}\n\nСохранить расход несмотря на лимит?`))return toast('Расход не сохранён — лимит защищён');limitWarning=`Лимит «${item.category}» превышен на ${moneyText(over)}`;}
        else if(limit&&projected>=limit*.8)limitWarning=`В категории «${item.category}» использовано ${Math.round(projected/limit*100)}% лимита`;
      }
    }
    item.updatedAt=nowIso();if(id)state[schema.arr]=array(schema.arr).map(x=>x.id===id?item:x);else state[schema.arr].unshift(item);save();closeModal();renderPremium();
    const message=limitWarning||(type==='task'&&taskStatusMeta(item.status).done?'Задача сохранена и отмечена как выполненная':'Сохранено');toast(message);
    if(type==='task'&&taskStatusMeta(item.status).done){awardGame(`task:${item.id}:done`,8,2,'discipline',{title:item.title});celebrate(originEl,'✓');}
  }

  function deleteRecord(type,id){if(type==='task'&&window.SecondBrainV90?.deleteTask)return window.SecondBrainV90.deleteTask(id);const schema=RECORDS[type];if(!schema)return;const item=array(schema.arr).find(x=>x.id===id);if(!item)return;if(!confirm(`Удалить «${item.title||item.name||item.person||schema.title}»? Копия останется в архиве.`))return;archiveSnapshot(`Удалено: ${item.title||item.name||item.person||schema.title}`,`deleted-${type}`,item);state[schema.arr]=array(schema.arr).filter(x=>x.id!==id);save();closeModal();renderPremium();toast('Удалено, копия сохранена в архиве');}
  function topCategories(limit=10){const counts=new Map(); array('operations').filter(item=>operationKind(item)==='expense').forEach(item=>{const key=clean(item.category)||'Другое'; counts.set(key,(counts.get(key)||0)+1);}); return [...counts.entries()].sort((a,b)=>b[1]-a[1]).slice(0,limit);}
  function openCategoryEditor(prefill=''){const from=clean(prefill);const cats=topCategories(12);openModal('Редактор категорий CSV',`<div class="v79-form-grid"><label class="v79-field"><span>Старая категория</span><input id="v81_cat_from" value="${safe(from)}" placeholder="Например: Продукты"></label><label class="v79-field"><span>Новая категория</span><input id="v81_cat_to" placeholder="Например: Еда / Магазин"></label><label class="v79-field span-2"><span>Быстрые категории из выписки</span><div class="v81-modal-pills">${cats.map(([name,count])=>`<button type="button" data-v81-action="prefill-category" data-name="${safe(name)}">${safe(name)} <small>${count}</small></button>`).join('') || '<span>Нет категорий</span>'}</div></label><label class="v79-field span-2"><span>Как это работает</span><div class="v81-help-box">Выберите категорию из CSV и задайте новое понятное название. Все операции с этой категорией обновятся сразу.</div></label></div><div class="v79-modal-actions"><button class="v78-primary" data-v81-action="apply-category-bulk">Применить ко всей выписке</button><button data-v78-action="close-modal">Отмена</button></div>`);}
  function applyCategoryBulk(originEl=null){const from=clean(document.getElementById('v81_cat_from')?.value),to=clean(document.getElementById('v81_cat_to')?.value);if(!from||!to)return toast('Укажите обе категории');let changed=0; state.operations.forEach(item=>{if((clean(item.category)||'Другое')===from){item.category=to; item.updatedAt=nowIso(); changed+=1;}}); if(!changed)return toast('Совпадений не найдено'); save(); closeModal(); renderPremium(); toast(`Обновлено операций: ${changed}`); celebrate(originEl,'✦');}
  function openQuickCategory(id){const item=array('operations').find(x=>x.id===id);if(!item)return;const kind=operationKind(item),cats=topCategories(8).filter(([name])=>name!==clean(item.category));openModal('Изменить категорию операции',`<div class="v79-form-grid"><label class="v79-field span-2"><span>Текущая операция</span><div class="v81-help-box">${kind==='income'?'Доход':'Расход'} · ${safe(item.note||'Без комментария')} · ${safe(moneyText(item.amount))}</div></label><label class="v79-field span-2"><span>Категория</span><select id="v81_quick_category" data-v866-quick-category data-category-kind="${kind}">${financeCategoryOptions(kind,item.category||'')}</select></label><label class="v79-field span-2"><span>Частые варианты</span><div class="v81-modal-pills">${cats.map(([name,count])=>`<button type="button" data-v81-action="fill-quick-category" data-name="${safe(name)}">${safe(name)} <small>${count}</small></button>`).join('')}</div></label></div><div class="v79-modal-actions"><button class="v78-primary" data-v81-action="save-quick-category" data-id="${safe(id)}">Сохранить категорию</button><button data-v866-action="open-finance-categories" type="button">Управлять списком</button><button data-v78-action="close-modal">Отмена</button></div>`);}
  function saveQuickCategory(id,originEl=null){const item=array('operations').find(x=>x.id===id);if(!item)return;const next=clean(document.getElementById('v81_quick_category')?.value);if(!next)return toast('Выберите конкретную категорию');item.category=next;item.needsCategoryReview=false;item.categoryReviewedAt=nowIso();item.updatedAt=nowIso();state.settings.v85=state.settings.v85||{};state.settings.v85.reviewQueueDismissed=(state.settings.v85.reviewQueueDismissed||[]).filter(key=>key!==`operation:${id}`);save();closeModal();renderPremium();toast('Категория сохранена — операция убрана из очереди');celebrate(originEl,'✓');}
  function openQuick(){openModal('Быстро добавить',`<div class="v79-quick-grid">${[['task','✓','Задача'],['operation','₽','Операция'],['note','📝','Заметка'],['idea','💡','Идея'],['wish','💗','Желание']].map(([t,i,l])=>`<button data-v79-action="open-record-form" data-type="${t}"><i>${i}</i><b>${l}</b></button>`).join('')}<button data-v80-action="open-person-form"><i>👥</i><b>Человек</b></button></div>`);}
  function openBalance(){openModal('Фактический баланс',`<div class="v79-form-grid"><label class="v79-field span-2"><span>Сколько денег фактически сейчас?</span><input id="v79_balance" type="number" step="0.01" value="${number(state.settings.currentBalance)}"></label></div><div class="v79-modal-actions"><button class="v78-primary" data-v79-action="save-balance">Сохранить</button><button data-v78-action="close-modal">Отмена</button></div>`);}
  function genericRecordPage(route){const type=ROUTE_RECORD[route],schema=RECORDS[type],meta=ROUTE_META[route],items=array(schema.arr).slice().sort((a,b)=>String(b.date||b.updatedAt||'').localeCompare(String(a.date||a.updatedAt||'')));return `<section class="v78-page"><header class="v78-page-head"><div><button class="v78-back" data-v78-route="information">← Информация</button><span>${meta[0]} Раздел</span><h1>${meta[1]}</h1><p>${meta[2]}</p></div><button class="v78-primary" data-v79-action="open-record-form" data-type="${type}">＋ Добавить</button></header><section class="v79-record-grid">${items.map(item=>recordTile(type,item)).join('')||'<div class="v78-empty-big">Пока пусто. Добавьте первую запись.</div>'}</section></section>`;}
  function recordTile(type,item){const title=item.title||item.name||item.person||item.category||'Запись';const sub=item.role||item.author||item.area||item.folder||item.place||item.type||item.date||'';const body=item.note||item.text||item.quotes||'';const amount=item.amount||item.budget||item.target;const image=normalizedUrl(item.imageUrl||item.coverUrl||item.posterUrl||'');const link=normalizedUrl(item.url||item.productUrl||'');return `<article class="v79-record-card ${image?'has-image':''}">${image?`<div class="v80-record-image"><img src="${safe(image)}" alt="${safe(title)}" loading="lazy" onerror="this.parentElement.style.display='none'"></div>`:''}<header><div><small>${safe(sub)}</small><h2>${safe(title)}</h2></div>${amount?`<b>${safe(moneyText(amount))}</b>`:''}</header><p>${safe(String(body).slice(0,320))||'Без дополнительного описания.'}</p>${link?`<a class="v80-external-link" href="${safe(link)}" target="_blank" rel="noopener">Открыть ссылку ↗</a>`:''}<footer><button data-v79-action="edit-record" data-type="${type}" data-id="${safe(item.id)}">Изменить</button><button class="danger" data-v79-action="delete-record" data-type="${type}" data-id="${safe(item.id)}">Удалить</button></footer></article>`;}


  function bookStatusMeta(value){const raw=clean(value).toLowerCase();if(/finished|прочитан|готов/.test(raw))return {key:'finished',label:'Прочитано',icon:'✓'};if(/reading|читаю|в процессе/.test(raw))return {key:'reading',label:'Читаю',icon:'◉'};if(/paused|пауза/.test(raw))return {key:'paused',label:'На паузе',icon:'Ⅱ'};return {key:'planned',label:'Хочу прочитать',icon:'+'};}
  function bookProgress(book){const total=Math.max(0,number(book.pagesTotal)),current=Math.max(0,number(book.currentPage));if(total>0)return Math.min(100,Math.round(current/total*100));return bookStatusMeta(book.status).key==='finished'?100:0;}
  function bookQuoteEntries(book){const list=Array.isArray(book.quoteEntries)?book.quoteEntries.filter(Boolean):[];if(list.length)return list.slice().sort((a,b)=>String(b.createdAt||b.date||'').localeCompare(String(a.createdAt||a.date||'')));const legacy=clean(book.quotes);return legacy?[{id:`legacy-${book.id}`,text:legacy,page:'',note:'Перенесено из старого поля',createdAt:book.updatedAt||book.createdAt||''}]:[];}
  function bookForecast(book){const sessions=array('bookSessions').filter(x=>x.bookId===book.id&&String(x.date||'')>=addDaysKey(todayKey(),-30));const pages=sessions.reduce((sum,x)=>sum+number(x.pages),0),days=[...new Set(sessions.map(x=>String(x.date||'').slice(0,10)))].length,remaining=Math.max(0,number(book.pagesTotal)-number(book.currentPage));if(!remaining||!pages||!days)return '';const perDay=pages/days;const estimate=Math.max(1,Math.ceil(remaining/perDay));return `Прогноз: ещё ${estimate} ${plural(estimate,'день','дня','дней')} чтения`; }
  function bookStats(){const books=array('books'),reading=books.filter(b=>bookStatusMeta(b.status).key==='reading'),finished=books.filter(b=>bookStatusMeta(b.status).key==='finished');const pages=books.reduce((sum,b)=>sum+Math.max(0,number(b.currentPage)),0);const quotes=books.reduce((sum,b)=>sum+bookQuoteEntries(b).length,0);const minutes=array('bookSessions').reduce((sum,x)=>sum+number(x.minutes),0);return {books,reading,finished,pages,quotes,minutes};}
  function booksPage(){const data=bookStats();const books=data.books.slice().sort((a,b)=>{const statusOrder={reading:0,planned:1,paused:2,finished:3};const sa=statusOrder[bookStatusMeta(a.status).key]??9,sb=statusOrder[bookStatusMeta(b.status).key]??9;return sa-sb||String(b.updatedAt||'').localeCompare(String(a.updatedAt||''));});const latestQuotes=books.flatMap(book=>bookQuoteEntries(book).map(q=>({book,q}))).slice().sort((a,b)=>String(b.q.createdAt||'').localeCompare(String(a.q.createdAt||''))).slice(0,8);return `<section class="v78-page v833-books-page"><header class="v78-page-head"><div><button class="v78-back" data-v78-route="information">← Информация</button><span>📚 Личная библиотека</span><h1>Книги</h1><p>Фиксируйте прогресс, страницы, цитаты, мысли и итоговую оценку — без отдельного дневника чтения.</p></div><button class="v78-primary" data-v79-action="open-record-form" data-type="book" type="button">＋ Добавить книгу</button></header><section class="v833-book-stats"><article><i>◉</i><span><small>Сейчас читаю</small><b>${data.reading.length}</b></span></article><article><i>✓</i><span><small>Прочитано</small><b>${data.finished.length}</b></span></article><article><i>▤</i><span><small>Страниц отмечено</small><b>${data.pages}</b></span></article><article><i>“</i><span><small>Цитат сохранено</small><b>${data.quotes}</b></span></article><article><i>⏱</i><span><small>Минут чтения</small><b>${data.minutes}</b></span></article></section><section class="v833-books-grid">${books.map(bookCard).join('')||'<div class="v78-empty-big">Добавьте первую книгу и начните фиксировать прогресс.</div>'}</section>${latestQuotes.length?card('Последние цитаты','Сохранённые мысли из всей библиотеки.',`<div class="v833-quotes-feed">${latestQuotes.map(({book,q})=>`<article><blockquote>${safe(q.text||'Цитата')}</blockquote><footer><span><b>${safe(book.title||'Книга')}</b>${q.page?`<small>стр. ${safe(q.page)}</small>`:''}</span><button data-v833-action="open-book-quote" data-id="${safe(book.id)}" type="button">Добавить ещё</button></footer>${q.note?`<p>${safe(q.note)}</p>`:''}</article>`).join('')}</div>`,'v833-quotes-card'):''}</section>`;}
  function bookCard(book){const status=bookStatusMeta(book.status),progress=bookProgress(book),cover=normalizedUrl(book.imageUrl||book.coverUrl||''),quotes=bookQuoteEntries(book),total=Math.max(0,number(book.pagesTotal)),current=Math.max(0,number(book.currentPage));return `<article class="v833-book-card ${status.key}"><div class="v833-book-cover">${cover?`<img src="${safe(cover)}" alt="${safe(book.title||'Книга')}" loading="lazy" onerror="this.outerHTML='<span>📚</span>'">`:'<span>📚</span>'}<em>${safe(status.icon)}</em></div><div class="v833-book-content"><header><div><small>${safe(book.author||'Автор не указан')}</small><h2>${safe(book.title||'Без названия')}</h2></div>${number(book.rating)?`<strong>★ ${number(book.rating)}/10</strong>`:''}</header><div class="v833-book-progress"><div><span>${safe(status.label)}</span><b>${progress}%</b></div><u><i style="width:${progress}%"></i></u><small>${total?`${current} из ${total} страниц`:current?`${current} страниц отмечено`:'Укажите количество страниц'}</small></div>${book.summary?`<p>${safe(String(book.summary).slice(0,180))}</p>`:'<p>Добавьте главные мысли или короткий конспект.</p>'}<div class="v833-book-meta"><span>“ ${quotes.length} ${plural(quotes.length,'цитата','цитаты','цитат')}</span>${book.startDate?`<span>Начато ${formatShort(book.startDate)}</span>`:''}${book.finishDate?`<span>Завершено ${formatShort(book.finishDate)}</span>`:''}${bookForecast(book)?`<span class="v86-book-forecast">${safe(bookForecast(book))}</span>`:''}</div><footer><button data-v85-action="open-book-session" data-id="${safe(book.id)}" type="button">Сессия</button><button data-v833-action="open-book-progress" data-id="${safe(book.id)}" type="button">Прогресс</button><button data-v833-action="open-book-quote" data-id="${safe(book.id)}" type="button">＋ Цитата</button><button data-v79-action="edit-record" data-type="book" data-id="${safe(book.id)}" type="button">Изменить</button><button class="danger" data-v79-action="delete-record" data-type="book" data-id="${safe(book.id)}" type="button">Удалить</button></footer></div></article>`;}
  function openBookProgress(id){const book=array('books').find(b=>b.id===id);if(!book)return toast('Книга не найдена');const status=bookStatusMeta(book.status);openModal(`Прогресс: ${book.title||'Книга'}`,`<div class="v79-form-grid"><label class="v79-field"><span>Текущая страница</span><input id="v833_book_current" type="number" min="0" value="${Math.max(0,number(book.currentPage))}"></label><label class="v79-field"><span>Всего страниц</span><input id="v833_book_total" type="number" min="0" value="${Math.max(0,number(book.pagesTotal))}"></label><label class="v79-field"><span>Статус</span><select id="v833_book_status"><option value="planned" ${status.key==='planned'?'selected':''}>Хочу прочитать</option><option value="reading" ${status.key==='reading'?'selected':''}>Читаю</option><option value="paused" ${status.key==='paused'?'selected':''}>На паузе</option><option value="finished" ${status.key==='finished'?'selected':''}>Прочитано</option></select></label><label class="v79-field"><span>Оценка из 10</span><input id="v833_book_rating" type="number" min="0" max="10" step="0.5" value="${number(book.rating)||''}"></label><label class="v79-field"><span>Дата начала</span><input id="v833_book_start" type="date" value="${safe(book.startDate||'')}"></label><label class="v79-field"><span>Дата завершения</span><input id="v833_book_finish" type="date" value="${safe(book.finishDate||'')}"></label><label class="v79-field span-2"><span>Что понял / главная мысль</span><textarea id="v833_book_summary">${safe(book.summary||'')}</textarea></label></div><div class="v79-modal-actions"><button class="v78-primary" data-v833-action="save-book-progress" data-id="${safe(id)}" type="button">Сохранить прогресс</button><button data-v78-action="close-modal" type="button">Отмена</button></div>`);}
  function saveBookProgress(id,originEl=null){const book=array('books').find(b=>b.id===id);if(!book)return;const previous=bookProgress(book);book.currentPage=Math.max(0,number(document.getElementById('v833_book_current')?.value));book.pagesTotal=Math.max(0,number(document.getElementById('v833_book_total')?.value));book.status=clean(document.getElementById('v833_book_status')?.value)||'planned';book.rating=Math.min(10,Math.max(0,number(document.getElementById('v833_book_rating')?.value)));book.startDate=clean(document.getElementById('v833_book_start')?.value);book.finishDate=clean(document.getElementById('v833_book_finish')?.value);book.summary=clean(document.getElementById('v833_book_summary')?.value);if(book.status==='reading'&&!book.startDate)book.startDate=todayKey();if(book.status==='finished'){if(book.pagesTotal)book.currentPage=book.pagesTotal;if(!book.finishDate)book.finishDate=todayKey();}book.updatedAt=nowIso();const current=bookProgress(book);if(current>previous)awardGame(`book-progress:${id}:${todayKey()}:${current}`,4,1,'knowledge',{title:`Прогресс книги: ${book.title}`});if(current===100&&previous<100)awardGame(`book-finished:${id}`,20,8,'knowledge',{title:`Книга прочитана: ${book.title}`});syncAchievements();save();closeModal();renderPremium();toast('Прогресс книги сохранён');if(current>previous)celebrate(originEl,'📚');}
  function openBookQuote(id){const book=array('books').find(b=>b.id===id);if(!book)return toast('Книга не найдена');openModal(`Новая цитата · ${book.title||'Книга'}`,`<div class="v79-form-grid"><label class="v79-field span-2"><span>Цитата</span><textarea id="v833_quote_text" placeholder="Запишите цитату точно или своими словами"></textarea></label><label class="v79-field"><span>Страница</span><input id="v833_quote_page" type="number" min="0" value="${Math.max(0,number(book.currentPage))||''}"></label><label class="v79-field"><span>Дата</span><input id="v833_quote_date" type="date" value="${todayKey()}"></label><label class="v79-field span-2"><span>Почему это важно / моя мысль</span><textarea id="v833_quote_note" placeholder="Как я понимаю эту мысль и где применю?"></textarea></label></div><div class="v79-modal-actions"><button class="v78-primary" data-v833-action="save-book-quote" data-id="${safe(id)}" type="button">Сохранить цитату</button><button data-v78-action="close-modal" type="button">Отмена</button></div>`);}
  function saveBookQuote(id,originEl=null){const book=array('books').find(b=>b.id===id);if(!book)return;const text=clean(document.getElementById('v833_quote_text')?.value);if(!text)return toast('Введите цитату');const entry={id:makeId(),text,page:Math.max(0,number(document.getElementById('v833_quote_page')?.value))||'',date:clean(document.getElementById('v833_quote_date')?.value)||todayKey(),note:clean(document.getElementById('v833_quote_note')?.value),createdAt:nowIso()};book.quoteEntries=Array.isArray(book.quoteEntries)?book.quoteEntries:[];book.quoteEntries.unshift(entry);if(entry.page&&entry.page>number(book.currentPage))book.currentPage=entry.page;if(bookStatusMeta(book.status).key==='planned')book.status='reading';if(!book.startDate)book.startDate=todayKey();book.updatedAt=nowIso();awardGame(`book-quote:${id}:${entry.id}`,2,1,'knowledge',{title:`Цитата: ${book.title}`});syncAchievements();save();closeModal();renderPremium();toast('Цитата сохранена');celebrate(originEl,'“');}

  function personAvatar(person,size='card'){const src=normalizedUrl(person.avatar||person.photoUrl||'');return src?`<img class="v80-person-avatar ${size}" src="${safe(src)}" alt="${safe(person.name)}" loading="lazy" onerror="this.outerHTML='<span class=&quot;v80-person-avatar fallback ${size}&quot;>${safe(initial(person.name))}</span>'">`:`<span class="v80-person-avatar fallback ${size}">${safe(initial(person.name))}</span>`;}
  function peoplePage(){const people=array('people').slice().sort((a,b)=>clean(a.name).localeCompare(clean(b.name),'ru')),birthdays=upcomingBirthdays(60);return `<section class="v78-page"><header class="v78-page-head"><div><button class="v78-back" data-v78-route="information">← Информация</button><span>Личные связи</span><h1>Люди</h1><p>Анкеты, важные даты, предпочтения, вишлисты и контекст отношений.</p></div><button class="v78-primary" data-v80-action="open-person-form">＋ Добавить человека</button></header>${birthdays.length?`<section class="v80-birthday-strip"><header><h2>Ближайшие дни рождения</h2><p>Напоминания отображаются заранее по настройкам каждой анкеты.</p></header><div>${birthdays.slice(0,6).map(({person,days})=>`<button data-v80-action="open-person-form" data-id="${safe(person.id)}">${personAvatar(person,'sm')}<span><b>${safe(person.name)}</b><small>${days===0?'сегодня':days===1?'завтра':`через ${days} дн.`}</small></span></button>`).join('')}</div></section>`:''}<section class="v80-people-grid">${people.map(person=>{const days=birthdayDays(person),wish=clean(person.wishlist||person.giftIdeas);return `<article class="v80-person-card"><header>${personAvatar(person)}<div><small>${safe(person.role||person.relation||'Человек')}</small><h2>${safe(person.name)}</h2>${person.city?`<p>⌖ ${safe(person.city)}</p>`:''}</div><button data-v80-action="open-person-form" data-id="${safe(person.id)}">✎</button></header><div class="v80-person-facts">${person.birthday?`<span><small>День рождения</small><b>${safe(formatDate(person.birthday))}</b><em>${days===0?'Сегодня':days===1?'Завтра':`через ${days} дн.`}</em></span>`:''}${person.phone?`<span><small>Телефон</small><b>${safe(person.phone)}</b></span>`:''}${person.telegram?`<span><small>Telegram</small><b>${safe(person.telegram)}</b></span>`:''}</div><p>${safe(person.note||person.about||'Добавьте важный контекст об этом человеке.')}</p>${wish?`<div class="v80-person-wishlist"><small>Вишлист и идеи подарков</small><p>${safe(wish.slice(0,220))}</p></div>`:''}<footer><button data-v80-action="open-person-form" data-id="${safe(person.id)}">Открыть анкету</button><button class="danger" data-v80-action="delete-person" data-id="${safe(person.id)}">Удалить</button></footer></article>`}).join('')||'<div class="v78-empty-big">Добавьте первую анкету человека.</div>'}</section></section>`;}
  function openPersonForm(id=''){const p=array('people').find(x=>x.id===id)||{};pendingPersonAvatar=p.avatar||p.photoUrl||'';const preview=pendingPersonAvatar?`<img src="${safe(normalizedUrl(pendingPersonAvatar))}">`:`<span>${safe(initial(p.name||'Ч'))}</span>`;openModal(id?'Анкета человека':'Новый человек',`<div class="v80-person-editor"><div class="v78-avatar-editor"><div id="v80_person_avatar_preview">${preview}</div><label><input id="v80_person_avatar_file" type="file" accept="image/*"><span>Загрузить фотографию</span></label><small>Фото хранится вместе с базой приложения.</small></div><div class="v79-form-grid"><label class="v79-field"><span>Имя</span><input id="v80_p_name" value="${safe(p.name||'')}"></label><label class="v79-field"><span>Кто это / роль</span><input id="v80_p_role" value="${safe(p.role||p.relation||'')}"></label><label class="v79-field"><span>Дата рождения</span><input id="v80_p_birthday" type="date" value="${safe(p.birthday||'')}"></label><label class="v79-field"><span>Напомнить за сколько дней</span><input id="v80_p_reminder" type="number" min="0" max="60" value="${number(p.birthdayReminderDays)||7}"></label><label class="v79-field"><span>Телефон</span><input id="v80_p_phone" value="${safe(p.phone||'')}"></label><label class="v79-field"><span>Email</span><input id="v80_p_email" type="email" value="${safe(p.email||'')}"></label><label class="v79-field"><span>Telegram / соцсеть</span><input id="v80_p_telegram" value="${safe(p.telegram||'')}"></label><label class="v79-field"><span>Город</span><input id="v80_p_city" value="${safe(p.city||'')}"></label><label class="v79-field span-2"><span>Интересы, любимое и предпочтения</span><textarea id="v80_p_interests">${safe(p.interests||'')}</textarea></label><label class="v79-field span-2"><span>Что не любит / важные границы</span><textarea id="v80_p_dislikes">${safe(p.dislikes||'')}</textarea></label><label class="v79-field span-2"><span>Вишлист человека</span><textarea id="v80_p_wishlist">${safe(p.wishlist||'')}</textarea></label><label class="v79-field span-2"><span>Идеи подарков</span><textarea id="v80_p_gifts">${safe(p.giftIdeas||'')}</textarea></label><label class="v79-field span-2"><span>Важные даты и события</span><textarea id="v80_p_dates">${safe(p.importantDates||'')}</textarea></label><label class="v79-field span-2"><span>Контекст и заметки</span><textarea id="v80_p_note">${safe(p.note||p.about||'')}</textarea></label></div></div><div class="v79-modal-actions"><button class="v78-primary" data-v80-action="save-person" data-id="${safe(id)}">Сохранить анкету</button>${id?`<button class="v79-danger" data-v80-action="delete-person" data-id="${safe(id)}">Удалить</button>`:''}<button data-v78-action="close-modal">Отмена</button></div>`);}
  function savePerson(id=''){const old=array('people').find(x=>x.id===id),p=Object.assign({},old||{id:makeId(),createdAt:nowIso()});p.name=clean(document.getElementById('v80_p_name')?.value)||'Без имени';p.role=clean(document.getElementById('v80_p_role')?.value);p.birthday=clean(document.getElementById('v80_p_birthday')?.value);p.birthdayReminderDays=Math.max(0,number(document.getElementById('v80_p_reminder')?.value)||7);p.birthdayReminderEnabled=true;p.phone=clean(document.getElementById('v80_p_phone')?.value);p.email=clean(document.getElementById('v80_p_email')?.value);p.telegram=clean(document.getElementById('v80_p_telegram')?.value);p.city=clean(document.getElementById('v80_p_city')?.value);p.interests=clean(document.getElementById('v80_p_interests')?.value);p.dislikes=clean(document.getElementById('v80_p_dislikes')?.value);p.wishlist=clean(document.getElementById('v80_p_wishlist')?.value);p.giftIdeas=clean(document.getElementById('v80_p_gifts')?.value);p.importantDates=clean(document.getElementById('v80_p_dates')?.value);p.note=clean(document.getElementById('v80_p_note')?.value);p.avatar=pendingPersonAvatar||'';p.updatedAt=nowIso();state.people=old?array('people').map(x=>x.id===id?p:x):[p,...array('people')];save();closeModal();renderPremium();toast('Анкета сохранена');}
  function deletePerson(id){const p=array('people').find(x=>x.id===id);if(!p)return;if(!confirm(`Удалить анкету «${p.name}»? Резервная копия останется в архиве.`))return;archiveSnapshot(`Удалённая анкета: ${p.name}`,'deleted-person',p);state.people=array('people').filter(x=>x.id!==id);save();closeModal();renderPremium();toast('Анкета перенесена в архив');}

  function startOfWeekKey(value){const d=dateAtNoon(value);const day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return d.toISOString().slice(0,10);}
  function monthGridDates(value){const d=dateAtNoon(value),first=new Date(d.getFullYear(),d.getMonth(),1,12);const start=startOfWeekKey(first.toISOString().slice(0,10));return Array.from({length:42},(_,i)=>addDaysKey(start,i));}
  function calendarAnchor(){return state.settings.v82?.calendarAnchor||todayKey();}
  function calendarView(){return state.settings.v82?.calendarView||'week';}
  function tasksForDate(date, includeDone=true){return array('tasks').filter(t=>String(t.date||'').slice(0,10)===date&&(includeDone||!taskStatusMeta(t.status).done)).sort((a,b)=>{const p=priorityMeta(a.priority).order-priorityMeta(b.priority).order;return p||String(a.time||'99:99').localeCompare(String(b.time||'99:99'));});}
  function taskIsArchived(task){return taskStatusMeta(task.status).done || (task.date&&String(task.date).slice(0,10)<todayKey());}
  function googleCalendarUrl(task){const title=clean(task.title)||'Событие Second Brain OS';const date=String(task.date||todayKey()).slice(0,10).replaceAll('-','');let dates='';if(task.time){const compact=String(task.time).replace(':','').padEnd(4,'0');const start=`${date}T${compact}00`;const startDate=new Date(`${String(task.date||todayKey()).slice(0,10)}T${task.time}:00`);const endDate=new Date(startDate.getTime()+60*60*1000);const end=`${endDate.getFullYear()}${String(endDate.getMonth()+1).padStart(2,'0')}${String(endDate.getDate()).padStart(2,'0')}T${String(endDate.getHours()).padStart(2,'0')}${String(endDate.getMinutes()).padStart(2,'0')}00`;dates=`${start}/${end}`;}else{const next=addDaysKey(task.date||todayKey(),1).replaceAll('-','');dates=`${date}/${next}`;}const params=new URLSearchParams({action:'TEMPLATE',text:title,dates,details:[task.note,task.area?`Сфера: ${task.area}`:'',`Приоритет: ${priorityMeta(task.priority).label}`].filter(Boolean).join('\n'),location:clean(task.location||'')});return `https://calendar.google.com/calendar/render?${params.toString()}`;}
  function calendarTaskCard(task, compact=false, positioned=false){const p=priorityMeta(task.priority),st=taskStatusMeta(task.status),weekly=String(task.automationKey||'').startsWith('weekly-review:');let position='';if(positioned&&task.time){const [h,m]=String(task.time).split(':').map(Number);const top=Math.max(0,((h||8)-8)*72+(m||0)/60*72);position=` style="--event-top:${top.toFixed(1)}px"`;}const openAction=weekly?'data-v85-action="weekly-review" data-v120-action="weekly-review" aria-label="Провести недельный разбор"':`data-v79-action="edit-record" data-type="task" data-id="${safe(task.id)}"`;return `<article class="v82-calendar-event ${p.tone} ${st.done?'done':''} ${compact?'compact':''} ${positioned?'positioned':''}"${position}><button class="v82-event-open" ${openAction} type="button"><span class="v82-event-time">${safe(task.time||'Весь день')}</span><b>${safe(task.title||'Событие')}</b>${compact?'':`<small>${safe(weekly?'Открыть форму разбора':task.area||st.label)}</small>`}</button><div class="v82-event-actions"><button title="Добавить в Google Календарь" data-v82-action="google-calendar" data-id="${safe(task.id)}" type="button">G</button><button title="Изменить время и детали" data-v79-action="edit-record" data-type="task" data-id="${safe(task.id)}" type="button">✎</button></div></article>`;}
  function calendarNavigation(){const view=calendarView(),anchor=calendarAnchor();return `<div class="v82-calendar-toolbar"><div class="v82-calendar-nav"><button data-v82-action="calendar-shift" data-delta="-1" type="button">←</button><button data-v82-action="calendar-today" type="button">Сегодня</button><button data-v82-action="calendar-shift" data-delta="1" type="button">→</button><strong>${view==='month'?dateAtNoon(anchor).toLocaleDateString('ru-RU',{month:'long',year:'numeric'}):formatDate(anchor)}</strong></div><div class="v82-calendar-views">${[['day','День'],['week','Неделя'],['month','Месяц'],['archive','Архив']].map(([key,label])=>`<button class="${view===key?'active':''}" data-v82-action="calendar-view" data-view="${key}" type="button">${label}</button>`).join('')}</div></div>`;}
  function calendarDayView(){const date=calendarAnchor(),items=tasksForDate(date);return `<section class="v82-day-calendar"><header><div><small>${dateAtNoon(date).toLocaleDateString('ru-RU',{weekday:'long'})}</small><h2>${formatDate(date)}</h2></div><button data-v82-action="quick-task-day" data-date="${date}" type="button">＋ Событие</button></header><div class="v82-day-timeline">${Array.from({length:15},(_,i)=>i+7).map(hour=>{const hourText=`${String(hour).padStart(2,'0')}:00`;const rows=items.filter(t=>String(t.time||'').startsWith(String(hour).padStart(2,'0')));return `<div class="v82-time-row"><time>${hourText}</time><section>${rows.map(t=>calendarTaskCard(t)).join('')||'<span></span>'}</section></div>`}).join('')}</div>${items.filter(t=>!t.time).length?`<div class="v82-all-day"><b>Весь день</b>${items.filter(t=>!t.time).map(t=>calendarTaskCard(t,true)).join('')}</div>`:''}</section>`;}
  function calendarWeekView(){const start=startOfWeekKey(calendarAnchor()),dates=Array.from({length:7},(_,i)=>addDaysKey(start,i));return `<section class="v82-google-week"><div class="v82-week-head"><span></span>${dates.map(date=>`<button class="${date===todayKey()?'today':''}" data-v82-action="calendar-anchor" data-date="${date}" type="button"><small>${dateAtNoon(date).toLocaleDateString('ru-RU',{weekday:'short'})}</small><b>${dateAtNoon(date).getDate()}</b></button>`).join('')}</div><div class="v82-week-body"><aside>${Array.from({length:14},(_,i)=>`${String(i+8).padStart(2,'0')}:00`).map(x=>`<span>${x}</span>`).join('')}</aside>${dates.map(date=>`<section class="v82-week-column"><button class="v82-column-add" data-v82-action="quick-task-day" data-date="${date}" type="button">＋</button>${tasksForDate(date).map(t=>calendarTaskCard(t,false,true)).join('')||'<div class="v82-week-empty">Свободно</div>'}</section>`).join('')}</div></section>`;}
  function calendarMonthView(){const anchor=calendarAnchor(),dates=monthGridDates(anchor),month=dateAtNoon(anchor).getMonth();return `<section class="v82-month-calendar"><header>${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(x=>`<span>${x}</span>`).join('')}</header><div>${dates.map(date=>{const outside=dateAtNoon(date).getMonth()!==month,items=tasksForDate(date);return `<article class="${outside?'outside':''} ${date===todayKey()?'today':''}"><header><button data-v82-action="calendar-anchor" data-date="${date}" type="button">${dateAtNoon(date).getDate()}</button><button data-v82-action="quick-task-day" data-date="${date}" type="button">＋</button></header><section>${items.slice(0,3).map(t=>calendarTaskCard(t,true)).join('')}${items.length>3?`<button class="v82-more-events" data-v82-action="calendar-anchor" data-date="${date}" type="button">ещё ${items.length-3}</button>`:''}</section></article>`}).join('')}</div></section>`;}
  function calendarArchiveView(){const items=array('tasks').filter(taskIsArchived).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));return `<section class="v82-task-archive"><header><div><h2>Архив задач</h2><p>Выполненные и прошедшие задачи сохраняются здесь и не теряются.</p></div><b>${items.length}</b></header><div>${items.map(t=>calendarTaskCard(t)).join('')||'<div class="v78-empty-big">Архив пока пуст.</div>'}</div></section>`;}

  function calendarPage(){const view=calendarView();return `<section class="v78-page v82-calendar-page"><header class="v78-page-head"><div><span>Календарь событий</span><h1>Календарь</h1><p>День, неделя, месяц и архив задач. Любое событие можно отправить в Google Календарь.</p></div><button class="v78-primary" data-v82-action="quick-task-day" data-date="${calendarAnchor()}">＋ Добавить событие</button></header>${calendarNavigation()}${view==='day'?calendarDayView():view==='month'?calendarMonthView():view==='archive'?calendarArchiveView():calendarWeekView()}</section>`;}

  function assistantSteps(){
    const candidates=[],today=todayKey(),f=financeSnapshot(),priorityScore={critical:98,high:92,medium:82,low:68};
    array('tasks')
      .filter(task=>{const date=String(task.date||'').slice(0,10);return !taskStatusMeta(task.status).done&&date&&date<=today;})
      .sort((a,b)=>String(a.date||'').localeCompare(String(b.date||''))||(priorityScore[b.priority]||82)-(priorityScore[a.priority]||82))
      .slice(0,3)
      .forEach(task=>{
        const overdue=String(task.date||'').slice(0,10)<today;
        candidates.push({
          score:overdue?110:(priorityScore[task.priority]||82),
          icon:'▦',
          title:overdue?'Вернуть просроченную задачу под контроль':'Задача на сегодня',
          text:task.title||'Открыть календарь',
          reason:overdue?'Срок уже прошёл — решите, выполнить, перенести или отменить':'Запланировано на сегодня',
          route:'calendar',
          action:'Открыть календарь'
        });
      });
    const birthday=upcomingBirthdays(14)[0];
    if(birthday) candidates.push({
      score:birthday.days===0?105:birthday.days<=2?94:58,
      icon:'🎂',
      title:`${birthday.person.name}: важная дата`,
      text:birthday.days===0?'День рождения сегодня':`День рождения через ${birthday.days} дн.`,
      reason:birthday.days<=2?'Требует внимания сейчас':'Можно подготовиться заранее',
      route:'people',
      action:'Открыть анкету'
    });
    if(!state.discipline.financeChecks?.[today]) candidates.push({
      score:f.debtTotal>0?90:76,
      icon:'₽',
      title:f.debtTotal>0?'Проверить деньги и обязательства':'Финансовая проверка',
      text:f.debtTotal>0?`Сверьте баланс и активные обязательства на ${moneyText(f.debtTotal)}.`:'Сверьте фактический баланс перед решениями о расходах.',
      reason:f.debtTotal>0?'Есть активные обязательства':'Сегодня ещё не подтверждён фактический остаток',
      route:'finance',
      action:'Проверить финансы'
    });
    const activeGoal=array('goals').find(goal=>goal.status==='active'&&clean(goal.nextAction));
    if(activeGoal) candidates.push({
      score:86,
      icon:'🎯',
      title:'Следующий шаг цели',
      text:activeGoal.nextAction,
      reason:`Продвигает цель «${activeGoal.title||'Без названия'}»`,
      route:`goal-${encodeURIComponent(activeGoal.id)}`,
      action:'Открыть цель'
    });
    habitsActive().filter(habit=>!completedHabit(habit)).slice(0,2).forEach((habit,index)=>candidates.push({
      score:66-index,
      icon:habit.icon||'✓',
      title:index===0?'Поддержать главный ритм':'Следующая привычка',
      text:`Выполните «${habit.name}» в минимальной версии.`,
      reason:'Маленькое действие поддерживает устойчивость дня',
      route:`habit-${encodeURIComponent(habit.id)}`,
      action:'Открыть привычку'
    }));
    if(!todayInterview()) candidates.push({
      score:38,
      icon:'✦',
      title:'Короткая рефлексия',
      text:'Ответьте на три вопроса дня без долгого анализа.',
      reason:'Помогает закрыть день и заметить повторяющиеся причины',
      route:'subconscious',
      action:'Начать интервью'
    });
    const steps=candidates.sort((a,b)=>b.score-a.score);
    if(!steps.length) steps.push({score:0,icon:'✓',title:'Главное на сегодня закрыто',text:'Зафиксируйте результат и спокойно завершайте день.',reason:'Нет незавершённых приоритетных действий',route:'today',action:'Вернуться на главную'});
    return steps;
  }
  function currentAssistantStep(){const steps=assistantSteps();const index=Math.max(0,Math.min(number(state.settings.v82.coachStep)||0,steps.length-1));state.settings.v82.coachStep=index;return {steps,index,step:steps[index]};}
  function coachPage(){const f=financeSnapshot(),data=currentAssistantStep(),step=data.step;return `<section class="v78-page v82-coach-page"><header class="v78-page-head"><div><span>ПРИОРИТЕТЫ НА ОСНОВАНИИ ДАННЫХ</span><h1>Подсказчик AI</h1><p>Сначала показывает то, что срочно или сильнее влияет на цели, деньги и контроль дня.</p></div><button class="v78-secondary" data-v82-action="coach-reset" type="button">К первому приоритету</button></header><section class="v82-coach-hero"><div class="v82-coach-art"><span class="v78-brand-orb"></span><i>${safe(step.icon)}</i></div><div><span>ПРИОРИТЕТ ${data.index+1} ИЗ ${data.steps.length}</span><h2>${safe(step.title)}</h2><p>${safe(step.text)}</p><small class="v108-coach-why"><b>Почему сейчас:</b> ${safe(step.reason||'Это следующий понятный шаг')}</small><div><button class="v78-primary" data-v82-action="coach-open-current" type="button">${safe(step.action)} →</button><button class="v78-secondary" data-v82-action="coach-next" type="button">Следующий приоритет</button></div></div></section><section class="v82-coach-queue">${data.steps.map((item,index)=>`<button class="${index===data.index?'active':''} ${index<data.index?'passed':''}" data-v82-action="coach-select" data-index="${index}" type="button"><i>${safe(item.icon)}</i><span><small>Приоритет ${index+1}</small><b>${safe(item.title)}</b><em>${safe(item.text)}</em></span><strong>${index<data.index?'✓':index===data.index?'Сейчас':'›'}</strong></button>`).join('')}</section><section class="v78-kpi-row"><article><small>Баланс</small><b>${safe(moneyText(f.balance))}</b><span>фактический остаток</span></article><article><small>Обязательства</small><b>${safe(moneyText(f.debtTotal))}</b><span>${f.debts.length} активных</span></article><article><small>Привычки</small><b>${habitsDone()}/${habitsActive().length}</b><span>выполнено сегодня</span></article><article><small>Приоритетов осталось</small><b>${Math.max(0,data.steps.length-data.index)}</b><span>в текущей очереди</span></article></section></section>`;}
  function subconsciousPage(){
    const entries=array('subconsciousEntries').slice().sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))),questions=interviewQuestions(),done=todayInterview();
    const streak=(()=>{let n=0,d=todayKey();while(entries.some(e=>String(e.date||'').slice(0,10)===d)){n++;d=addDaysKey(d,-1);}return n;})();
    return `<section class="v78-page"><header class="v78-page-head"><div><button class="v78-back" data-v78-route="habits">← Привычки</button><span>Ежедневная осознанность</span><h1>Интервью с подсознанием</h1><p>Вопросы меняются каждый день и помогают заметить сопротивление без самокритики.</p></div><button class="v78-primary" data-v79-action="open-interview">${done?'Изменить ответы':'Начать интервью сегодня'}</button></header>
      <section class="v80-interview-hero"><div class="v80-interview-orb"><i></i><b></b><em></em></div><div><span>${formatDate(todayKey())}</span><h2>${done?'Сегодня вы уже остановились и услышали себя':'Три вопроса на сегодня'}</h2><p>${safe(questions[0])}</p><div><strong>${streak}</strong><small>${plural(streak,'день','дня','дней')} подряд с интервью</small></div></div></section>
      <section class="v80-question-grid">${questions.map((q,i)=>`<article><i>0${i+1}</i><span><small>${['Состояние','Сопротивление','Действие'][i]}</small><h2>${safe(q)}</h2></span></article>`).join('')}</section>
      <section class="v80-interview-history"><header><div><h2>История интервью</h2><p>Ответы хранятся только здесь и больше не попадают в заметки или личную память.</p></div></header><div>${entries.map(e=>{const qs=Array.isArray(e.questions)&&e.questions.length?e.questions:[{question:e.question||'Вопрос',answer:e.answer||e.note||''}];return `<article><header><span>${safe(formatDate(e.date||todayKey()))}</span><b>${safe(e.theme||'Ежедневное интервью')}</b></header>${qs.map(x=>`<div><small>${safe(x.question||'Вопрос')}</small><p>${safe(x.answer||'Без ответа')}</p></div>`).join('')}</article>`}).join('')||'<div class="v78-empty-big">Первое интервью появится после сохранения ответов.</div>'}</div></section></section>`;
  }
  function openInterview(){const existing=todayInterview(),questions=interviewQuestions(),answers=Array.isArray(existing?.questions)?existing.questions.map(x=>x.answer||''):[existing?.answer||'',...(String(existing?.note||'').split('\n'))];openModal('Сегодняшнее интервью',`<div class="v80-interview-modal"><header><span>${formatDate(todayKey())}</span><h2>Ответьте честно, но без требования идеального ответа</h2><p>Ответы можно изменить в течение дня.</p></header>${questions.map((q,i)=>`<label class="v79-field"><span><i>0${i+1}</i>${safe(q)}</span><textarea id="v80_int_${i}" placeholder="Запишите первое, что приходит в голову…">${safe(answers[i]||'')}</textarea></label>`).join('')}</div><div class="v79-modal-actions"><button class="v78-primary" data-v79-action="save-interview">Сохранить интервью</button><button data-v78-action="close-modal">Отмена</button></div>`);}
  function saveInterview(){const questions=interviewQuestions(),answers=questions.map((q,i)=>clean(document.getElementById(`v80_int_${i}`)?.value));const old=todayInterview();const item={id:old?.id||makeId(),date:todayKey(),theme:'Ежедневное интервью',question:questions[0],answer:answers[0],note:answers.slice(1).join('\n'),questions:questions.map((question,i)=>({question,answer:answers[i]})),createdAt:old?.createdAt||nowIso(),updatedAt:nowIso()};state.subconsciousEntries=state.subconsciousEntries.filter(e=>e.id!==old?.id);state.subconsciousEntries.unshift(item);save();closeModal();renderPremium();toast('Интервью сохранено');awardGame(`interview:${todayKey()}`,6,1,'awareness',{title:'Интервью с подсознанием'});celebrate(null,'✦');}

  function activateScheduledHabitIfDue(){const scheduled=state.settings.v86?.scheduledHabit;if(!scheduled?.wishlistId||scheduled.activatedAt||String(scheduled.activateOn)>todayKey())return false;const item=state.habitWishlist.find(row=>row.id===scheduled.wishlistId);if(!item){scheduled.activatedAt=nowIso();return false;}const existing=array('habits').find(h=>clean(h.name).toLowerCase()===clean(item.title).toLowerCase());if(!existing)state.habits.unshift({id:makeId(),name:item.title,icon:item.icon||'✦',color:'#8b5cf6',target:1,unit:'раз',frequency:item.schedule||'Ежедневно',marks:{},active:true,note:item.note||'Добавлено автоматически из недельного вишлиста',createdAt:nowIso(),updatedAt:nowIso()});scheduled.activatedAt=nowIso();save();toast(existing?'Запланированная привычка уже была активна':'Новая привычка недели активирована');return !existing;}
  async function autoDailySnapshot(force=false){try{if(!state.settings.v86.autoBackup&&!force)return false;const date=todayKey();if(!force&&state.settings.v86.lastDailySnapshot===date)return false;await coreDbPut(`daily:v86:${date}:${Date.now()}`,{version:86,createdAt:nowIso(),reason:force?'manual-snapshot':'automatic-daily-snapshot',state:coreClone(state)});state.settings.v86.lastDailySnapshot=date;const keys=(await coreDbKeys()).filter(key=>String(key).startsWith('daily:v86:')).sort().reverse();for(const key of keys.slice(14))await coreDbDelete(key);save();return true;}catch(error){console.warn('[V86 snapshot]',error);return false;}}
  async function snapshotRows(){try{const keys=(await coreDbKeys()).filter(key=>String(key).startsWith('daily:v86:')||String(key).startsWith('backup:v85-before-v86:')).sort().reverse().slice(0,20);const rows=[];for(const key of keys){const value=await coreDbGet(key);rows.push({key,value});}return rows;}catch(error){return [];}}
  async function openSnapshots(){const rows=await snapshotRows();openModal('Локальные резервные копии',`<div class="v86-snapshot-list">${rows.map(row=>`<article><i>▣</i><span><b>${safe(row.value?.reason||'Резервная копия')}</b><small>${safe(formatDate(row.value?.createdAt||todayKey()))}</small></span><button data-v86-action="restore-snapshot" data-key="${safe(row.key)}">Восстановить</button></article>`).join('')||'<div class="v78-empty-big">Локальных снимков пока нет.</div>'}</div><div class="v79-modal-actions"><button class="v78-primary" data-v86-action="make-snapshot">Создать снимок сейчас</button><button data-v78-action="close-modal">Закрыть</button></div>`);}
  async function restoreSnapshot(key){if(!confirm('Восстановить выбранный снимок? Текущее состояние сначала будет сохранено отдельной копией.'))return;const record=await coreDbGet(key);if(!record?.state)return toast('Снимок не найден');await autoDailySnapshot(true);state=coreNormalize(coreClone(record.state));ensureData();save();closeModal();renderPremium();toast('Снимок восстановлен');}
  function estimatedStorage(){try{return new Blob([JSON.stringify(state)]).size;}catch(error){return 0;}}
  function automationSettingsHtml(){const v=state.settings.v86,s=state.settings.v85;return `<section class="v86-automation-center"><article><header><i>⚡</i><div><h2>Автопилот дня</h2><p>Мягкие ритуалы без обязательного заполнения.</p></div></header>${switchRow('Автоматические подсказки','Check-in, вечерний итог и недельный разбор','v86_auto_prompts',s.autoPrompts)}${switchRow('Автоперенос задач','Незавершённые задачи можно переносить на завтра','v86_carry_tasks',v.carryTasksToTomorrow)}${switchRow('Автозадачи целей','Следующий этап создаёт задачу автоматически','v86_goal_tasks',v.autoCreateGoalTasks)}</article><article><header><i>▣</i><div><h2>Защита данных</h2><p>Ежедневные локальные снимки в IndexedDB.</p></div></header>${switchRow('Автоматический backup','Хранить последние 14 ежедневных снимков','v86_auto_backup',v.autoBackup)}<div class="v86-switch-row"><span><b>Последний снимок</b><small>${safe(v.lastDailySnapshot?formatDate(v.lastDailySnapshot):'Ещё не создан')}</small></span><button data-v86-action="open-snapshots">Открыть</button></div><div class="v86-switch-row"><span><b>Настройки автопилота</b><small>Сохранить переключатели</small></span><button class="v78-primary" data-v86-action="save-automation-settings">Сохранить</button></div></article></section>`;}
  function switchRow(title,text,id,checked){return `<div class="v86-switch-row"><span><b>${safe(title)}</b><small>${safe(text)}</small></span><label class="v86-switch"><input id="${id}" type="checkbox" ${checked?'checked':''}><i></i></label></div>`;}
  function saveAutomationSettings(){state.settings.v85.autoPrompts=Boolean(document.getElementById('v86_auto_prompts')?.checked);state.settings.v86.carryTasksToTomorrow=Boolean(document.getElementById('v86_carry_tasks')?.checked);state.settings.v86.autoCreateGoalTasks=Boolean(document.getElementById('v86_goal_tasks')?.checked);state.settings.v86.autoBackup=Boolean(document.getElementById('v86_auto_backup')?.checked);save();renderPremium();toast('Настройки автопилота сохранены');}
  function systemPage(){const stats=[['Операции',array('operations').length],['Долги',array('debts').length],['Задачи',array('tasks').length],['Покупки',array('purchases').length],['Желания',array('wishes').length],['Заметки',array('notes').length],['Идеи',array('ideas').length],['Люди',array('people').length],['Привычки',array('habits').length],['Цели',array('goals').length],['Документы',array('documents').length],['Книги',array('books').length],['Фильмы',array('films').length],['Поездки',array('trips').length],['Личная память',array('personal').length]],bytes=estimatedStorage();return `<section class="v78-page"><header class="v78-page-head"><div><span>Автопилот и защита данных</span><h1>Настройки</h1><p>Фирменный интерфейс остаётся прежним, а автоматизация и резервные копии работают поверх него.</p></div></header>${automationSettingsHtml()}<section class="v86-health-grid"><article><small>Состояние хранения</small><b>${document.body.dataset.sbosStorage==='indexeddb-only'?'IndexedDB':'Local + IndexedDB'}</b><span>двойная локальная запись</span></article><article><small>Размер данных</small><b>${(bytes/1024).toFixed(1)} КБ</b><span>без изображений по URL</span></article><article><small>Очередь разбора</small><b>${reviewQueueCount()}</b><span>элементов без решения</span></article><article><small>Версия</small><b>V86.7</b><span>Лимиты и финансовый помощник</span></article></section><section class="v79-system-actions"><article><i>⇩</i><div><h2>Резервная копия JSON</h2><p>Скачайте переносимый файл перед крупными изменениями.</p></div><button data-v79-action="export-data">Скачать</button></article><article><i>⇧</i><div><h2>Импорт данных</h2><p>Верните ранее сохранённую JSON-копию.</p></div><label><input id="v79_import_file" type="file" accept="application/json"><span>Выбрать</span></label></article><article><i>↻</i><div><h2>Обновить интерфейс</h2><p>Удаляет только кэш файлов, личные данные остаются.</p></div><button data-v79-action="clear-ui-cache">Очистить кэш</button></article></section><section class="v79-data-stats">${stats.map(([l,v])=>`<article><small>${l}</small><b>${v}</b></article>`).join('')}</section></section>`;}

  function polinaPage(){const key=state.settings.polinaMonth||monthKey(todayKey());const [y,m]=key.split('-').map(Number);const first=new Date(y,m-1,1,12),days=new Date(y,m,0,12).getDate(),offset=(first.getDay()+6)%7;const cells=Array(offset).fill('').concat(Array.from({length:days},(_,i)=>`${key}-${String(i+1).padStart(2,'0')}`));const entries=new Map(array('polinaDays').map(e=>[String(e.date).slice(0,10),e]));const forecast=polinaCycleForecast();return `<section class="v78-page"><header class="v78-page-head"><div><button class="v78-back" data-v78-route="information">← Информация</button><span>Состояние и цикл</span><h1>Состояние Полины</h1><p>Хорошее — зелёным, нейтральное — жёлтым, плохое — красным. Заполняется вся ячейка. Прогноз строится по уже отмеченным циклам.</p></div><div><button class="v78-secondary" data-v79-action="polina-month" data-delta="-1">←</button><button class="v78-primary" data-v79-action="polina-month" data-delta="1">→</button></div></header><section class="v85-polina-forecast"><article><small>Следующие месячные</small><b>${forecast.nextStart?formatDate(forecast.nextStart):'Нужно больше данных'}</b><span>${forecast.nextStart?`ориентир на ${forecast.avgCycle} дней цикла`: 'Отметьте хотя бы 2 начала цикла'}</span></article><article><small>Средняя длина цикла</small><b>${forecast.avgCycle?`${forecast.avgCycle} дн.`:'—'}</b><span>${forecast.cycles>=2?`${forecast.cycles} сохранённых цикла`: 'Пока недостаточно истории'}</span></article><article><small>Средняя длительность</small><b>${forecast.avgPeriod?`${forecast.avgPeriod} дн.`:'—'}</b><span>${forecast.nextEnd?`прогноз окончания ${formatDate(forecast.nextEnd)}`:'Обычно по последним отметкам'}</span></article></section><section class="v79-polina-card"><header><h2>${new Date(`${key}-01T12:00:00`).toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}</h2><div><span class="good">Хорошее</span><span class="neutral">Нейтральное</span><span class="bad">Плохое</span></div></header><div class="v79-weekdays">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(x=>`<span>${x}</span>`).join('')}</div><div class="v79-polina-grid">${cells.map(date=>{if(!date)return '<i></i>';const e=entries.get(date)||{};const isForecast=forecast.nextStart&&date>=forecast.nextStart&&date<=forecast.nextEnd&&!e.periodMarker;const statusLabel=e.status==='good'?'Хорошее':e.status==='neutral'?'Нейтральное':e.status==='bad'?'Плохое':isForecast?'Прогноз цикла':'Без отметки';return `<button class="${safe(e.status||'')} ${e.periodMarker?'period':''} ${isForecast?'forecast':''}" data-v79-action="open-polina-day" data-date="${date}"><b>${Number(date.slice(8))}</b><span>${safe(statusLabel)}</span><small>${safe(e.comment||(isForecast?'Можно заранее учитывать самочувствие':'Добавить комментарий'))}</small>${e.periodMarker?`<em>${e.periodMarker==='start'?'Начало':e.periodMarker==='end'?'Конец':'Месячные'}</em>`:isForecast?'<em class="v85-forecast-tag">Прогноз</em>':''}</button>`}).join('')}</div></section></section>`;}

  function openPolinaDay(date){const e=array('polinaDays').find(x=>x.date===date)||{};openModal(`Состояние Полины · ${formatDate(date)}`,`<div class="v79-form-grid"><label class="v79-field"><span>Состояние</span><select id="v79_p_status"><option value="">Без отметки</option><option value="good" ${e.status==='good'?'selected':''}>Хорошее</option><option value="neutral" ${e.status==='neutral'?'selected':''}>Нейтральное</option><option value="bad" ${e.status==='bad'?'selected':''}>Плохое</option></select></label><label class="v79-field"><span>Цикл</span><select id="v79_p_period"><option value="">Нет отметки</option><option value="start" ${e.periodMarker==='start'?'selected':''}>Начало месячных</option><option value="period" ${e.periodMarker==='period'?'selected':''}>Месячные</option><option value="end" ${e.periodMarker==='end'?'selected':''}>Конец месячных</option></select></label><label class="v79-field span-2"><span>Комментарий</span><textarea id="v79_p_comment">${safe(e.comment||'')}</textarea></label></div><div class="v79-modal-actions"><button class="v78-primary" data-v79-action="save-polina-day" data-date="${date}">Сохранить</button><button data-v78-action="close-modal">Отмена</button></div>`);}
  function savePolinaDay(date){const status=clean(document.getElementById('v79_p_status')?.value),periodMarker=clean(document.getElementById('v79_p_period')?.value),comment=clean(document.getElementById('v79_p_comment')?.value);const old=array('polinaDays').find(x=>x.date===date);state.polinaDays=array('polinaDays').filter(x=>x.date!==date);if(status||periodMarker||comment)state.polinaDays.push({id:old?.id||makeId(),date,status,periodMarker,comment,updatedAt:nowIso()});save();closeModal();renderPremium();toast('Состояние сохранено');}

  const enc=new TextEncoder(),dec=new TextDecoder();
  const bytesToB64=bytes=>{let s='';new Uint8Array(bytes).forEach(b=>s+=String.fromCharCode(b));return btoa(s)};const b64ToBytes=v=>{const s=atob(String(v||'')),a=new Uint8Array(s.length);for(let i=0;i<s.length;i++)a[i]=s.charCodeAt(i);return a};
  async function vaultKey(password,salt,iterations=310000){const base=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations,hash:'SHA-256'},base,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);}
  async function vaultEncrypt(entries,key,salt,iterations=310000){const iv=crypto.getRandomValues(new Uint8Array(12)),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,enc.encode(JSON.stringify({entries})));return {version:1,cipher:'AES-GCM-256',kdf:'PBKDF2-SHA256',iterations,salt:bytesToB64(salt),iv:bytesToB64(iv),ciphertext:bytesToB64(cipher),updatedAt:nowIso()};}
  async function vaultDecrypt(vault,key){const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:b64ToBytes(vault.iv)},key,b64ToBytes(vault.ciphertext));return JSON.parse(dec.decode(plain)).entries||[];}
  function passwordsPage(){const vault=state.passwordVault;if(!vault)return `<section class="v78-page"><header class="v78-page-head"><div><button class="v78-back" data-v78-route="information">← Информация</button><span>Зашифрованная папка</span><h1>Пароли и доступы</h1><p>Мастер-пароль нигде не сохраняется.</p></div></header><section class="v79-vault-box"><i>🔐</i><h2>Создать защищённое хранилище</h2><input id="v79_vault_new" type="password" placeholder="Мастер-пароль, минимум 10 символов"><input id="v79_vault_repeat" type="password" placeholder="Повторите пароль"><button class="v78-primary" data-v79-action="create-vault">Создать</button></section></section>`;if(!vaultSession.unlocked)return `<section class="v78-page"><header class="v78-page-head"><div><button class="v78-back" data-v78-route="information">← Информация</button><span>Зашифрованная папка</span><h1>Пароли и доступы</h1><p>Данные сохранены и заблокированы.</p></div></header><section class="v79-vault-box"><i>🔒</i><h2>Разблокировать</h2><input id="v79_vault_unlock" type="password" placeholder="Введите мастер-пароль"><button class="v78-primary" data-v79-action="unlock-vault">Открыть</button></section></section>`;return `<section class="v78-page"><header class="v78-page-head"><div><button class="v78-back" data-v78-route="information">← Информация</button><span>Зашифрованная папка</span><h1>Пароли и доступы</h1><p>${vaultSession.entries.length} записей. Автоблокировка через 15 минут.</p></div><div><button class="v78-secondary" data-v79-action="lock-vault">Заблокировать</button><button class="v78-primary" data-v79-action="open-vault-entry">＋ Запись</button></div></header><section class="v79-vault-grid">${vaultSession.entries.map(e=>`<article><header><i>🔑</i><div><small>${safe(e.category||'Другое')}</small><h2>${safe(e.title||'Без названия')}</h2></div></header><p><b>${safe(e.login||'—')}</b></p><p class="secret">${vaultSession.revealed.has(e.id)?safe(e.secret||'—'):'••••••••••••'}</p><footer><button data-v79-action="reveal-vault" data-id="${safe(e.id)}">${vaultSession.revealed.has(e.id)?'Скрыть':'Показать'}</button><button data-v79-action="copy-vault" data-id="${safe(e.id)}">Копировать</button><button data-v79-action="open-vault-entry" data-id="${safe(e.id)}">Изменить</button></footer></article>`).join('')||'<div class="v78-empty-big">Хранилище пустое.</div>'}</section></section>`;}
  async function createVault(){const p=String(document.getElementById('v79_vault_new')?.value||''),r=String(document.getElementById('v79_vault_repeat')?.value||'');if(p.length<10)return toast('Минимум 10 символов');if(p!==r)return toast('Пароли не совпадают');const salt=crypto.getRandomValues(new Uint8Array(16)),key=await vaultKey(p,salt);state.passwordVault=await vaultEncrypt([],key,salt);vaultSession={key,entries:[],unlocked:true,revealed:new Set(),lastActivity:Date.now()};save();renderPremium();}
  async function unlockVault(){try{const p=String(document.getElementById('v79_vault_unlock')?.value||''),v=state.passwordVault,key=await vaultKey(p,b64ToBytes(v.salt),Number(v.iterations)||310000),entries=await vaultDecrypt(v,key);vaultSession={key,entries,unlocked:true,revealed:new Set(),lastActivity:Date.now()};renderPremium();toast('Хранилище открыто');}catch(error){toast('Неверный мастер-пароль');}}
  function openVaultEntry(id=''){const e=vaultSession.entries.find(x=>x.id===id)||{};openModal(id?'Изменить запись':'Новая запись',`<div class="v79-form-grid"><label class="v79-field"><span>Название</span><input id="v79_ve_title" value="${safe(e.title||'')}"></label><label class="v79-field"><span>Категория</span><input id="v79_ve_category" value="${safe(e.category||'')}"></label><label class="v79-field"><span>Логин</span><input id="v79_ve_login" value="${safe(e.login||'')}"></label><label class="v79-field"><span>Пароль / секрет</span><input id="v79_ve_secret" value="${safe(e.secret||'')}"></label><label class="v79-field span-2"><span>Ссылка</span><input id="v79_ve_url" value="${safe(e.url||'')}"></label><label class="v79-field span-2"><span>Комментарий</span><textarea id="v79_ve_note">${safe(e.note||'')}</textarea></label></div><div class="v79-modal-actions"><button class="v78-primary" data-v79-action="save-vault-entry" data-id="${safe(id)}">Сохранить</button><button data-v78-action="close-modal">Отмена</button></div>`);}
  async function saveVaultEntry(id){const e={id:id||makeId(),title:clean(document.getElementById('v79_ve_title')?.value)||'Без названия',category:clean(document.getElementById('v79_ve_category')?.value)||'Другое',login:clean(document.getElementById('v79_ve_login')?.value),secret:String(document.getElementById('v79_ve_secret')?.value||''),url:clean(document.getElementById('v79_ve_url')?.value),note:clean(document.getElementById('v79_ve_note')?.value),updatedAt:nowIso()};vaultSession.entries=vaultSession.entries.filter(x=>x.id!==id);vaultSession.entries.unshift(e);state.passwordVault=await vaultEncrypt(vaultSession.entries,vaultSession.key,b64ToBytes(state.passwordVault.salt),Number(state.passwordVault.iterations)||310000);save();closeModal();renderPremium();toast('Запись сохранена');}

  function dailyCheckInToday(){return state.gameLife.checkIns.find(item=>String(item.date||'').slice(0,10)===todayKey());}
  function eveningReviewToday(){return state.gameLife.eveningReviews.find(item=>String(item.date||'').slice(0,10)===todayKey());}
  function weekStartKey(value=todayKey()){const d=dateAtNoon(value),day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return d.toISOString().slice(0,10);}
  function currentWeeklyReview(){const key=weekStartKey();return state.gameLife.weeklyReviews.find(item=>item.week===key);}
  function dayMetrics(date=todayKey()){const habits=habitsActive(),habitDone=habits.filter(h=>Boolean(h.marks?.[date])).length,tasks=array('tasks').filter(t=>String(t.date||'').slice(0,10)===date),tasksDone=tasks.filter(t=>taskStatusMeta(t.status).done).length,expense=array('operations').filter(o=>operationKind(o)==='expense'&&operationDate(o)===date).reduce((sum,o)=>sum+operationAmount(o),0),captures=state.gameLife.captures.filter(c=>String(c.date||'').slice(0,10)===date).length;return {habitDone,habitTotal:habits.length,tasksDone,tasksTotal:tasks.length,expense,captures};}
  function weekMetrics(){const start=weekStartKey(),dates=Array.from({length:7},(_,i)=>addDaysKey(start,i)),habitMarks=habitsActive().reduce((sum,h)=>sum+dates.filter(date=>h.marks?.[date]).length,0),habitPossible=habitsActive().length*7,tasks=array('tasks').filter(t=>dates.includes(String(t.date||'').slice(0,10))),tasksDone=tasks.filter(t=>taskStatusMeta(t.status).done).length,expense=array('operations').filter(o=>operationKind(o)==='expense'&&dates.includes(operationDate(o))).reduce((sum,o)=>sum+operationAmount(o),0),captures=state.gameLife.captures.filter(c=>dates.includes(String(c.date||'').slice(0,10))).length;const dayScores=dates.map(date=>({date,score:habitsActive().filter(h=>h.marks?.[date]).length+array('tasks').filter(t=>String(t.date||'').slice(0,10)===date&&taskStatusMeta(t.status).done).length})).sort((a,b)=>b.score-a.score);return {start,dates,habitMarks,habitPossible,tasksDone,tasksTotal:tasks.length,expense,captures,bestDay:dayScores[0]};}
  function openDailyCheckIn(){const old=dailyCheckInToday()||{};openModal('Утренний check-in',`<div class="v85-checkin-form"><p>Это не планирование всего дня. Достаточно зафиксировать состояние и одно главное действие.</p><label class="v79-field"><span>Состояние сейчас</span><div class="v85-mood-picker">${[['1','😣'],['2','😕'],['3','😐'],['4','🙂'],['5','🔥']].map(([v,i])=>`<label><input type="radio" name="v85_mood" value="${v}" ${String(old.mood||3)===v?'checked':''}><span>${i}</span></label>`).join('')}</div></label><label class="v79-field"><span>Что сегодня главное?</span><input id="v85_checkin_focus" value="${safe(old.focus||'')}" placeholder="Одно конкретное действие"></label><label class="v79-field"><span>Что нельзя забыть?</span><input id="v85_checkin_remember" value="${safe(old.remember||'')}" placeholder="Необязательное поле"></label><label class="v79-field"><span>Короткая заметка</span><textarea id="v85_checkin_note">${safe(old.note||'')}</textarea></label></div><div class="v79-modal-actions"><button class="v78-primary" data-v85-action="save-daily-checkin">Сохранить check-in</button><button data-v78-action="close-modal">Пропустить</button></div>`);}
  function saveDailyCheckIn(originEl=null){const old=dailyCheckInToday(),entry={id:old?.id||makeId(),date:todayKey(),mood:number(document.querySelector('input[name="v85_mood"]:checked')?.value)||3,focus:clean(document.getElementById('v85_checkin_focus')?.value),remember:clean(document.getElementById('v85_checkin_remember')?.value),note:clean(document.getElementById('v85_checkin_note')?.value),createdAt:old?.createdAt||nowIso(),updatedAt:nowIso()};state.gameLife.checkIns=state.gameLife.checkIns.filter(item=>String(item.date||'').slice(0,10)!==todayKey());state.gameLife.checkIns.unshift(entry);awardGame(`checkin:${todayKey()}`,3,1,'awareness',{title:'Утренний check-in'});syncAchievements();save();closeModal();renderPremium();toast('Главный фокус дня сохранён');celebrate(originEl,'☀️');}
  function openEveningReview(){const old=eveningReviewToday()||{},m=dayMetrics();openModal('Завершение дня',`<div class="v85-evening-summary"><header><small>АВТОМАТИЧЕСКИЙ ИТОГ</small><h2>${m.habitDone}/${m.habitTotal} привычек · ${m.tasksDone}/${m.tasksTotal} задач</h2><p>Расходы: ${safe(moneyText(m.expense))} · быстрых записей: ${m.captures}</p></header><label class="v79-field"><span>Что сегодня сработало лучше всего?</span><textarea id="v85_evening_win" placeholder="Одна маленькая победа">${safe(old.win||'')}</textarea></label><label class="v79-field"><span>Что перенести или упростить завтра?</span><textarea id="v85_evening_next">${safe(old.next||'')}</textarea></label><label class="v79-field"><span>Энергия вечером, 1–5</span><input id="v85_evening_energy" type="number" min="1" max="5" value="${number(old.energy)||3}"></label></div><div class="v79-modal-actions"><button class="v78-primary" data-v85-action="save-evening-review">Завершить день</button><button data-v78-action="close-modal">Позже</button></div>`);}
  function saveEveningReview(originEl=null){const old=eveningReviewToday(),entry={id:old?.id||makeId(),date:todayKey(),metrics:dayMetrics(),win:clean(document.getElementById('v85_evening_win')?.value),next:clean(document.getElementById('v85_evening_next')?.value),energy:Math.min(5,Math.max(1,number(document.getElementById('v85_evening_energy')?.value)||3)),createdAt:old?.createdAt||nowIso(),updatedAt:nowIso()};state.gameLife.eveningReviews=state.gameLife.eveningReviews.filter(item=>String(item.date||'').slice(0,10)!==todayKey());state.gameLife.eveningReviews.unshift(entry);if(state.settings.v86.carryTasksToTomorrow){array('tasks').forEach(task=>{if(String(task.date||'').slice(0,10)===todayKey()&&!taskStatusMeta(task.status).done){task.date=addDaysKey(todayKey(),1);task.updatedAt=nowIso();}});}awardGame(`evening:${todayKey()}`,5,2,'awareness',{title:'День завершён'});syncAchievements();save();closeModal();renderPremium();toast('Итог дня сохранён');celebrate(originEl,'🌙');}
  function openWeeklyReview(){const old=currentWeeklyReview()||{},m=weekMetrics(),wishlist=state.habitWishlist||[],scheduled=state.settings.v86.scheduledHabit||{};openModal('Недельный разбор',`<div class="v85-weekly-review"><div class="v85-weekly-stats"><article><small>Привычки</small><b>${m.habitMarks}/${m.habitPossible}</b></article><article><small>Задачи</small><b>${m.tasksDone}/${m.tasksTotal}</b></article><article><small>Расходы</small><b>${safe(moneyText(m.expense))}</b></article><article><small>Лучший день</small><b>${m.bestDay?.score?formatShort(m.bestDay.date):'—'}</b></article></div><label class="v79-field"><span>Главная победа недели</span><textarea id="v85_week_win">${safe(old.win||'')}</textarea></label><label class="v79-field"><span>Что чаще всего мешало?</span><textarea id="v85_week_obstacle">${safe(old.obstacle||'')}</textarea></label><label class="v79-field"><span>Один фокус следующей недели</span><input id="v85_week_focus" value="${safe(old.focus||'')}" placeholder="Только один приоритет"></label><div class="v86-week-habit"><label class="v79-field"><span>Следующая привычка из вишлиста</span><select id="v86_week_habit"><option value="">Не добавлять новую привычку</option>${wishlist.map(item=>`<option value="${safe(item.id)}" ${String(old.nextHabitId||scheduled.wishlistId||'')===String(item.id)?'selected':''}>${safe(item.icon||'✦')} ${safe(item.title)}</option>`).join('')}</select></label><label style="display:flex;align-items:center;gap:10px"><input id="v86_activate_habit" type="checkbox" ${old.activateNextHabit||scheduled.wishlistId?'checked':''}><span>Автоматически активировать в следующий понедельник</span></label></div></div><div class="v79-modal-actions"><button class="v78-primary" data-v85-action="save-weekly-review">Сохранить разбор</button><button data-v78-action="close-modal">Позже</button></div>`);}
  function saveWeeklyReview(originEl=null){const key=weekStartKey(),old=currentWeeklyReview(),nextHabitId=clean(document.getElementById('v86_week_habit')?.value),activateNextHabit=Boolean(document.getElementById('v86_activate_habit')?.checked),entry={id:old?.id||makeId(),week:key,date:todayKey(),metrics:weekMetrics(),win:clean(document.getElementById('v85_week_win')?.value),obstacle:clean(document.getElementById('v85_week_obstacle')?.value),focus:clean(document.getElementById('v85_week_focus')?.value),nextHabitId,activateNextHabit,createdAt:old?.createdAt||nowIso(),updatedAt:nowIso()};state.gameLife.weeklyReviews=state.gameLife.weeklyReviews.filter(item=>item.week!==key);state.gameLife.weeklyReviews.unshift(entry);const reviewTask=array('tasks').find(task=>task?.automationKey===`weekly-review:${key}`);if(reviewTask){reviewTask.status='done';reviewTask.completedAt=nowIso();reviewTask.updatedAt=reviewTask.completedAt;}if(nextHabitId&&activateNextHabit)state.settings.v86.scheduledHabit={wishlistId:nextHabitId,activateOn:addDaysKey(weekStartKey(),7),scheduledAt:nowIso(),activatedAt:''};else if(!activateNextHabit)state.settings.v86.scheduledHabit=null;awardGame(`weekly:${key}`,15,5,'awareness',{title:'Недельный разбор'});syncAchievements();save();closeModal();renderPremium();toast(nextHabitId&&activateNextHabit?'Разбор сохранён. Привычка запланирована на понедельник.':'Фокус следующей недели сохранён');celebrate(originEl,'✦');}
  function dailyAutomationStrip(){const checkin=dailyCheckInToday(),evening=eveningReviewToday(),weekly=currentWeeklyReview(),hour=new Date().getHours(),queue=reviewQueueCount();return `<section class="v85-automation-strip"><button class="${checkin?'done':''}" data-v85-action="daily-checkin"><i>${checkin?'✓':'☀️'}</i><span><b>Check-in</b><small>${checkin?safe(checkin.focus||'Сохранён'):'30 секунд утром'}</small></span></button><button class="${evening?'done':''}" data-v85-action="evening-review"><i>${evening?'✓':'🌙'}</i><span><b>Итог дня</b><small>${evening?'День завершён':hour>=19?'Пора подвести итог':'Откроется вечером'}</small></span></button><button class="${weekly?'done':''}" data-v85-action="weekly-review"><i>${weekly?'✓':'📊'}</i><span><b>Разбор недели</b><small>${weekly?safe(weekly.focus||'Сохранён'):new Date().getDay()===0?'Доступен сегодня':'Можно заполнить заранее'}</small></span></button>${queue?`<button data-v78-route="review-queue"><i>◇</i><span><b>Разобрать</b><small>${queue} ${plural(queue,'элемент','элемента','элементов')}</small></span></button>`:''}</section>`;}
  function dailyRoutineCards(){const checkin=dailyCheckInToday(),evening=eveningReviewToday(),weekly=currentWeeklyReview();return `${card('Утренний check-in',checkin?'Сохранён сегодня':'30 секунд',`<div class="v85-routine-card"><i>☀️</i><div><b>${safe(checkin?.focus||'Выберите одно главное действие')}</b><p>${checkin?`Настроение ${checkin.mood}/5`:'Состояние, фокус и что нельзя забыть.'}</p></div><button data-v85-action="daily-checkin">${checkin?'Изменить':'Заполнить'}</button></div>`,'v85-routine')}${card('Вечерний итог',evening?'День завершён':'Автосводка',`<div class="v85-routine-card"><i>🌙</i><div><b>${safe(evening?.win||'Приложение соберёт факты за день')}</b><p>${evening?'Итог сохранён':'Привычки, задачи, расходы и одна победа.'}</p></div><button data-v85-action="evening-review">${evening?'Открыть':'Подвести итог'}</button></div>`,'v85-routine')}${card('Недельный разбор',weekly?'Сохранён':'Автосводка недели',`<div class="v85-routine-card"><i>📊</i><div><b>${safe(weekly?.focus||'Один фокус на следующую неделю')}</b><p>${weekly?'Фокус определён':'Система сама соберёт статистику.'}</p></div><button data-v85-action="weekly-review">${weekly?'Открыть':'Разобрать'}</button></div>`,'v85-routine')}`;}
  function reviewQueueItems(){const dismissed=new Set(state.settings.v85.reviewQueueDismissed||[]),snoozed=state.settings.v86.queueSnoozed||{},items=[];array('operations').forEach(item=>{if(!clean(item.category)||['без категории','быстрая запись','не назначена','не определена'].includes(clean(item.category).toLowerCase()))items.push({id:`operation:${item.id}`,icon:'₽',title:item.note||`Операция ${moneyText(item.amount)}`,reason:'Нужно указать понятную категорию',route:'finance-operations',action:'quick-category',recordId:item.id});});array('inbox').forEach(item=>items.push({id:`inbox:${item.id}`,icon:'📥',title:item.title||item.text||'Входящая запись',reason:'Нужно решить: задача, событие, заметка, финансовая операция, цель, человек, архив или удаление',route:'inbox',action:'edit-record',recordId:item.id,recordType:'inbox'}));array('goals').forEach(item=>{if(item.status==='active'&&!clean(item.nextAction))items.push({id:`goal:${item.id}`,icon:'🎯',title:item.title,reason:'У активной цели нет конкретного следующего шага',route:`goal-${encodeURIComponent(item.id)}`});});return items.filter(item=>!dismissed.has(item.id)&&(!snoozed[item.id]||String(snoozed[item.id])<todayKey()));}
  function reviewQueueCount(){return reviewQueueItems().length;}
  function reviewQueuePage(){
    const items=reviewQueueItems();
    if(!items.length){
      return `<section class="v78-page v85-queue-page v101-queue-complete"><header class="v78-page-head"><div><span>Автоматическая очередь</span><h1>Разобрать</h1><p>Здесь появляются только записи, которым действительно не хватает категории или следующего решения.</p></div></header><section class="v101-empty-success"><i>✓</i><div><h2>Очередь полностью разобрана</h2><p>Новых элементов без решения нет. Ложные напоминания и старые флаги категорий больше не учитываются.</p></div><button data-v78-route="today" type="button">Вернуться к дню →</button></section></section>`;
    }
    return `<section class="v78-page v85-queue-page"><header class="v78-page-head"><div><span>Автоматическая очередь</span><h1>Разобрать</h1><p>Здесь только записи, которым не хватает следующего решения. Разбирайте по три элемента, а не всю очередь сразу.</p></div><div><button class="v78-secondary" data-v85-action="reset-queue-dismissed" type="button">Вернуть скрытые</button><button class="v78-primary" data-v83-action="quick-capture" type="button">＋ Зафиксировать</button></div></header><section class="v85-queue-summary"><article><small>Требуют решения</small><b>${items.length}</b><span>формируется автоматически</span></article><article><small>Рекомендуемая порция</small><b>${Math.min(3,items.length)}</b><span>не перегружает вниманием</span></article></section><section class="v85-queue-list">${items.map((item,index)=>`<article class="${index<3?'focus':''}"><i>${item.icon}</i><span><small>${index<3?'РАЗОБРАТЬ СЕЙЧАС':'ПОЗЖЕ'}</small><b>${safe(item.title)}</b><p>${safe(item.reason)}</p></span><div>${item.action==='quick-category'?`<button data-v81-action="quick-category" data-id="${safe(item.recordId)}">Исправить</button>`:item.action==='edit-record'?`<button data-v79-action="edit-record" data-type="${safe(item.recordType)}" data-id="${safe(item.recordId)}">Открыть</button>`:`<button data-v78-route="${safe(item.route)}">Открыть</button>`}<button class="ghost" data-v86-action="snooze-queue" data-id="${safe(item.id)}">На 7 дней</button><button class="ghost" data-v85-action="dismiss-queue" data-id="${safe(item.id)}">Скрыть</button></div></article>`).join('')}</section></section>`;
  }
  function dismissQueueItem(id){state.settings.v85.reviewQueueDismissed=[...new Set([...(state.settings.v85.reviewQueueDismissed||[]),id])];save();renderPremium();toast('Элемент скрыт из очереди');}
  function goalAutomationItems(){const now=Date.now(),items=[];array('goals').filter(goal=>goal.status==='active').forEach(goal=>{const mode=goalExecutionMode(goal),habits=linkedHabitsForGoal(goal),linked=array('tasks').filter(t=>t.goalId===goal.id&&!taskStatusMeta(t.status).done);let last=new Date(goal.lastActivityAt||goal.updatedAt||goal.createdAt||0).getTime();habits.forEach(habit=>{const latest=Object.entries(habit.marks||{}).filter(([,done])=>done).map(([date])=>dateAtNoon(date).getTime()).sort((a,b)=>b-a)[0]||0;if(latest>last)last=latest;});const days=last?Math.floor((now-last)/DAY):99;if(mode!=='actions'&&!habits.length)items.push({goal,type:'habit',text:'Выбран режим с привычками, но связь ещё не настроена'});if(!clean(goal.nextAction))items.push({goal,type:'next',text:'Нет следующего конкретного шага'});else if(mode!=='habits'&&!linked.length)items.push({goal,type:'task',text:'Следующий шаг ещё не превращён в задачу'});if(days>=5)items.push({goal,type:'stale',text:`Нет движения ${days} дней`});});return items;}
  function goalAutomationHtml(items){return `<div class="v85-goal-automation">${items.slice(0,6).map(item=>`<article><i>${item.type==='stale'?'⏸':item.type==='habit'?'↻':'⚡'}</i><span><b>${safe(item.goal.title)}</b><small>${safe(item.text)}</small></span><div>${item.type==='next'?`<button data-v85-action="goal-auto-next" data-id="${safe(item.goal.id)}">Создать шаг</button>`:item.type==='task'?`<button data-v85-action="goal-auto-task" data-id="${safe(item.goal.id)}">В задачу</button>`:item.type==='habit'?`<button data-v865-action="manage-goal-habits" data-id="${safe(item.goal.id)}">Связать</button>`:`<button data-v78-route="goal-${encodeURIComponent(item.goal.id)}">Открыть</button>`}</div></article>`).join('')}</div>`;}
  function autoGoalNext(id){const goal=array('goals').find(g=>g.id===id);if(!goal)return;const stage=(goal.stages||[]).find(s=>!s.done);goal.nextAction=stage?`Открыть этап «${stage.title}» и выполнить первое конкретное действие за 15 минут`:`Открыть цель «${goal.title}» и записать одно физическое действие на 15 минут`;goal.actionMinutes=15;goal.lastActivityAt=nowIso();goal.updatedAt=nowIso();save();renderPremium();toast('Следующий шаг создан. Его можно изменить.');}
  function autoGoalTask(id){createGoalTask(id);}
  const ACHIEVEMENT_DEFS=[
    {id:'first-capture',icon:'✍️',title:'Первый след',text:'Сохранить первую быструю запись',hp:3,test:()=>state.gameLife.captures.length>=1},
    {id:'checkin-7',icon:'☀️',title:'Семь честных утр',text:'Заполнить 7 check-in',hp:8,test:()=>state.gameLife.checkIns.length>=7},
    {id:'quotes-10',icon:'“',title:'Коллекционер мыслей',text:'Сохранить 10 цитат',hp:10,test:()=>array('books').reduce((sum,b)=>sum+bookQuoteEntries(b).length,0)>=10},
    {id:'categorized-100',icon:'₽',title:'Финансовый картограф',text:'Категоризировать 100 операций',hp:15,test:()=>array('operations').filter(o=>clean(o.category)&&!['другое','без категории'].includes(clean(o.category).toLowerCase())).length>=100},
    {id:'goal-stage',icon:'🎯',title:'Первая контрольная точка',text:'Завершить этап цели',hp:8,test:()=>state.gameLife.logs.some(l=>String(l.source||'').startsWith('goal-stage:'))},
    {id:'weekly-review',icon:'📊',title:'Архитектор недели',text:'Провести недельный разбор',hp:10,test:()=>state.gameLife.weeklyReviews.length>=1},
    {id:'book-finished',icon:'📚',title:'Закрытая глава',text:'Прочитать первую книгу',hp:12,test:()=>array('books').some(b=>bookStatusMeta(b.status).key==='finished')},
    {id:'first-reward',icon:'🎁',title:'Осознанная награда',text:'Получить первую награду за HP',hp:5,test:()=>state.gameLife.logs.some(l=>String(l.source||'').startsWith('reward:'))},
    {id:'evening-7',icon:'🌙',title:'Семь завершённых дней',text:'Сохранить 7 вечерних итогов',hp:10,test:()=>state.gameLife.eveningReviews.length>=7},
    {id:'book-sessions-10',icon:'⏱',title:'Ритм читателя',text:'Провести 10 сессий чтения',hp:10,test:()=>array('bookSessions').length>=10},
    {id:'goal-finished',icon:'🏆',title:'Кампания завершена',text:'Завершить первую цель',hp:20,test:()=>array('goals').some(g=>g.status==='done')},
    {id:'queue-clear',icon:'◇',title:'Чистый входящий поток',text:'Полностью разобрать автоматическую очередь',hp:8,test:()=>state.gameLife.captures.length>0&&reviewQueueCount()===0}
  ];
  function syncAchievements(){let changed=false;const unlocked=new Set(state.gameLife.achievements.map(a=>a.id));ACHIEVEMENT_DEFS.forEach(def=>{if(!unlocked.has(def.id)&&def.test()){state.gameLife.achievements.unshift({id:def.id,title:def.title,icon:def.icon,text:def.text,hp:def.hp,date:todayKey(),createdAt:nowIso()});state.gameLife.coins+=def.hp;state.gameLife.logs.unshift({id:makeId(),source:`achievement:${def.id}`,date:todayKey(),xp:0,coins:def.hp,skill:'achievement',title:`Достижение: ${def.title}`,createdAt:nowIso()});changed=true;}});return changed;}
  function achievementCards(){const unlocked=new Map(state.gameLife.achievements.map(a=>[a.id,a]));return ACHIEVEMENT_DEFS.map(def=>{const item=unlocked.get(def.id);return `<article class="${item?'unlocked':'locked'}"><i>${def.icon}</i><span><b>${safe(def.title)}</b><small>${safe(def.text)}</small></span><em>${item?`+${def.hp} HP`:'🔒'}</em></article>`;}).join('');}
  function openBookSession(id){const book=array('books').find(b=>b.id===id);if(!book)return;openModal(`Сессия чтения · ${book.title}`,`<div class="v79-form-grid"><label class="v79-field"><span>Минут прочитано</span><input id="v85_book_minutes" type="number" min="1" value="20"></label><label class="v79-field"><span>Страниц прочитано</span><input id="v85_book_pages" type="number" min="0" value="0"></label><label class="v79-field span-2"><span>Одна мысль после чтения</span><textarea id="v85_book_thought" placeholder="Что хочется сохранить?"></textarea></label></div><div class="v79-modal-actions"><button class="v78-primary" data-v85-action="save-book-session" data-id="${safe(id)}">Сохранить сессию</button><button data-v78-action="close-modal">Отмена</button></div>`);}
  function saveBookSession(id,originEl=null){const book=array('books').find(b=>b.id===id);if(!book)return;const minutes=Math.max(1,number(document.getElementById('v85_book_minutes')?.value)||20),pages=Math.max(0,number(document.getElementById('v85_book_pages')?.value)),thought=clean(document.getElementById('v85_book_thought')?.value);const before=bookProgress(book);book.currentPage=Math.max(0,number(book.currentPage))+pages;if(book.pagesTotal&&book.currentPage>=book.pagesTotal){book.currentPage=book.pagesTotal;book.status='finished';book.finishDate=book.finishDate||todayKey();}else if(bookStatusMeta(book.status).key==='planned')book.status='reading';book.startDate=book.startDate||todayKey();book.updatedAt=nowIso();state.bookSessions.unshift({id:makeId(),bookId:id,date:todayKey(),minutes,pages,thought,createdAt:nowIso()});if(thought)book.summary=[book.summary,thought].filter(Boolean).join('\n');awardGame(`book-session:${id}:${makeId()}`,5,2,'knowledge',{title:`Чтение: ${book.title}`});if(bookProgress(book)===100&&before<100)awardGame(`book-finished:${id}`,20,8,'knowledge',{title:`Книга прочитана: ${book.title}`});syncAchievements();save();closeModal();renderPremium();toast('Сессия чтения сохранена');celebrate(originEl,'📚');}
  let autoPromptTimer=0;
  function maybePromptRoutines(){clearTimeout(autoPromptTimer);return false;}

  const GAME_LEVELS=[
    {level:1,name:'Возвращение контроля',xp:0,next:80},{level:2,name:'Финансовая осознанность',xp:80,next:180},{level:3,name:'Управление днём',xp:180,next:320},{level:4,name:'Стабильный ритм',xp:320,next:500},{level:5,name:'Система дисциплины',xp:500,next:800}
  ];
  function gameLevelData(){const xp=number(state.gameLife?.xp);let row=GAME_LEVELS[0];GAME_LEVELS.forEach(item=>{if(xp>=item.xp)row=item;});const max=row.next||row.xp+300;return {...row,progress:Math.max(0,Math.min(100,Math.round((xp-row.xp)/(max-row.xp)*100))),remaining:Math.max(0,max-xp)};}
  function gameTodayXp(){return state.gameLife.logs.filter(log=>String(log.date||'').slice(0,10)===todayKey()).reduce((sum,log)=>sum+number(log.xp),0);}
  function awardGame(source,xp=0,coins=0,skill='discipline',meta={}){ensureData();if(state.gameLife.logs.some(log=>log.source===source))return false;const cap=number(state.settings.v83.dailyXpCap)||40;const allowed=Math.max(0,Math.min(number(xp),cap-gameTodayXp()));if(allowed<=0&&coins<=0)return false;state.gameLife.xp+=allowed;state.gameLife.coins+=Math.max(0,number(coins));state.gameLife.skillXp[skill]=number(state.gameLife.skillXp[skill])+allowed;state.gameLife.logs.unshift({id:makeId(),source,date:todayKey(),xp:allowed,coins:Math.max(0,number(coins)),skill,title:meta.title||'Действие',createdAt:nowIso()});state.gameLife.logs=state.gameLife.logs.slice(0,1000);save();return true;}
  function gameQuestData(){
    const quests=[];
    const checkin=dailyCheckInToday();
    quests.push({id:'daily-checkin',icon:'☀️',title:'Утренний check-in — 30 секунд',text:checkin?`Главное сегодня: ${checkin.focus||'сохранено'}`:'Состояние, главное действие и то, что нельзя забыть.',xp:3,coins:1,action:'daily-checkin',done:Boolean(checkin)});
    const undone=habitsActive().filter(h=>!completedHabit(h));
    if(undone[0])quests.push({id:`habit-${undone[0].id}`,icon:undone[0].icon||'✓',title:`Главный квест: ${undone[0].name}`,text:`Полная версия: ${undone[0].target} ${undone[0].unit}. Минимальная — начать на 5 минут.`,xp:10,coins:2,route:`habit-${encodeURIComponent(undone[0].id)}`,done:false});
    else quests.push({id:'habits-done',icon:'🏆',title:'Привычки на сегодня закрыты',text:'Ты сохранил ритм. Не нужно добавлять новые обязательства.',xp:0,coins:0,route:'habits',done:true});
    const financeDone=Boolean(state.discipline.financeChecks?.[todayKey()]);
    quests.push({id:'finance-check',icon:'💳',title:'Финансовая сверка — 2 минуты',text:'Посмотреть баланс, обязательства и последние операции.',xp:5,coins:1,action:'finance-check',done:financeDone});
    const captured=state.gameLife.captures.some(c=>String(c.date||'').slice(0,10)===todayKey());
    quests.push({id:'capture',icon:'✍️',title:'Зафиксировать одну мысль',text:'Любая мысль, эмоция, задача или наблюдение за 30 секунд.',xp:3,coins:1,action:'quick-capture',done:captured});
    const goal=array('goals').find(g=>g.status==='active'&&g.nextAction);
    if(goal)quests.push({id:`goal-${goal.id}`,icon:'🎯',title:`Кампания: ${goal.title}`,text:goal.nextAction,xp:8,coins:2,route:`goal-${encodeURIComponent(goal.id)}`,done:false});
    if(new Date().getHours()>=number(state.settings.v85.eveningPromptHour||19)){
      const evening=eveningReviewToday();quests.push({id:'evening-review',icon:'🌙',title:'Завершить день',text:evening?'Итог дня сохранён':'Автоматический итог и один вопрос о том, что сработало.',xp:5,coins:2,action:'evening-review',done:Boolean(evening)});
    }
    return quests;
  }

  function gameLifeTodayStrip(){
    const lv=gameLevelData(),quests=gameQuestData(),done=quests.filter(q=>q.done).length,queue=reviewQueueCount(),p=profile();
    return `<section class="v83-today-game v103-profile-strip"><div class="v83-player-mini"><div class="v103-home-avatar" title="${safe(p.name||'Алексей')}">${avatarHtml('md')}</div><div><small>GAMELIFE · ${safe(lv.name)}</small><h2>${safe(p.name||'Алексей')}, сегодня ${done}/${quests.length} квестов</h2><div class="v83-xp-line"><i style="width:${lv.progress}%"></i></div></div><div class="v83-mini-money"><b>${number(state.gameLife.xp)} XP</b><span>${number(state.gameLife.coins)} HP</span></div></div><div class="v83-strip-actions"><button data-v83-action="quick-capture" type="button">＋ Зафиксировать</button>${queue?`<button data-v78-route="review-queue" type="button">Разобрать ${queue}</button>`:''}<button data-v78-route="gamelife" type="button">Открыть GameLife →</button></div></section>`;
  }
  function hpJournal(limit=120){return (Array.isArray(state.gameLife?.logs)?state.gameLife.logs:[]).filter(Boolean).slice().sort((a,b)=>String(b.createdAt||b.date||'').localeCompare(String(a.createdAt||a.date||''))).slice(0,Math.max(1,number(limit)||120));}
  function skillCard(key,icon,title){const value=number(state.gameLife?.skillXp?.[key]),level=Math.max(1,Math.floor(value/60)+1),progress=Math.max(0,Math.min(100,(value%60)/60*100));return `<article><i>${safe(icon)}</i><span><small>${safe(title)}</small><b>Уровень ${level}</b><u><em style="width:${progress}%"></em></u></span><strong>${value} XP</strong></article>`;}
  function rewardCooldownRemaining(reward={}){const days=number(reward.cooldownDays);if(!days||!reward.lastRedeemedAt)return 0;const redeemed=new Date(reward.lastRedeemedAt);if(Number.isNaN(redeemed.getTime()))return 0;return Math.max(0,Math.ceil((redeemed.getTime()+days*86400000-Date.now())/86400000));}
  function rewardVisual(reward={}){const image=String(reward.imageUrl||'').trim(),fallback=safe(reward.icon||'✦');if(!/^https?:\/\//i.test(image)&&!/^data:image\//i.test(image))return `<i>${fallback}</i>`;return `<span class="v85-reward-image"><img src="${safe(image)}" alt="${safe(reward.title||'Награда')}" loading="lazy" onerror="this.parentElement.textContent='${fallback}'"></span>`;}
  function rewardAvailability(reward={}){const game=state.gameLife||{},level=number(gameLevelData()?.level||game.level||1),cooldown=rewardCooldownRemaining(reward);if(reward.archived||reward.active===false)return {ok:false,text:'Неактивна'};if(number(reward.minLevel)>level)return {ok:false,text:`Нужен LV ${number(reward.minLevel)}`};if(reward.limit&&number(reward.redeemedCount)>=number(reward.limit))return {ok:false,text:'Лимит исчерпан'};if(cooldown)return {ok:false,text:`Через ${cooldown} дн.`};if(number(game.coins)<number(reward.cost))return {ok:false,text:'Не хватает HP'};return {ok:true,text:'Получить'};}
  function gameLifePage(){const lv=gameLevelData(),quests=gameQuestData(),logs=hpJournal(),achievements=achievementCards(),queue=reviewQueueCount(),automation=goalAutomationItems();return `<section class="v78-page v83-game-page v85-game-page"><header class="v78-page-head"><div><span>Life simulator без обнуления прогресса</span><h1>GameLife</h1><p>XP показывает развитие, HP тратится на реальные награды, а ежедневные и недельные ритуалы удерживают систему в движении.</p></div><div>${queue?`<button class="v78-secondary" data-v78-route="review-queue" type="button">◇ Разобрать ${queue}</button>`:''}<button class="v78-primary" data-v83-action="quick-capture" type="button">＋ Зафиксировать за 30 секунд</button></div></header><section class="v83-player-hero"><div class="v83-avatar-core">${avatarHtml('xl')}<span>LV ${lv.level}</span></div><div><small>ТЕКУЩИЙ УРОВЕНЬ</small><h2>${safe(lv.name)}</h2><p>До следующего уровня осталось ${lv.remaining} XP. HP можно обменивать только на выбранные тобой награды.</p><div class="v83-level-progress"><i style="width:${lv.progress}%"></i></div><footer><b>${number(state.gameLife.xp)} XP</b><span>${number(state.gameLife.coins)} HP</span><em>Сегодня +${gameTodayXp()} XP</em></footer></div><div class="v83-map-orb"><i></i><b>✦</b></div></section><section class="v85-routine-grid">${dailyRoutineCards()}</section><section class="v83-game-grid"><div class="v83-game-main">${card('Квесты дня','Один главный и несколько коротких дополнительных.',`<div class="v83-quests">${quests.map(q=>`<article class="${q.done?'done':''}"><i>${q.icon}</i><span><b>${safe(q.title)}</b><small>${safe(q.text)}</small><em>+${q.xp} XP · +${q.coins} HP</em></span>${q.done?'<strong>✓</strong>':q.action?`<button data-v85-action="${q.action}">${q.action==='quick-capture'?'Записать':'Выполнить'}</button>`:`<button data-v78-route="${q.route}">Открыть</button>`}</article>`).join('')}</div>`,'v83-quest-card')}${card('Характеристики персонажа','Дисциплина, финансы, знания, энергия и осознанность.',`<div class="v83-skills">${skillCard('discipline','🛡️','Дисциплина')}${skillCard('finance','💰','Финансы')}${skillCard('knowledge','📚','Знания')}${skillCard('energy','⚡','Энергия')}${skillCard('awareness','🧠','Осознанность')}</div>`,'v83-skills-card')}${automation.length?card('Автоматизация целей',`${automation.length} ${plural(automation.length,'подсказка','подсказки','подсказок')}`,goalAutomationHtml(automation),'v85-goal-automation-card'):''}</div><aside class="v83-game-side">${card('Магазин наград',`${number(state.gameLife.coins)} HP`, `<div class="v83-rewards v85-rewards">${state.gameLife.rewards.filter(r=>!r.archived).map(r=>{const a=rewardAvailability(r);return `<article>${rewardVisual(r)}<span><b>${safe(r.title)}</b><small>${number(r.cost)} HP · ${safe(r.category||'Другое')}</small>${r.description?`<em>${safe(r.description)}</em>`:''}</span><div class="v85-reward-actions"><button data-v83-action="redeem-reward" data-id="${safe(r.id)}" ${a.ok?'':'disabled'}>${safe(a.text)}</button><button class="ghost" data-v85-action="edit-reward" data-id="${safe(r.id)}">✎</button><button class="ghost danger" data-v85-action="delete-reward" data-id="${safe(r.id)}">×</button></div></article>`}).join('')||'<p class="v78-empty">Добавьте первую награду.</p>'}</div><button class="v78-link-button" data-v83-action="add-reward">＋ Своя награда</button>`,'v83-reward-card')}${card('Достижения',`${state.gameLife.achievements.length} открыто`, `<div class="v85-achievements">${achievements}</div>`,'v85-achievements-card')}${card('Журнал HP','Каждое начисление и списание объяснено.',`<div class="v83-game-log">${logs.map(log=>`<div><i>${number(log.coins)<0?'−':'+'}</i><span><b>${safe(log.title)}</b><small>${formatShort(log.date)} · ${number(log.xp)?`${number(log.xp)>0?'+':''}${number(log.xp)} XP · `:''}${number(log.coins)>0?'+':''}${number(log.coins)} HP</small></span><em>${safe(log.skill||'game')}</em></div>`).join('')||'<p class="v78-empty">История HP появится после первого действия.</p>'}</div>`,'v83-log-card')}</aside></section></section>`;}
  function v108CaptureGlyph(type){
    const paths={
      thought:'<path d="M6 5h12v10H9l-3 3z"/><path d="M9 9h6M9 12h4"/>',
      emotion:'<path d="M12 20S5 16 5 10a4 4 0 0 1 7-2.7A4 4 0 0 1 19 10c0 6-7 10-7 10z"/>',
      task:'<rect x="5" y="4" width="14" height="16" rx="3"/><path d="m8 12 2.3 2.3L16 8.7"/>',
      idea:'<path d="M9 18h6M10 21h4"/><path d="M8.5 14.5A6 6 0 1 1 15.5 14.5c-1 .8-1.5 1.8-1.5 3.5h-4c0-1.7-.5-2.7-1.5-3.5z"/>',
      expense:'<circle cx="12" cy="12" r="9"/><path d="M9 8h4a2 2 0 0 1 0 4H9m0 0h5a2 2 0 0 1 0 4H9M11 6v12"/>',
      event:'<rect x="4" y="6" width="16" height="14" rx="3"/><path d="M8 3v6M16 3v6M4 10h16"/>'
    };
    return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[type]||paths.thought}</svg>`;
  }
  function updateGameCaptureFields(){
    const type=document.querySelector('input[name="v83_capture_type"]:checked')?.value||'thought';
    document.querySelectorAll('[data-v108-capture-field]').forEach(field=>{field.hidden=!String(field.dataset.v108CaptureField||'').split(' ').includes(type);});
    const copy=document.querySelector('[data-v108-capture-copy]');
    if(copy)copy.textContent=({thought:'Мысль попадёт во входящие и дождётся решения.',emotion:'Запись сохранит состояние без оценки.',task:'Добавьте один ближайший шаг — его можно будет открыть из задач.',idea:'Идея сохранится без обязательства сразу её выполнять.',expense:'Сумма и описание попадут в финансовые операции.',event:'Событие попадёт во входящие, где можно уточнить дату.'})[type]||'';
  }
  function openGameCapture(){
    const types=[['thought','violet','Мысль'],['emotion','coral','Эмоция'],['task','mint','Задача'],['idea','amber','Идея'],['expense','cyan','Расход'],['event','blue','Событие']];
    openModal('Быстрая фиксация',`<div class="v83-capture v108-clear-form"><header class="v108-form-intro"><b>Что важно не потерять?</b><span>Сначала одна строка. Остальные поля появятся только по смыслу.</span></header><label class="v79-field v108-capture-main"><span>Запись</span><textarea id="v83_capture_text" placeholder="Например: оплатить интернет до пятницы…"></textarea></label><div class="v83-capture-types">${types.map(([value,tone,label],index)=>`<label data-tone="${tone}"><input type="radio" name="v83_capture_type" value="${value}" ${index===0?'checked':''}><span><i>${v108CaptureGlyph(value)}</i>${label}</span></label>`).join('')}</div><p class="v108-capture-help" data-v108-capture-copy></p><div class="v79-form-grid"><label class="v79-field" data-v108-capture-field="expense" hidden><span>Сумма</span><input id="v83_capture_amount" type="number" min="0" step="0.01" inputmode="decimal" placeholder="0 ₽"></label><label class="v79-field" data-v108-capture-field="task event" hidden><span>Следующий шаг</span><input id="v83_capture_next" placeholder="Что именно сделать?"></label></div></div><div class="v79-modal-actions v108-sticky-actions"><button class="v78-primary" data-v83-action="save-capture">Сохранить</button><button data-v78-action="close-modal">Отмена</button></div>`);
    updateGameCaptureFields();
    setTimeout(()=>document.getElementById('v83_capture_text')?.focus(),40);
  }
  window.addEventListener('change',event=>{if(event.target?.name==='v83_capture_type')updateGameCaptureFields();},true);
  function saveGameCapture(originEl=null){const type=document.querySelector('input[name="v83_capture_type"]:checked')?.value||'thought',text=clean(document.getElementById('v83_capture_text')?.value),next=clean(document.getElementById('v83_capture_next')?.value),amount=number(document.getElementById('v83_capture_amount')?.value);if(!text){document.getElementById('v83_capture_text')?.focus();return toast('Напишите, что важно сохранить');}if(type==='expense'&&!amount){document.getElementById('v83_capture_amount')?.focus();return toast('Укажите сумму расхода');}const entry={id:makeId(),date:todayKey(),type,text,next,amount,createdAt:nowIso()};state.gameLife.captures.unshift(entry);if(type==='task')state.tasks.unshift({id:makeId(),title:text,date:todayKey(),status:'planned',priority:'medium',note:next,createdAt:nowIso()});else if(type==='idea')state.ideas.unshift({id:makeId(),title:text.slice(0,70),date:todayKey(),text:[text,next].filter(Boolean).join('\n'),createdAt:nowIso()});else if(type==='expense')state.operations.unshift({id:makeId(),date:todayKey(),type:'expense',amount:Math.abs(amount),category:'Быстрая запись',note:text,createdAt:nowIso()});else state.inbox.unshift({id:makeId(),title:type==='emotion'?'Эмоция':type==='event'?'Событие':'Быстрая запись',date:todayKey(),text:[text,next].filter(Boolean).join('\n'),captureType:type,createdAt:nowIso()});awardGame(`capture:${entry.id}`,3,1,type==='expense'?'finance':type==='thought'||type==='emotion'?'awareness':'discipline',{title:'Быстрая фиксация'});syncAchievements();save();closeModal();renderPremium();toast(type==='expense'?`Расход ${moneyText(Math.abs(amount))} сохранён`:type==='task'?'Задача добавлена на сегодня':'Запись сохранена');celebrate(originEl,'✦');}
  function openRewardForm(id=''){const reward=state.gameLife.rewards.find(r=>r.id===id)||{};openModal(id?'Редактировать награду':'Своя награда',`<div class="v79-form-grid"><label class="v79-field"><span>Эмодзи / короткая иконка</span><input id="v83_reward_icon" value="${safe(reward.icon||'🎁')}"></label><label class="v79-field"><span>URL картинки</span><input id="v85_reward_image" type="url" value="${safe(reward.imageUrl||'')}" placeholder="https://..."></label><label class="v79-field span-2"><span>Название награды</span><input id="v83_reward_title" value="${safe(reward.title||'')}" placeholder="Например: вечер без дел"></label><label class="v79-field"><span>Стоимость в HP</span><input id="v83_reward_cost" type="number" min="1" value="${number(reward.cost)||50}"></label><label class="v79-field"><span>Категория</span><input id="v85_reward_category" value="${safe(reward.category||'Отдых')}" placeholder="Отдых, еда, покупка"></label><label class="v79-field"><span>Минимальный уровень</span><input id="v85_reward_level" type="number" min="1" value="${number(reward.minLevel)||1}"></label><label class="v79-field"><span>Лимит получений, 0 — без лимита</span><input id="v85_reward_limit" type="number" min="0" value="${number(reward.limit)}"></label><label class="v79-field"><span>Пауза между получениями, дней</span><input id="v85_reward_cooldown" type="number" min="0" value="${number(reward.cooldownDays)}"></label><label class="v79-field"><span>Статус</span><select id="v85_reward_active"><option value="1" ${reward.active!==false?'selected':''}>Активна</option><option value="0" ${reward.active===false?'selected':''}>Выключена</option></select></label><label class="v79-field span-2"><span>Описание</span><textarea id="v85_reward_description" placeholder="Когда и как использовать награду">${safe(reward.description||'')}</textarea></label></div><div class="v79-modal-actions"><button class="v78-primary" data-v83-action="save-reward" data-id="${safe(id)}">Сохранить</button><button data-v78-action="close-modal">Отмена</button></div>`);}
  function saveReward(id=''){const title=clean(document.getElementById('v83_reward_title')?.value),cost=Math.max(1,number(document.getElementById('v83_reward_cost')?.value)),icon=clean(document.getElementById('v83_reward_icon')?.value)||'🎁';if(!title)return toast('Укажите награду');const old=state.gameLife.rewards.find(r=>r.id===id);const reward={...old,id:id||makeId(),title,cost,icon,imageUrl:clean(document.getElementById('v85_reward_image')?.value),description:clean(document.getElementById('v85_reward_description')?.value),category:clean(document.getElementById('v85_reward_category')?.value)||'Другое',minLevel:Math.max(1,number(document.getElementById('v85_reward_level')?.value)||1),limit:Math.max(0,number(document.getElementById('v85_reward_limit')?.value)),cooldownDays:Math.max(0,number(document.getElementById('v85_reward_cooldown')?.value)),active:String(document.getElementById('v85_reward_active')?.value)!=='0',redeemedCount:number(old?.redeemedCount),lastRedeemedAt:old?.lastRedeemedAt||'',createdAt:old?.createdAt||nowIso(),updatedAt:nowIso()};state.gameLife.rewards=old?state.gameLife.rewards.map(r=>r.id===id?reward:r):[reward,...state.gameLife.rewards];save();closeModal();renderPremium();toast('Награда сохранена');}
  function deleteReward(id){const reward=state.gameLife.rewards.find(r=>r.id===id);if(!reward)return;if(!confirm(`Удалить награду «${reward.title}»? История получений останется в журнале HP.`))return;archiveSnapshot(`Удалённая награда: ${reward.title}`,'deleted-reward',reward);state.gameLife.rewards=state.gameLife.rewards.filter(r=>r.id!==id);save();renderPremium();toast('Награда удалена, копия сохранена в архиве');}
  function redeemReward(id,originEl=null){const reward=state.gameLife.rewards.find(r=>r.id===id);if(!reward)return;const availability=rewardAvailability(reward);if(!availability.ok)return toast(availability.text);if(!confirm(`Обменять ${reward.cost} HP на «${reward.title}»?`))return;state.gameLife.coins-=number(reward.cost);reward.redeemedCount=number(reward.redeemedCount)+1;reward.lastRedeemedAt=nowIso();reward.updatedAt=nowIso();state.gameLife.logs.unshift({id:makeId(),source:`reward:${makeId()}`,date:todayKey(),xp:0,coins:-number(reward.cost),skill:'reward',title:`Награда: ${reward.title}`,createdAt:nowIso()});syncAchievements();save();renderPremium();toast('Награда получена — используй её без чувства вины');celebrate(originEl,'🎁');}

  function goalProgress(goal){
    if(!goal||typeof goal!=='object')return 0;
    if(clean(goal.status).toLowerCase()==='done')return 100;
    const target=Math.max(0,number(goal.target)),current=Math.max(0,number(goal.current));
    if(target>0)return Math.max(0,Math.min(100,Math.round(current/target*100)));
    const stages=(Array.isArray(goal.stages)?goal.stages:[]).filter(Boolean);
    if(stages.length)return Math.max(0,Math.min(100,Math.round(stages.filter(stage=>Boolean(stage?.done)).length/stages.length*100)));
    return 0;
  }

  function goalExecutionMode(goal){const mode=clean(goal?.executionMode);return ['actions','habits','hybrid'].includes(mode)?mode:'actions';}
  function goalExecutionLabel(mode){return mode==='habits'?'Через привычки':mode==='hybrid'?'Шаги + привычки':'Через действия';}
  function goalExecutionDescription(mode){return mode==='habits'?'Прогресс строится на регулярности связанных привычек.':mode==='hybrid'?'Этапы и задачи дают основной прогресс, привычки поддерживают ритм.':'Цель движется этапами, метрикой и конкретными задачами — привычки не обязательны.';}
  function goalHabitIds(goal){return [...new Set((Array.isArray(goal?.habitIds)?goal.habitIds:[]).map(String).filter(Boolean))];}
  function linkedHabitsForGoal(goal){const ids=new Set(goalHabitIds(goal));return array('habits').filter(h=>ids.has(String(h.id))&&h.active!==false);}
  function linkedGoalsForHabit(habit){return array('goals').filter(g=>g&&g.status!=='archived'&&g.status!=='done'&&goalHabitIds(g).includes(String(habit.id)));}
  function habitWeeklyTarget(habit){const f=clean(habit?.frequency).toLowerCase();if(/ежеднев|каждый день/.test(f))return 7;if(/еженед|раз в неделю/.test(f))return 1;const match=f.match(/(\d+)\s*(раз|дн)/);if(match)return Math.max(1,Math.min(7,number(match[1])));return Math.max(1,Math.min(7,number(habit?.weeklyTarget)||7));}
  function habitStability(habit){const actual=recentDates(7).filter(date=>completedHabit(habit,date)).length,target=habitWeeklyTarget(habit);return Math.max(0,Math.min(100,Math.round(actual/target*100)));}
  function goalHabitStability(goal){const habits=linkedHabitsForGoal(goal);if(!habits.length)return 0;return Math.round(habits.reduce((sum,h)=>sum+habitStability(h),0)/habits.length);}
  function goalDisplayProgress(goal){const raw=goalProgress(goal),mode=goalExecutionMode(goal),stability=goalHabitStability(goal);if(clean(goal?.status)==='done')return 100;if(mode==='habits')return stability;if(mode==='hybrid'&&linkedHabitsForGoal(goal).length)return Math.round(raw*.7+stability*.3);return raw;}
  function goalProgressCaption(goal){const mode=goalExecutionMode(goal);return mode==='habits'?'стабильность привычек':mode==='hybrid'?'смешанный прогресс':'прогресс кампании';}
  function goalHabitSelector(selectedIds=[]){const selected=new Set((selectedIds||[]).map(String)),habits=habitsActive();return habits.length?`<div class="v865-habit-select-list">${habits.map(h=>`<label><input type="checkbox" name="v865_goal_habit" value="${safe(h.id)}" ${selected.has(String(h.id))?'checked':''}><span><i>${safe(h.icon||'✦')}</i><span><b>${safe(h.name)}</b><small>${safe(h.frequency||'Регулярно')} · ${habitStability(h)}% за неделю</small></span><em></em></span></label>`).join('')}</div>`:'<div class="v865-empty-links">Активных привычек пока нет. Сначала сохраните цель, затем создайте привычку и свяжите её через редактирование.</div>';}

  function goalsPage(){const valid=array('goals').filter(g=>g&&typeof g==='object'),active=valid.filter(g=>g.status!=='archived'&&g.status!=='done'),done=valid.filter(g=>g.status==='done'),automation=goalAutomationItems();return `<section class="v78-page v83-goals-page"><header class="v78-page-head"><div><span>Цели с понятным результатом</span><h1>Цели</h1><p>Результат, срок и один конкретный шаг — остальное можно уточнить позже.</p></div><button class="v78-primary" data-v83-action="goal-wizard">＋ Создать цель</button></header>${automation.length?card('Цели, которым нужна помощь',`${automation.length} автоматических подсказок`,goalAutomationHtml(automation),'v85-goal-automation-card'):''}<section class="v83-goal-principles"><article><i>1</i><span><b>Какой нужен результат</b><small>Одна проверяемая формулировка.</small></span></article><article><i>2</i><span><b>Когда это должно произойти</b><small>Дата или честное «без жёсткого срока».</small></span></article><article><i>3</i><span><b>Что сделать сейчас</b><small>Физическое действие на 5–20 минут.</small></span></article></section><section class="v83-goal-grid">${active.map(goalCard).join('')||'<div class="v78-empty-big">Активных целей пока нет. Достаточно результата и первого шага.</div>'}</section>${done.length?card('Завершённые цели',`${done.length} целей`, `<div class="v83-finished-goals">${done.map(g=>`<article><button data-v78-route="goal-${encodeURIComponent(g.id)}" type="button"><i>✓</i><span><b>${safe(g.title)}</b><small>${safe(formatDate(g.due))}</small></span><em>100%</em></button><button class="v833-goal-delete" data-v83-action="delete-goal" data-id="${safe(g.id)}" type="button">Удалить</button></article>`).join('')}</div>`,'v83-finished-card'):''}</section>`;}
  function goalTypeLabel(type){
    const key=clean(type||'result').toLowerCase();
    if(key==='process')return 'Цель-процесс';
    if(key==='maintenance')return 'Цель-поддержание';
    return 'Цель-результат';
  }

  function goalCard(goal){const progress=goalDisplayProgress(goal),next=goal.nextAction||'Определите следующий физический шаг',mode=goalExecutionMode(goal),habits=linkedHabitsForGoal(goal),stability=goalHabitStability(goal);return `<article class="v83-goal-card"><header><span>${goal.type==='process'?'🔁':goal.type==='maintenance'?'🛡️':'🎯'}</span><div><small>${goalTypeLabel(goal.type)}</small><h2>${safe(goal.title)}</h2></div><em>${progress}%</em></header><div class="v83-goal-progress"><i style="width:${progress}%"></i></div><div class="v865-goal-card-meta"><b class="v865-mode-badge ${mode}">${goalExecutionLabel(mode)}</b>${habits.length?`<span>${habits.length} ${plural(habits.length,'привычка','привычки','привычек')} · ${stability}% стабильности</span>`:'<span>Без привязанных привычек</span>'}</div><p>${safe(goal.why||'Причина пока не указана.')}</p><div class="v83-next-action"><small>СЛЕДУЮЩИЙ ШАГ · ${number(goal.actionMinutes)||15} МИН</small><b>${safe(next)}</b></div><footer><span>${goal.due?`до ${formatShort(goal.due)}`:'без жёсткого срока'} · ${goalProgressCaption(goal)}</span><div class="v833-goal-card-actions"><button class="v833-goal-delete" data-v83-action="delete-goal" data-id="${safe(goal.id)}" type="button" title="Удалить цель">Удалить</button><button data-v78-route="goal-${encodeURIComponent(goal.id)}" type="button">Открыть кампанию →</button></div></footer></article>`;}
  function goalPage(id){const goal=array('goals').find(g=>g.id===id);if(!goal)return `<section class="v78-page"><div class="v78-empty-big">Цель не найдена.<button data-v78-route="goals">Вернуться</button></div></section>`;const progress=goalDisplayProgress(goal),rawProgress=goalProgress(goal),linked=array('tasks').filter(t=>t.goalId===goal.id),habits=linkedHabitsForGoal(goal),stability=goalHabitStability(goal),mode=goalExecutionMode(goal);return `<section class="v78-page v83-goal-page"><header class="v78-page-head"><div><button class="v78-back" data-v78-route="goals">← Все цели</button><span>${goalTypeLabel(goal.type)} · ${goalExecutionLabel(mode)}</span><h1>${safe(goal.title)}</h1><p>${safe(goal.why||'Добавьте личную причину — она помогает возвращаться к цели после спада мотивации.')}</p></div><div><button class="v78-secondary" data-v865-action="manage-goal-habits" data-id="${safe(goal.id)}">Связать привычки</button><button class="v78-secondary" data-v83-action="goal-wizard" data-id="${safe(goal.id)}">Редактировать</button><button class="v83-danger-soft" data-v83-action="delete-goal" data-id="${safe(goal.id)}">Удалить</button></div></header><section class="v83-goal-hero"><div class="v83-goal-ring" style="--goal-progress:${progress}"><span><b>${progress}%</b><small>${goalProgressCaption(goal)}</small></span></div><div><small>СИСТЕМА ДОСТИЖЕНИЯ</small><h2>${safe(goalExecutionLabel(mode))}</h2><p>${safe(goalExecutionDescription(mode))}</p><div class="v83-goal-meta"><span>📅 ${goal.due?formatDate(goal.due):'Без срока'}</span><span>⏱ ${number(goal.actionMinutes)||15} минут на шаг</span><span>↻ ${habits.length} ${plural(habits.length,'привычка','привычки','привычек')}</span></div></div><div class="v83-campaign-badge">КАМПАНИЯ</div></section><section class="v865-goal-system-summary"><article><small>Прогресс этапов / метрики</small><b>${rawProgress}%</b><span>не зависит от ежедневной серии</span></article><article><small>Стабильность привычек</small><b>${habits.length?`${stability}%`:'—'}</b><span>${habits.length?'за последние 7 дней':'привычки не связаны'}</span></article><article><small>Итоговый показатель</small><b>${progress}%</b><span>${goalProgressCaption(goal)}</span></article></section><section class="v83-goal-layout"><div>${card('Карта кампании','Этапы не обязаны быть идеальными — их можно менять по ходу.', `<div class="v83-stage-list">${(goal.stages||[]).map((stage,index)=>`<button class="${stage.done?'done':''}" data-v83-action="toggle-goal-stage" data-goal="${safe(goal.id)}" data-stage="${safe(stage.id)}"><i>${stage.done?'✓':index+1}</i><span><b>${safe(stage.title)}</b><small>${stage.done?'Этап завершён':'Нажмите, когда контрольная точка достигнута'}</small></span><em>${stage.done?'Готово':'○'}</em></button>`).join('')||'<p class="v78-empty">Добавьте этапы через редактирование цели.</p>'}</div>`,'v83-stages-card')}${card('Задачи этой цели',`${linked.length} связанных задач`, `<div class="v83-linked-tasks">${linked.map(t=>`<button data-v79-action="edit-record" data-type="task" data-id="${safe(t.id)}"><i>${taskStatusMeta(t.status).done?'✓':'▦'}</i><span><b>${safe(t.title)}</b><small>${safe(formatShort(t.date))} · ${safe(taskStatusMeta(t.status).label)}</small></span><em>›</em></button>`).join('')||'<p class="v78-empty">Пока нет связанных задач.</p>'}</div>`,'v83-linked-card')}${card('Привычки, которые двигают цель',habits.length?`${habits.length} связанных · ${stability}% стабильности`:'Связь необязательна', habits.length?`<div class="v865-linked-habits">${habits.map(h=>`<button class="v865-linked-habit ${completedHabit(h)?'done':''}" data-v78-route="habit-${encodeURIComponent(h.id)}" type="button"><i>${safe(h.icon||'✦')}</i><span><b>${safe(h.name)}</b><small>${safe(h.frequency||'Регулярно')} · цель недели ${habitWeeklyTarget(h)} · сегодня ${completedHabit(h)?'выполнено':'не отмечено'}</small></span><em>${habitStability(h)}%</em></button>`).join('')}</div><button class="v78-link-button" data-v865-action="manage-goal-habits" data-id="${safe(goal.id)}" type="button">Изменить связи →</button>`:`<div class="v865-empty-links"><span>${mode==='actions'?'Для этой цели привычки не обязательны. Добавляйте их только если повторение реально помогает результату.':'Свяжите одну или несколько существующих привычек.'}</span><button class="v78-secondary" data-v865-action="manage-goal-habits" data-id="${safe(goal.id)}" type="button">Выбрать привычки</button></div>`,'v865-goal-habits-card')}</div><aside>${card('Активный следующий шаг',`Действие на ${number(goal.actionMinutes)||15} минут`, `<div class="v83-current-step"><i>⚡</i><h2>${safe(goal.nextAction||'Сформулируйте конкретное физическое действие')}</h2><p>Хороший шаг начинается с глагола: открыть, написать, позвонить, проверить, внести.</p><button class="v78-primary" data-v83-action="goal-task" data-id="${safe(goal.id)}">Создать задачу на сегодня</button><button class="v78-secondary" data-v83-action="goal-next-done" data-id="${safe(goal.id)}">✓ Шаг выполнен</button></div>`,'v83-current-step-card')}${card('Управление кампанией','Цель можно поставить на паузу без удаления данных.', `<div class="v83-goal-controls"><button data-v83-action="goal-status" data-id="${safe(goal.id)}" data-status="${goal.status==='paused'?'active':'paused'}">${goal.status==='paused'?'▶ Возобновить':'Ⅱ Поставить на паузу'}</button><button data-v83-action="goal-status" data-id="${safe(goal.id)}" data-status="done">🏆 Завершить цель</button></div>`,'v83-controls-card')}</aside></section></section>`;}
  function openGoalWizard(id=''){const goal=array('goals').find(g=>g.id===id);goalWizardStep=0;goalWizardDraft=goal?coreClone(goal):{id:'',title:'',type:'result',why:'',metric:'',target:0,current:0,unit:'',due:'',currentPoint:'',stages:[],executionMode:'actions',habitIds:[],nextAction:'',actionMinutes:15,status:'active'};goalWizardDraft.executionMode=goalExecutionMode(goalWizardDraft);goalWizardDraft.habitIds=goalHabitIds(goalWizardDraft);renderGoalWizard();}
  function goalWizardQuestions(){return [
    {title:'Что должно конкретно измениться?',hint:'Не «стать финансово грамотным», а измеримый результат.',html:()=>`<label class="v79-field"><span>Название кампании</span><input id="v83_goal_title" value="${safe(goalWizardDraft.title||'')}" placeholder="Например: Финансовая опора"></label><label class="v79-field"><span>Тип цели</span><select id="v83_goal_type"><option value="result" ${goalWizardDraft.type==='result'?'selected':''}>Цель-результат</option><option value="process" ${goalWizardDraft.type==='process'?'selected':''}>Цель-процесс</option><option value="maintenance" ${goalWizardDraft.type==='maintenance'?'selected':''}>Цель-поддержание</option></select></label>`},
    {title:'Почему это важно именно сейчас?',hint:'Личная причина сильнее абстрактной правильности.',html:()=>`<label class="v79-field"><span>Моя причина</span><textarea id="v83_goal_why" placeholder="Что изменится в моей жизни?">${safe(goalWizardDraft.why||'')}</textarea></label>`},
    {title:'Как понять, что цель достигнута?',hint:'Выберите число или наблюдаемый критерий.',html:()=>`<label class="v79-field"><span>Метрика</span><input id="v83_goal_metric" value="${safe(goalWizardDraft.metric||'')}" placeholder="Например: записано 90% операций"></label><div class="v79-form-grid"><label class="v79-field"><span>Сейчас</span><input id="v83_goal_current" type="number" value="${number(goalWizardDraft.current)}"></label><label class="v79-field"><span>Цель</span><input id="v83_goal_target" type="number" value="${number(goalWizardDraft.target)}"></label><label class="v79-field"><span>Единица</span><input id="v83_goal_unit" value="${safe(goalWizardDraft.unit||'')}" placeholder="₽, дней, %, сделок"></label><label class="v79-field"><span>Срок</span><input id="v83_goal_due" type="date" value="${safe(goalWizardDraft.due||'')}"></label></div>`},
    {title:'Где вы находитесь сейчас?',hint:'Факты без самокритики.',html:()=>`<label class="v79-field"><span>Текущая точка</span><textarea id="v83_goal_current_point" placeholder="Что происходит сейчас?">${safe(goalWizardDraft.currentPoint||'')}</textarea></label>`},
    {title:'Разбейте путь на 3–5 этапов',hint:'Один этап — одна понятная контрольная точка.',html:()=>`<label class="v79-field"><span>Каждый этап с новой строки</span><textarea id="v83_goal_stages" placeholder="1. Увидеть реальную картину\n2. Настроить систему\n3. Прожить первую неделю">${safe((goalWizardDraft.stages||[]).map(s=>s.title||s).join('\n'))}</textarea></label>`},
    {title:'Как эта цель будет двигаться?',hint:'Привычки нужны не каждой цели. Выберите честную механику.',html:()=>`<div class="v865-execution-options"><label><input type="radio" name="v865_execution_mode" value="actions" ${goalExecutionMode(goalWizardDraft)==='actions'?'checked':''}><span><i>⚡</i><b>Только действия</b><small>Проект, покупка, регистрация, разовая задача или результат через этапы.</small></span></label><label><input type="radio" name="v865_execution_mode" value="habits" ${goalExecutionMode(goalWizardDraft)==='habits'?'checked':''}><span><i>↻</i><b>Через привычки</b><small>Цель держится на повторении: чтение, сон, учёт расходов, спорт.</small></span></label><label><input type="radio" name="v865_execution_mode" value="hybrid" ${goalExecutionMode(goalWizardDraft)==='hybrid'?'checked':''}><span><i>✦</i><b>Гибрид</b><small>Есть этапы и задачи, а привычки поддерживают движение между ними.</small></span></label></div><div class="v865-wizard-note">Связь необязательна. Для режима «Только действия» можно не выбирать ни одной привычки.</div>${goalHabitSelector(goalWizardDraft.habitIds||[])}`},
    {title:'Какое действие можно сделать за 5–20 минут?',hint:'Даже цель через привычки должна иметь понятный следующий шаг.',html:()=>`<label class="v79-field"><span>Следующий физический шаг</span><textarea id="v83_goal_next" placeholder="Например: открыть операции за 7 дней и исправить 10 категорий">${safe(goalWizardDraft.nextAction||'')}</textarea></label><label class="v79-field"><span>Сколько минут</span><input id="v83_goal_minutes" type="number" min="5" max="60" value="${number(goalWizardDraft.actionMinutes)||15}"></label>`},
    {title:'Проверьте кампанию',hint:'После сохранения можно изменить механику и связи.',html:()=>{const habits=linkedHabitsForGoal(goalWizardDraft);return `<div class="v83-goal-review"><small>${goalTypeLabel(goalWizardDraft.type)} · ${goalExecutionLabel(goalExecutionMode(goalWizardDraft))}</small><h2>${safe(goalWizardDraft.title||'Цель')}</h2><p>${safe(goalWizardDraft.why||'Причина не указана')}</p><div><b>Следующий шаг</b><span>${safe(goalWizardDraft.nextAction||'Не указан')}</span></div><div><b>Связанные привычки</b><span>${habits.length?habits.map(h=>`${h.icon||'✦'} ${h.name}`).join(', '):'Не используются'}</span></div></div>`;}}
  ];}
  function collectGoalWizard(){const get=id=>document.getElementById(id);if(get('v83_goal_title'))goalWizardDraft.title=clean(get('v83_goal_title').value);if(get('v83_goal_type'))goalWizardDraft.type=clean(get('v83_goal_type').value);if(get('v83_goal_why'))goalWizardDraft.why=clean(get('v83_goal_why').value);if(get('v83_goal_metric'))goalWizardDraft.metric=clean(get('v83_goal_metric').value);if(get('v83_goal_current'))goalWizardDraft.current=number(get('v83_goal_current').value);if(get('v83_goal_target'))goalWizardDraft.target=number(get('v83_goal_target').value);if(get('v83_goal_unit'))goalWizardDraft.unit=clean(get('v83_goal_unit').value);if(get('v83_goal_due'))goalWizardDraft.due=clean(get('v83_goal_due').value);if(get('v83_goal_current_point'))goalWizardDraft.currentPoint=clean(get('v83_goal_current_point').value);if(get('v83_goal_stages')){const old=goalWizardDraft.stages||[];goalWizardDraft.stages=String(get('v83_goal_stages').value||'').split('\n').map(x=>clean(x.replace(/^\d+[.)]\s*/,''))).filter(Boolean).map((title,index)=>({id:old[index]?.id||makeId(),title,done:Boolean(old[index]?.done),order:index}));}const mode=document.querySelector('input[name="v865_execution_mode"]:checked');if(mode)goalWizardDraft.executionMode=clean(mode.value);const habitBoxes=[...document.querySelectorAll('input[name="v865_goal_habit"]')];if(habitBoxes.length)goalWizardDraft.habitIds=habitBoxes.filter(box=>box.checked).map(box=>box.value);if(get('v83_goal_next'))goalWizardDraft.nextAction=clean(get('v83_goal_next').value);if(get('v83_goal_minutes'))goalWizardDraft.actionMinutes=Math.max(5,number(get('v83_goal_minutes').value)||15);}
  function renderGoalWizard(){
    const mode=goalExecutionMode(goalWizardDraft);
    openModal(goalWizardDraft.id?'Редактировать цель':'Новая цель',`<div class="v108-clear-form v108-goal-form"><header class="v108-form-intro"><b>Сначала — результат и один шаг</b><span>Метрики, этапы и связи можно добавить позже.</span></header><label class="v79-field span-2"><span>Какой результат должен быть готов? *</span><input id="v83_goal_title" value="${safe(goalWizardDraft.title||'')}" placeholder="Например: создан резерв на 3 месяца"></label><div class="v79-form-grid"><label class="v79-field"><span>Срок</span><input id="v83_goal_due" type="date" value="${safe(goalWizardDraft.due||'')}"></label><label class="v79-field"><span>Время на первый шаг</span><input id="v83_goal_minutes" type="number" min="5" max="60" value="${number(goalWizardDraft.actionMinutes)||15}"></label></div><label class="v79-field span-2"><span>Что можно сделать прямо сейчас? *</span><textarea id="v83_goal_next" rows="3" placeholder="Начните с глагола: открыть, посчитать, позвонить…">${safe(goalWizardDraft.nextAction||'')}</textarea></label><label class="v79-field span-2"><span>Почему это важно сейчас?</span><textarea id="v83_goal_why" rows="2" placeholder="Одна личная причина">${safe(goalWizardDraft.why||'')}</textarea></label><details class="v108-advanced"><summary><span>Уточнить критерии, этапы и связи</span><small>Необязательно</small></summary><div class="v108-advanced-body"><div class="v79-form-grid"><label class="v79-field"><span>Тип цели</span><select id="v83_goal_type"><option value="result" ${goalWizardDraft.type==='result'?'selected':''}>Результат</option><option value="process" ${goalWizardDraft.type==='process'?'selected':''}>Процесс</option><option value="maintenance" ${goalWizardDraft.type==='maintenance'?'selected':''}>Поддержание</option></select></label><label class="v79-field"><span>Критерий завершения</span><input id="v83_goal_metric" value="${safe(goalWizardDraft.metric||'')}" placeholder="Как понять, что готово?"></label><label class="v79-field"><span>Сейчас</span><input id="v83_goal_current" type="number" value="${number(goalWizardDraft.current)}"></label><label class="v79-field"><span>Целевое значение</span><input id="v83_goal_target" type="number" value="${number(goalWizardDraft.target)}"></label><label class="v79-field"><span>Единица</span><input id="v83_goal_unit" value="${safe(goalWizardDraft.unit||'')}" placeholder="₽, дней, %"></label></div><label class="v79-field"><span>Текущая точка</span><textarea id="v83_goal_current_point" rows="2">${safe(goalWizardDraft.currentPoint||'')}</textarea></label><label class="v79-field"><span>Этапы — по одному на строку</span><textarea id="v83_goal_stages" rows="4">${safe((goalWizardDraft.stages||[]).map(stage=>stage.title||stage).join('\n'))}</textarea></label><div class="v865-execution-options"><label><input type="radio" name="v865_execution_mode" value="actions" ${mode==='actions'?'checked':''}><span><i>→</i><b>Действия</b><small>Разовый или проектный результат.</small></span></label><label><input type="radio" name="v865_execution_mode" value="habits" ${mode==='habits'?'checked':''}><span><i>↻</i><b>Привычки</b><small>Прогресс строится на регулярности.</small></span></label><label><input type="radio" name="v865_execution_mode" value="hybrid" ${mode==='hybrid'?'checked':''}><span><i>✦</i><b>Гибрид</b><small>Этапы плюс поддерживающие привычки.</small></span></label></div>${goalHabitSelector(goalWizardDraft.habitIds||[])}</div></details></div><div class="v79-modal-actions v108-sticky-actions"><button type="button" class="v78-primary" data-v83-action="goal-wizard-save">Сохранить цель</button><button type="button" data-v78-action="close-modal">Отмена</button></div>`);
  }
  function goalWizardNext(originEl=null){try{collectGoalWizard();if(goalWizardStep===0&&!goalWizardDraft.title)return toast('Укажите название цели');if(goalWizardStep===5&&goalExecutionMode(goalWizardDraft)!=='actions'&&!goalHabitIds(goalWizardDraft).length)return toast('Выберите хотя бы одну привычку или режим «Только действия»');if(goalWizardStep===6&&!goalWizardDraft.nextAction)return toast('Нужен конкретный следующий шаг');goalWizardStep=Math.min(goalWizardQuestions().length-1,goalWizardStep+1);renderGoalWizard();}catch(error){console.error('[Goal wizard next]',error);toast('Не удалось открыть следующий шаг. Обновите страницу и повторите.');if(originEl)originEl.disabled=false;}}
  function goalWizardPrev(){try{collectGoalWizard();goalWizardStep=Math.max(0,goalWizardStep-1);renderGoalWizard();}catch(error){console.error('[Goal wizard prev]',error);toast('Не удалось вернуться к предыдущему шагу.');}}
  function saveGoalWizard(originEl=null){collectGoalWizard();if(!goalWizardDraft.title||!goalWizardDraft.nextAction)return toast('Нужны название и следующий шаг');goalWizardDraft.executionMode=goalExecutionMode(goalWizardDraft);goalWizardDraft.habitIds=goalHabitIds(goalWizardDraft);if(goalWizardDraft.executionMode!=='actions'&&!goalWizardDraft.habitIds.length)return toast('Для этого режима выберите хотя бы одну привычку');const old=array('goals').find(g=>g.id===goalWizardDraft.id);const goal={...old,...goalWizardDraft,id:goalWizardDraft.id||makeId(),date:goalWizardDraft.due,status:goalWizardDraft.status||'active',createdAt:old?.createdAt||nowIso(),updatedAt:nowIso(),lastActivityAt:nowIso()};state.goals=old?array('goals').map(g=>g.id===goal.id?goal:g):[goal,...array('goals')];awardGame(`goal-created:${goal.id}`,5,1,'discipline',{title:`Создана цель: ${goal.title}`});save();closeModal();navigate(`goal-${encodeURIComponent(goal.id)}`);celebrate(originEl,'🎯');}
  function openGoalHabitManager(id){const goal=array('goals').find(g=>g.id===id);if(!goal)return toast('Цель не найдена');const mode=goalExecutionMode(goal);openModal('Связь цели и привычек',`<div class="v865-link-manager"><div class="v865-execution-options"><label><input type="radio" name="v865_manage_mode" value="actions" ${mode==='actions'?'checked':''}><span><i>⚡</i><b>Только действия</b><small>Привычки необязательны.</small></span></label><label><input type="radio" name="v865_manage_mode" value="habits" ${mode==='habits'?'checked':''}><span><i>↻</i><b>Через привычки</b><small>Регулярность является главным двигателем.</small></span></label><label><input type="radio" name="v865_manage_mode" value="hybrid" ${mode==='hybrid'?'checked':''}><span><i>✦</i><b>Гибрид</b><small>Задачи плюс поддерживающие привычки.</small></span></label></div><div class="v865-wizard-note">Отметьте только те привычки, которые напрямую помогают цели «${safe(goal.title)}».</div>${goalHabitSelector(goalHabitIds(goal))}</div><div class="v79-modal-actions"><button class="v78-primary" data-v865-action="save-goal-habits" data-id="${safe(goal.id)}" type="button">Сохранить связи</button><button data-v78-action="close-modal" type="button">Отмена</button></div>`);}
  function saveGoalHabitLinks(id,originEl=null){const goal=array('goals').find(g=>g.id===id);if(!goal)return;const mode=clean(document.querySelector('input[name="v865_manage_mode"]:checked')?.value)||'actions';const ids=[...document.querySelectorAll('input[name="v865_goal_habit"]:checked')].map(el=>el.value);if(mode!=='actions'&&!ids.length)return toast('Выберите хотя бы одну привычку или режим «Только действия»');goal.executionMode=mode;goal.habitIds=ids;goal.updatedAt=nowIso();goal.lastActivityAt=nowIso();save();closeModal();renderPremium();toast(ids.length?`Связано привычек: ${ids.length}`:'Цель сохранена без привычек');celebrate(originEl,'✦');}

  function toggleGoalStage(goalId,stageId,originEl=null){const goal=array('goals').find(g=>g.id===goalId),stage=goal?.stages?.find(s=>s.id===stageId);if(!stage)return;stage.done=!stage.done;goal.lastActivityAt=nowIso();goal.updatedAt=nowIso();if(stage.done)awardGame(`goal-stage:${goalId}:${stageId}`,12,3,'discipline',{title:`Этап цели: ${stage.title}`});save();renderPremium();if(stage.done)celebrate(originEl,'✓');}
  function createGoalTask(id){const goal=array('goals').find(g=>g.id===id);if(!goal)return;const stage=(goal.stages||[]).find(s=>!s.done);openRecordForm('task','',{title:goal.nextAction,date:todayKey(),status:'planned',priority:'high',goalId:goal.id,stageId:stage?.id||'',area:goal.title,note:`Следующий шаг цели «${goal.title}»`});}
  function completeGoalNextAction(id,originEl=null){const goal=array('goals').find(g=>g.id===id);if(!goal)return;const current=goal.nextAction;const stage=(goal.stages||[]).find(s=>!s.done);if(stage)stage.done=true;const nextStage=(goal.stages||[]).find(s=>!s.done);goal.nextAction=nextStage?`Сделать первый конкретный шаг этапа «${nextStage.title}» за ${Math.max(5,number(goal.actionMinutes)||15)} минут`:'Сформулировать один следующий физический шаг на 5–20 минут';goal.updatedAt=nowIso();goal.lastActivityAt=nowIso();if(nextStage&&state.settings.v86.autoCreateGoalTasks&&!array('tasks').some(t=>t.goalId===goal.id&&!taskStatusMeta(t.status).done&&clean(t.title)===clean(goal.nextAction))){state.tasks.unshift({id:makeId(),title:goal.nextAction,date:addDaysKey(todayKey(),1),status:'planned',priority:'high',goalId:goal.id,stageId:nextStage.id,area:goal.title,note:`Автоматически создано после завершения предыдущего шага`,createdAt:nowIso(),updatedAt:nowIso()});}awardGame(`goal-action:${id}:${todayKey()}:${current}`,8,2,'discipline',{title:`Шаг цели: ${current}`});save();renderPremium();toast(nextStage?'Шаг выполнен. Следующий создан автоматически.':'Шаг выполнен. Осталось определить продолжение.');celebrate(originEl,'🎯');}
  function setGoalStatus(id,status){const goal=array('goals').find(g=>g.id===id);if(!goal)return;goal.status=status;goal.updatedAt=nowIso();goal.lastActivityAt=nowIso();if(status==='done'){awardGame(`goal-done:${id}`,30,10,'discipline',{title:`Цель завершена: ${goal.title}`});celebrate(null,'🏆');}save();renderPremium();}
  function deleteGoal(id){const goal=array('goals').find(g=>g.id===id);if(!goal)return;const linked=array('tasks').filter(t=>t.goalId===id);if(!confirm(`Удалить цель «${goal.title}»? Копия сохранится в архиве.${linked.length?` Связь будет снята у ${linked.length} задач.`:''}`))return;archiveSnapshot(`Удалённая цель: ${goal.title}`,'deleted-goal',Object.assign({},goal,{linkedTasks:linked}));state.goals=array('goals').filter(g=>g.id!==id);state.tasks=array('tasks').map(task=>task.goalId===id?Object.assign({},task,{goalId:'',stageId:'',updatedAt:nowIso()}):task);save();navigate('goals');toast('Цель удалена, копия сохранена в архиве');}

  function archivePage(){
    const items=array('archive').slice().sort((a,b)=>String(b.createdAt||b.date||'').localeCompare(String(a.createdAt||a.date||'')));
    return `<section class="v78-page v821-archive-page"><header class="v78-page-head"><div><span>Резервные копии и удалённые записи</span><h1>Архив</h1><p>Здесь хранятся удалённые привычки, анкеты, записи и автоматические копии перед миграциями.</p></div><div><button class="v78-secondary" data-v78-route="information" type="button">Открыть информацию</button><button class="v78-primary" data-v78-route="calendar" type="button">Архив задач</button></div></header><section class="v821-archive-summary"><article><small>Всего записей</small><b>${items.length}</b><span>ничего не удаляется автоматически</span></article><article><small>Последнее сохранение</small><b>${items[0]?safe(formatShort(items[0].createdAt||items[0].date)):'—'}</b><span>дата последней архивной копии</span></article></section><section class="v821-archive-grid">${items.map(item=>{const original=item.original&&typeof item.original==='object'?item.original:{};const originalTitle=original.title||original.name||original.person||original.category||'';return `<article class="v821-archive-card"><header><i>▣</i><div><small>${safe(item.type||'Архивная запись')}</small><h2>${safe(item.title||originalTitle||'Без названия')}</h2></div></header><p>${safe(item.note||'Резервная копия сохранена приложением.')}</p>${originalTitle&&originalTitle!==item.title?`<div class="v821-archive-original"><small>Исходная запись</small><b>${safe(originalTitle)}</b></div>`:''}<footer><span>${safe(formatDate(item.createdAt||item.date))}</span><button data-v82-action="archive-details" data-id="${safe(item.id)}" type="button">Подробнее</button></footer></article>`}).join('')||'<div class="v78-empty-big">Архив пока пуст. Он заполнится автоматически при удалении или миграции данных.</div>'}</section></section>`;
  }
  function openArchiveDetails(id){const item=array('archive').find(x=>x.id===id);if(!item)return toast('Архивная запись не найдена');const original=item.original&&typeof item.original==='object'?item.original:null;openModal(item.title||'Архивная запись',`<div class="v821-archive-modal"><div><small>Тип</small><b>${safe(item.type||'Архив')}</b></div><div><small>Дата</small><b>${safe(formatDate(item.createdAt||item.date))}</b></div><p>${safe(item.note||'Без комментария')}</p>${original?`<details open><summary>Сохранённые данные</summary><pre>${safe(JSON.stringify(original,null,2))}</pre></details>`:''}</div><div class="v79-modal-actions"><button data-v78-action="close-modal" type="button">Закрыть</button></div>`);}
  function customPage(route) {
    const normalized = LEGACY_ALIASES[route] || route;
    if (normalized === 'today') return todayPage();
    if (normalized === 'gamelife') return gameLifePage();
    if (normalized === 'review-queue') return reviewQueuePage();
    if (normalized === 'goals') return goalsPage();
    if (normalized.startsWith('goal-')) return goalPage(decodeURIComponent(normalized.slice(5)));
    if (normalized === 'habits') return habitsPage();
    if (normalized === 'information') return informationPage();
    if (normalized === 'finance') return v869SafeFinanceRoute(()=>financePage(),'finance');
    if (normalized === 'finance-operations') return v869SafeFinanceRoute(()=>financeOperationsPage(),'finance-operations');
    if (normalized === 'finance-analytics') return v869SafeFinanceRoute(()=>financeAnalyticsPage(),'finance-analytics');
    if (normalized === 'finance-export') return v869SafeFinanceRoute(()=>financeExportPage(),'finance-export');
    if (normalized === 'finance-planning') return v869SafeFinanceRoute(()=>financePlanningPage(),'finance-planning');
    if (normalized === 'debts') return debtsPage();
    if (normalized === 'profile') return profilePage();
    if (normalized === 'habit-wishlist') return wishlistPage();
    if (normalized === 'calendar') return calendarPage();
    if (normalized === 'archive') return archivePage();
    if (normalized === 'coach') return coachPage();
    if (normalized === 'system') return systemPage();
    if (normalized === 'subconscious') return subconsciousPage();
    if (normalized === 'people') return peoplePage();
    if (normalized === 'polina') return polinaPage();
    if (normalized === 'passwords') return passwordsPage();
    if (normalized === 'books') return booksPage();
    if (ROUTE_RECORD[normalized]) return genericRecordPage(normalized);
    if (normalized.startsWith('habit-')) return habitPage(decodeURIComponent(normalized.slice(6)));
    return todayPage();
  }

  function isCustom(route) { const normalized = LEGACY_ALIASES[route] || route; return CUSTOM_ROUTES.has(route) || CUSTOM_ROUTES.has(normalized) || normalized.startsWith('habit-') || normalized.startsWith('goal-'); }

  function renderPremium() {
    clearTimeout(renderTimer);
    const route = routeNow();
    try {
      ensureData();
      if(syncAchievements()) setTimeout(()=>save(),0);
      premiumShell(customPage(route));
      afterRender();
    } catch(error) {
      console.error('[V86.9 route render]',route,error);
      try { document.body.dataset.sbosRouteError = String(error?.message || error).slice(0, 900); } catch (_) {}
      if(route!=='today'){
        try { history.replaceState(null,'','#today'); } catch(routeError) { location.hash='today'; }
        try {
          ensureData();
          premiumShell(todayPage());
          afterRender();
          setTimeout(()=>toast('Раздел временно восстановлен. Ошибка сохранена в консоли.'),50);
          return;
        } catch(fallbackError) {
          console.error('[V86.9 fallback render]',fallbackError);
        }
      }
      throw error;
    }
  }

  function afterRender() {
    setBuild();
    document.body.classList.remove('v80-booting','v79-booting','v78-booting','v70-booting','v67-theme-dark');
    document.documentElement.className='v79-light';
    document.documentElement.style.colorScheme='light';
    try { window.scrollTo(0,0); } catch(error){}
    maybePromptRoutines();
  }

  function navigate(route, options = {}) {
    const target = LEGACY_ALIASES[route] || route || 'today';
    if (options.filter) operationType = options.filter;
    closeModal();
    document.querySelectorAll('.modal.show').forEach(el=>el.classList.remove('show'));
    try { history.pushState(null,'',`#${encodeURIComponent(target)}`); } catch(error) { location.hash=target; }
    renderPremium();
  }

