  function saveHabit(id) {
    const existing = array('habits').find(item => item.id === id);
    const item = existing || { id: makeId(), marks: {}, active: true, createdAt: nowIso() };
    const name=clean(document.getElementById('v78_habit_name')?.value),minimumVersion=clean(document.getElementById('v108_habit_minimum')?.value);
    if(!name){document.getElementById('v78_habit_name')?.focus();return toast('Введите название привычки');}
    if(!existing&&!minimumVersion){document.getElementById('v108_habit_minimum')?.focus();return toast('Укажите минимальную версию на тяжёлый день');}
    item.name = name;
    item.minimumVersion = minimumVersion||existing?.minimumVersion||'';
    item.icon = clean(document.getElementById('v78_habit_icon')?.value) || '✨';
    item.color = clean(document.getElementById('v78_habit_color')?.value) || '#8b5cf6';
    item.target = Math.max(1, number(document.getElementById('v78_habit_target')?.value) || 1);
    item.unit = clean(document.getElementById('v78_habit_unit')?.value) || 'раз';
    item.frequency = clean(document.getElementById('v78_habit_frequency')?.value) || 'Ежедневно';
    item.note = clean(document.getElementById('v78_habit_note')?.value);
    const selectedGoals=new Set([...document.querySelectorAll('input[name="v865_habit_goal"]:checked')].map(el=>String(el.value)));
    state.goals=array('goals').map(goal=>{if(!goal||typeof goal!=='object')return goal;const ids=new Set(goalHabitIds(goal));if(selectedGoals.has(String(goal.id)))ids.add(String(item.id));else ids.delete(String(item.id));goal.habitIds=[...ids];goal.updatedAt=nowIso();return goal;});
    item.updatedAt = nowIso();
    if (!existing) state.habits.unshift(item);
    persist('Привычка сохранена');
    if (typeof closeModal === 'function') closeModal();
    navigate(`habit-${encodeURIComponent(item.id)}`);
  }

  function deleteHabit(id){const habit=array('habits').find(x=>x.id===id);if(!habit)return;if(!confirm(`Удалить привычку «${habit.name}»? Все отметки будут сохранены в архивной копии.`))return;archiveSnapshot(`Удалённая привычка: ${habit.name}`,'deleted-habit',habit);state.habits=array('habits').filter(x=>x.id!==id);state.goals=array('goals').map(goal=>Object.assign(goal,{habitIds:goalHabitIds(goal).filter(habitId=>habitId!==String(id)),updatedAt:nowIso()}));if(state.discipline?.activeHabit?.id===id)state.discipline.activeHabit=null;save();closeModal();navigate('habits');toast('Привычка перенесена в архив, связи с целями сняты');}

