  openFinanceCategorySettings=function(id){ensureFinanceCategories();const row=state.financeCategories.find(x=>x.id===id);if(!row)return;openModal(`Настройка · ${row.name}`,`<div class="v79-form-grid"><label class="v79-field"><span>Название</span><input id="v867_edit_name" value="${safe(row.name)}"></label><label class="v79-field"><span>Иконка из списка</span><select id="v867_edit_icon" class="v8610-icon-select">${v8610FinanceIconOptions(row.icon,row.type)}</select></label><label class="v79-field"><span>Цвет</span><input id="v867_edit_color" type="color" value="${safe(row.color||'#8b5cf6')}"></label>${row.type==='expense'?`<label class="v79-field"><span>Лимит в месяц</span><input id="v867_edit_limit" type="number" min="0" step="100" value="${number(row.monthlyLimit)||''}" placeholder="0 — без лимита"></label><label class="v79-field span-2"><span>Расход по умолчанию</span><div class="v867-expense-choice"><button class="${expenseClass(row.defaultExpenseClass)==='mandatory'?'selected mandatory':''}" data-v867-action="category-class-choice" data-value="mandatory" type="button">🛡 Обязательный</button><button class="${expenseClass(row.defaultExpenseClass)==='optional'?'selected optional':''}" data-v867-action="category-class-choice" data-value="optional" type="button">✨ Необязательный</button><input id="v867_edit_class" type="hidden" value="${expenseClass(row.defaultExpenseClass)}"></div></label>`:''}</div><div class="v79-modal-actions"><button class="v78-primary" data-v867-action="save-finance-category-settings" data-id="${safe(id)}" type="button">Сохранить</button><button data-v78-action="close-modal" type="button">Отмена</button></div>`);};


  /* V86.11 finance architecture patch */
  const V8611_TRANSFER_NAMES=new Set(['между своими счетами','между счетами','переводы','перевод','возврат','возвраты','прочие расходы','прочие движения']);
  const V8611_TRANSFER_DEFAULTS=[['Между своими счетами','⇄','#7185c6'],['Переводы','↔','#8791b8'],['Возвраты','↩','#65a8c9'],['Прочие расходы','◇','#9a92b5']];
  let v8611OperationClass='all';
  let v8611CategoryScrollState=null;
  let v8611PendingScroll='';

  function v8611NameKey(value){return clean(value).toLowerCase().replace(/ё/g,'е').replace(/\s+/g,' ');}
