  window.SecondBrainApp={getState:()=>state,setStateFromCloud:data=>{try{v8612ApplyingCloud=true;state=coreNormalize(data);window.state=state;ensureData();v8612BaseSave();renderPremium();toast('☁️ Данные синхронизированы');}finally{v8612ApplyingCloud=false;}},render:()=>renderPremium(),toast};
