    function v884SaveDebt(id=''){const creditor=clean(document.getElementById('v884_debt_creditor')?.value),balance=Math.max(0,v884Num(document.getElementById('v884_debt_balance')?.value));if(!creditor)return toast('Введите кредитора');const old=array('debts').find(x=>x.id===id),d=old||{id:makeId(),direction:'out',createdAt:nowIso()};Object.assign(d,{person:creditor,creditor,type:clean(document.getElementById('v884_debt_type')?.value)||'other',status:clean(document.getElementById('v884_debt_status')?.value)||'active',initialAmount:Math.max(0,v884Num(document.getElementById('v884_debt_initial')?.value))||balance,currentBalance:balance,amount:balance,principalBalance:Math.max(0,v884Num(document.getElementById('v884_debt_principal')?.value))||balance,accruedInterest:Math.max(0,v884Num(document.getElementById('v884_debt_interest_due')?.value)),penalties:Math.max(0,v884Num(document.getElementById('v884_debt_penalties')?.value)),interestRate:Math.max(0,v884Num(document.getElementById('v884_debt_rate')?.value)),fullCost:Math.max(0,v884Num(document.getElementById('v884_debt_full_cost')?.value)),minimumPayment:Math.max(0,v884Num(document.getElementById('v884_debt_minimum')?.value)),nextPaymentDate:v884Date(document.getElementById('v884_debt_next')?.value),due:v884Date(document.getElementById('v884_debt_next')?.value),endDate:v884Date(document.getElementById('v884_debt_end')?.value),daysOverdue:Math.max(0,Math.floor(v884Num(document.getElementById('v884_debt_overdue')?.value))),priority:Math.max(1,Math.min(5,Math.floor(v884Num(document.getElementById('v884_debt_priority')?.value)||3))),canRestructure:Boolean(document.getElementById('v884_debt_restructure')?.checked),canProlong:Boolean(document.getElementById('v884_debt_prolong')?.checked),documents:clean(document.getElementById('v884_debt_documents')?.value),note:clean(document.getElementById('v884_debt_note')?.value),lastInfoUpdate:nowIso(),updatedAt:nowIso()});if(!old)state.debts.unshift(d);v884Persist('Долг сохранён');}
    function v884OpenDebtPayment(id){const d=array('debts').find(x=>x.id===id);if(!d)return;openModal(`Платёж · ${d.creditor}`,`<div class="v79-form-grid"><label class="v79-field"><span>Дата</span><input id="v884_payment_date" type="date" value="${todayKey()}"></label><label class="v79-field"><span>Счёт списания</span><select id="v884_payment_account">${v884AccountOptions('')}</select></label><label class="v79-field"><span>Общий платёж</span><input id="v884_payment_amount" type="number" min="0" step="0.01" value="${d.minimumPayment||''}"></label><label class="v79-field"><span>Тело долга</span><input id="v884_payment_principal" type="number" min="0" step="0.01"></label><label class="v79-field"><span>Проценты</span><input id="v884_payment_interest" type="number" min="0" step="0.01"></label><label class="v79-field"><span>Штрафы</span><input id="v884_payment_penalties" type="number" min="0" step="0.01"></label><div class="v81-help-box span-2">Сумма частей должна быть равна общему платежу. Только часть «Тело долга» уменьшит основной остаток.</div></div><div class="v79-modal-actions"><button class="v78-primary" data-v884-action="save-debt-payment" data-id="${v884Esc(id)}" type="button">Сохранить платёж</button><button data-v78-action="close-modal" type="button">Отмена</button></div>`);}
    function v884SaveDebtPayment(id){const d=array('debts').find(x=>x.id===id);if(!d)return;const amount=Math.max(0,v884Num(document.getElementById('v884_payment_amount')?.value)),interest=Math.max(0,v884Num(document.getElementById('v884_payment_interest')?.value)),penalties=Math.max(0,v884Num(document.getElementById('v884_payment_penalties')?.value));let principal=Math.max(0,v884Num(document.getElementById('v884_payment_principal')?.value));if(!principal&&amount>=interest+penalties)principal=amount-interest-penalties;if(!amount)return toast('Укажите сумму платежа');if(Math.abs(amount-(principal+interest+penalties))>.01)return toast('Тело, проценты и штрафы должны быть равны общей сумме');if(principal>v884DebtBalance(d))return toast('Тело платежа больше остатка долга');const accountId=clean(document.getElementById('v884_payment_account')?.value),account=array('financeAccounts').find(a=>a.id===accountId),date=v884Date(document.getElementById('v884_payment_date')?.value)||todayKey(),stamp=nowIso();if(account&&account.actualBalance!==null){account.actualBalance=v884AccountBalance(account)-amount;account.calculatedBalance=account.actualBalance;account.updatedAt=stamp;}d.currentBalance=Math.max(0,v884DebtBalance(d)-principal);d.principalBalance=Math.max(0,v884Num(d.principalBalance)-principal);d.accruedInterest=Math.max(0,v884Num(d.accruedInterest)-interest);d.penalties=Math.max(0,v884Num(d.penalties)-penalties);d.amount=d.currentBalance;d.lastInfoUpdate=stamp;d.updatedAt=stamp;if(d.currentBalance===0){d.status='closed';d.closedAt=stamp;}const payment={id:makeId(),debtId:d.id,accountId,date,amount,principal,interest,penalties,createdAt:stamp};state.debtPayments.unshift(payment);state.operations.unshift({id:makeId(),date,type:'expense',amount,category:'Долги',expenseClass:'mandatory',account:account?.name||'',accountId,linkedDebtId:d.id,debtPaymentId:payment.id,debtPrincipal:principal,debtInterest:interest,debtPenalties:penalties,note:`Платёж ${d.creditor}: тело ${moneyText(principal)}, проценты ${moneyText(interest)}, штрафы ${moneyText(penalties)}`,createdAt:stamp,updatedAt:stamp});const total=v884CurrentBalanceFromAccounts();if(total!==null)state.settings.currentBalance=total;v884Persist('Платёж сохранён и долг пересчитан');}
    function v884OpenDebtSettings(){openModal('Стратегия погашения',`<div class="v79-form-grid"><label class="v79-field span-2"><span>Порядок</span><select id="v884_debt_strategy"><option value="urgent" ${state.settings.v884.debtStrategy==='urgent'?'selected':''}>Сначала срочные и просроченные</option><option value="rate" ${state.settings.v884.debtStrategy==='rate'?'selected':''}>Сначала дорогие по ставке</option><option value="small" ${state.settings.v884.debtStrategy==='small'?'selected':''}>Сначала самые маленькие</option><option value="custom" ${state.settings.v884.debtStrategy==='custom'?'selected':''}>Пользовательский порядок</option></select></label><label class="v79-field span-2"><span>Дополнительный платёж в месяц</span><input id="v884_debt_extra" type="number" min="0" value="${state.settings.v884.extraDebtPayment}"></label></div><div class="v79-modal-actions"><button class="v78-primary" data-v884-action="save-debt-settings" type="button">Сохранить</button><button data-v78-action="close-modal" type="button">Отмена</button></div>`);}

    function v884OpenDeferred(){openModal('Отложить покупку на 24 часа',`<div class="v79-form-grid"><label class="v79-field span-2"><span>Что хочется купить</span><input id="v884_deferred_title"></label><label class="v79-field"><span>Стоимость</span><input id="v884_deferred_amount" type="number" min="0"></label><label class="v79-field span-2"><span>Комментарий</span><textarea id="v884_deferred_note"></textarea></label></div><div class="v79-modal-actions"><button class="v78-primary" data-v884-action="save-deferred" type="button">Отложить решение</button><button data-v78-action="close-modal" type="button">Отмена</button></div>`);}
    function v884SaveDeferred(){const title=clean(document.getElementById('v884_deferred_title')?.value),amount=Math.max(0,v884Num(document.getElementById('v884_deferred_amount')?.value));if(!title||!amount)return toast('Укажите покупку и стоимость');state.deferredPurchases.unshift({id:makeId(),title,amount,note:clean(document.getElementById('v884_deferred_note')?.value),decisionAt:nowIso(),status:'waiting',createdAt:nowIso(),updatedAt:nowIso()});v884Persist('Решение отложено на 24 часа');}

