    const v884BaseOpenRecordForm=openRecordForm;
    openRecordForm=function(type,id='',preset={}){if(type==='debt')return v884OpenDebt(id);v884BaseOpenRecordForm(type,id,preset);if(type==='operation'){
      const item=id?array('operations').find(x=>x.id===id)||{}:preset||{},grid=document.querySelector('#modal .v79-form-grid');if(!grid||grid.querySelector('[data-v884-impulse-fields]'))return;
      const extrasHost=grid.querySelector('[data-v108-advanced="operation"] .v108-advanced-body')||grid;
      extrasHost.insertAdjacentHTML('beforeend',`<details data-v884-impulse-fields class="v108-analysis-details span-2"><summary><span>Разобрать покупку</span><small>Эмоция, триггер и полезность</small></summary><div class="v884-impulse-fields"><label class="v79-field"><span>Покупка была запланирована?</span><select id="v79_f_plannedPurchase"><option value="">Не указано</option><option value="yes" ${item.plannedPurchase==='yes'?'selected':''}>Да</option><option value="no" ${item.plannedPurchase==='no'?'selected':''}>Нет</option><option value="partial" ${item.plannedPurchase==='partial'?'selected':''}>Частично</option></select></label><label class="v79-field"><span>Эмоция</span><input id="v79_f_emotion" value="${v884Esc(item.emotion||'')}" placeholder="Стресс, скука, радость"></label><label class="v79-field"><span>Триггер</span><input id="v79_f_impulseTrigger" value="${v884Esc(item.impulseTrigger||'')}"></label><label class="v79-field"><span>Причина</span><input id="v79_f_impulseReason" value="${v884Esc(item.impulseReason||'')}"></label><label class="v79-field"><span>Необходимость</span><select id="v79_f_necessary"><option value="">Не указано</option><option value="yes" ${item.necessary==='yes'?'selected':''}>Необходима</option><option value="no" ${item.necessary==='no'?'selected':''}>Необязательна</option></select></label><label class="v79-field"><span>Можно было отложить на 24 часа?</span><select id="v79_f_couldWait24"><option value="">Не указано</option><option value="yes" ${item.couldWait24==='yes'?'selected':''}>Да</option><option value="no" ${item.couldWait24==='no'?'selected':''}>Нет</option></select></label><label class="v79-field"><span>Полезность 1–10</span><input id="v79_f_usefulness" type="number" min="1" max="10" value="${item.usefulness||''}"></label></div></details>`);
    }};
    const v884BaseSaveRecord=saveRecord;
    saveRecord=function(type,id,originEl=null){if(originEl?.dataset.v884Busy)return;const extras=type==='operation'?{plannedPurchase:clean(document.getElementById('v79_f_plannedPurchase')?.value),emotion:clean(document.getElementById('v79_f_emotion')?.value),impulseTrigger:clean(document.getElementById('v79_f_impulseTrigger')?.value),impulseReason:clean(document.getElementById('v79_f_impulseReason')?.value),necessary:clean(document.getElementById('v79_f_necessary')?.value),couldWait24:clean(document.getElementById('v79_f_couldWait24')?.value),usefulness:Math.max(0,v884Num(document.getElementById('v79_f_usefulness')?.value))}:null;const before=new Set(array('operations').map(o=>o.id));if(originEl)originEl.dataset.v884Busy='1';try{const result=v884BaseSaveRecord(type,id,originEl);if(type==='operation'&&extras){const item=id?array('operations').find(o=>o.id===id):array('operations').find(o=>!before.has(o.id));if(item){Object.assign(item,extras,{updatedAt:nowIso()});save();}}return result;}finally{setTimeout(()=>{if(originEl)delete originEl.dataset.v884Busy;},700);}};

