  function hardenModal(){const root=modal();if(!root)return;const open=root.classList.contains('show');document.documentElement.classList.toggle('sbos-v90-modal-open',open);document.body.classList.toggle('sbos-v90-modal-open',open);root.setAttribute('aria-hidden',open?'false':'true');root.querySelectorAll('input,textarea,select').forEach(field=>{field.style.pointerEvents='auto';field.removeAttribute('aria-disabled');field.removeAttribute('inert');if(field.hasAttribute('disabled')&&!field.dataset.disabledReason)field.removeAttribute('disabled');if(field.hasAttribute('readonly')&&!field.dataset.readonlyReason)field.removeAttribute('readonly');if(field.tabIndex<0)field.tabIndex=0});enhanceTaskModal();if(open){if(!modalOpener&&document.activeElement instanceof HTMLElement)modalOpener=document.activeElement;requestAnimationFrame(()=>{const active=document.activeElement;if(!root.contains(active)||active===root){const first=root.querySelector('input:not([type="hidden"]),textarea,select,button');safe(first?.focus?.bind(first),{preventScroll:true})}})}else if(modalOpener){safe(modalOpener.focus?.bind(modalOpener),{preventScroll:true});modalOpener=null}}
