  function decorateCalendar(){const page=document.querySelector('.v82-calendar-page');if(!page)return;const heads=[...page.querySelectorAll('.v82-week-head>button[data-date]')];page.querySelectorAll('.v82-week-column').forEach((col,index)=>{if(heads[index]?.dataset.date)col.dataset.sbosV90Date=heads[index].dataset.date});page.querySelectorAll('.v82-month-calendar article').forEach(article=>{const day=article.querySelector('[data-date]');if(day?.dataset.date)article.dataset.sbosV90Date=day.dataset.date});page.querySelectorAll('.v82-time-row').forEach(row=>{const time=row.querySelector('time')?.textContent?.trim();if(time)row.dataset.sbosV90Time=time});page.querySelectorAll('.v82-calendar-event').forEach(card=>{const task=calendarTask(card);if(!task)return;card.draggable=true;card.dataset.sbosTaskId=task.id;card.setAttribute('aria-grabbed','false');const open=card.querySelector('.v82-event-open');if(open)open.title=task.title||'Событие';let duration=open?.querySelector('.sbos-v90-duration');if(task.durationMinutes&&!duration){duration=document.createElement('span');duration.className='sbos-v90-duration';duration.textContent=`${task.durationMinutes} мин`;open?.appendChild(duration)}})}
