  function showUndo(task,index,archiveId){clearTimeout(undoTimer);document.querySelector('.sbos-v90-undo')?.remove();const box=document.createElement('div');box.className='sbos-v90-undo';box.innerHTML=`<span>Событие «${esc(task.title||'Без названия')}» удалено</span><button type="button">Отменить</button>`;document.body.appendChild(box);box.querySelector('button').onclick=()=>{const s=state();s.tasks=Array.isArray(s.tasks)?s.tasks:[];if(!s.tasks.some(t=>String(t.id)===String(task.id)))s.tasks.splice(Math.min(index,s.tasks.length),0,task);if(Array.isArray(s.archive))s.archive=s.archive.filter(a=>a.id!==archiveId);box.remove();persist('Событие восстановлено')};undoTimer=setTimeout(()=>box.remove(),9000)}
  function deleteTask(id){const s=state(),list=Array.isArray(s.tasks)?s.tasks:[],index=list.findIndex(t=>String(t.id)===String(id));if(index<0)return;const task=clone(list[index]);if(!confirm(`Удалить событие «${task.title||'Без названия'}»?`))return;const archiveId=`v90-task-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;s.archive=Array.isArray(s.archive)?s.archive:[];s.archive.unshift({id:archiveId,title:`Удалённое событие: ${task.title||'Без названия'}`,type:'deleted-task',date:new Date().toISOString().slice(0,10),createdAt:new Date().toISOString(),note:'Автоматическая копия перед удалением из календаря',original:task});s.tasks.splice(index,1);safe(window.closeModal);const root=document.getElementById('modal');if(root){root.classList.remove('show');root.style.display='';root.style.visibility='';root.setAttribute('aria-hidden','true')}document.documentElement.classList.remove('sbos-v90-modal-open','sbos-modal-open');document.body.classList.remove('sbos-v90-modal-open','sbos-modal-open');persist('Событие удалено');showUndo(task,index,archiveId);setTimeout(()=>{const modalRoot=document.getElementById('modal');modalRoot?.classList.remove('show');document.documentElement.classList.remove('sbos-v90-modal-open','sbos-modal-open');document.body.classList.remove('sbos-v90-modal-open','sbos-modal-open')},0)}
  function updateIncomeAllocation(){
    const ids=['v884_alloc_debt','v884_alloc_reserve','v884_alloc_free'];
    if(!ids.every(id=>document.getElementById(id)))return;
    const values=ids.map(id=>Math.max(0,Number(document.getElementById(id)?.value)||0));
    const total=Math.round(values.reduce((sum,value)=>sum+value,0)*100)/100;
    const label=document.getElementById('v884_income_allocation_total');
    const error=document.getElementById('v884_income_allocation_error');
    if(label){label.textContent=`${total}%`;label.dataset.state=total>100?'error':total===100?'ok':'pending';}
    if(error){error.textContent=total>100?'Сумма превышает 100%. Уменьшите один из процентов.':total<100&&total>0?`Оставшиеся ${Math.round((100-total)*100)/100}% автоматически пойдут в свободные деньги при сохранении.`:total===0?'Укажите распределение сверх гарантированного дохода.':'';error.hidden=!error.textContent;}
  }

  function decorateIncomeSettings(){
    const root=document.getElementById('modal');
    if(!root?.classList.contains('show')||!document.getElementById('v884_alloc_debt'))return;
    updateIncomeAllocation();
  }

